head.script:
//
/* ============================================================
   Callango Nerd - Lazy Load Engine (v3)
   Motor moderno baseado em IntersectionObserver.
   Compatível com a API legada: defer, deferimg, deferscript,
   deferstyle. Também observa iframes, vídeos, áudios, elementos
   com data-bg e nós adicionados dinamicamente (AJAX / infinite
   scroll) via MutationObserver.
   ============================================================ */
(function (win, doc) {
  "use strict";

  var IO = win.IntersectionObserver;
  var LAZY_MARK = "data-lazied";
  var OBSERVER = null;
  var PENDING_CBS = {}; // seletor -> callback

  // ---- API legada: defer(fn, delay) --------------------------
  function defer(fn, delay) {
    if (typeof fn !== "function") return;
    if (doc.readyState === "complete" || doc.readyState === "interactive") {
      win.setTimeout(fn, delay || 0);
    } else {
      doc.addEventListener("DOMContentLoaded", function () {
        win.setTimeout(fn, delay || 0);
      });
    }
  }
  win.defer = defer;

  // ---- deferscript / deferstyle ------------------------------
  win.deferscript = function (url, id, delay, onload) {
    defer(function () {
      if (id && doc.getElementById(id)) return;
      var s = doc.createElement("script");
      if (id) s.id = id;
      s.src = url;
      if (onload) s.onload = onload;
      doc.head.appendChild(s);
    }, delay);
  };
  win.deferstyle = function (url, id, delay) {
    defer(function () {
      if (id && doc.getElementById(id)) return;
      var l = doc.createElement("link");
      if (id) l.id = id;
      l.rel = "stylesheet";
      l.href = url;
      doc.head.appendChild(l);
    }, delay);
  };

  // ---- Swap data-* -> atributos reais ------------------------
  function reveal(el, doneClass, cb) {
    if (el.getAttribute(LAZY_MARK)) return;
    el.setAttribute(LAZY_MARK, "1");

    ["src", "srcset", "poster", "style"].forEach(function (a) {
      var v = el.getAttribute("data-" + a);
      if (v) el.setAttribute(a, v);
    });
    var bg = el.getAttribute("data-bg");
    if (bg) el.style.backgroundImage = "url('" + bg + "')";

    // <picture><source data-srcset>
    var sources = el.querySelectorAll && el.querySelectorAll("source[data-srcset], source[data-src]");
    if (sources && sources.length) {
      Array.prototype.forEach.call(sources, function (s) {
        var ss = s.getAttribute("data-srcset");
        var sr = s.getAttribute("data-src");
        if (ss) s.setAttribute("srcset", ss);
        if (sr) s.setAttribute("src", sr);
      });
    }

    if (typeof el.load === "function") { try { el.load(); } catch (e) {} }

    el.classList.add(doneClass || "lazied");
    el.classList.add("shown");
    el.classList.remove("bgblur");

    if (typeof cb === "function") { try { cb.call(el, el); } catch (e) {} }
  }

  // ---- Observer central --------------------------------------
  function ensureObserver() {
    if (OBSERVER || !IO) return OBSERVER;
    OBSERVER = new IO(function (entries) {
      entries.forEach(function (entry) {
        if (!entry.isIntersecting) return;
        var el = entry.target;
        OBSERVER.unobserve(el);
        var cfg = el.__lz || {};
        reveal(el, cfg.doneClass, cfg.cb);
      });
    }, { rootMargin: "200px 0px", threshold: 0.01 });
    return OBSERVER;
  }

  function observe(el, doneClass, cb) {
    if (!el || el.getAttribute(LAZY_MARK)) return;
    el.__lz = { doneClass: doneClass, cb: cb };
    var obs = ensureObserver();
    if (obs) obs.observe(el);
    else reveal(el, doneClass, cb); // fallback: sem IO, carrega já
  }

  // ---- Coletor de alvos --------------------------------------
  function collect(selector) {
    var list = [];
    var sel = selector ||
      "img[data-src], img[data-srcset], img.lazyload," +
      "iframe[data-src], video[data-src], audio[data-src]," +
      "source[data-src], source[data-srcset]," +
      "[data-bg]";
    try {
      list = Array.prototype.slice.call(doc.querySelectorAll(sel));
    } catch (e) {}
    return list.filter(function (el) { return !el.getAttribute(LAZY_MARK); });
  }

  // ---- API pública: deferimg(selector, delay, doneClass, cb) --
  function deferimg(selector, delay, doneClass, cb) {
    PENDING_CBS[selector || "*"] = { doneClass: doneClass, cb: cb };
    defer(function () {
      collect(selector).forEach(function (el) { observe(el, doneClass, cb); });
    }, delay);
  }
  win.deferimg = deferimg;
  win.deferiframe = deferimg;

  // ---- Varredura genérica + AJAX-friendly --------------------
  function scanAll() {
    Object.keys(PENDING_CBS).forEach(function (sel) {
      var cfg = PENDING_CBS[sel];
      collect(sel === "*" ? null : sel).forEach(function (el) {
        observe(el, cfg.doneClass, cfg.cb);
      });
    });
    // fallback amplo caso ninguém tenha registrado deferimg
    collect().forEach(function (el) { observe(el); });
  }

  // Primeira varredura assim que o DOM estiver pronto.
  defer(scanAll, 0);

  // Novo evento para forçar re-scan após conteúdo dinâmico.
  win.addEventListener("cn:lazyrefresh", scanAll);

  // MutationObserver: pega imagens injetadas via AJAX/infinite scroll.
  if (win.MutationObserver) {
    var mo = new MutationObserver(function (muts) {
      var needs = false;
      for (var i = 0; i < muts.length && !needs; i++) {
        if (muts[i].addedNodes && muts[i].addedNodes.length) needs = true;
      }
      if (needs) scanAll();
    });
    defer(function () {
      mo.observe(doc.body, { childList: true, subtree: true });
    }, 0);
  }

  // Compat: defer.all = noop (o motor antigo processava scripts type=deferjs)
  defer.all = function () {};
})(this, document);
//

head.b:skin:

/* -----------------------------------------------
Blogger Template Style
Template: Callango Nerd
Autor: Marcio Oliveira
https://instagram.com/marciooliveiradesign/
----------------------------------------------- */

@import url('https://fonts.googleapis.com/css2?family=Outfit:wght@100..900&display=swap');
/*
<!-- Variable definitions -->
<Variable name="keycolor" description="Main Color" type="color" default="$(main.color)" value="#ff0000"/>
<Variable name="followByEmail" description="Follow By Email Text" type="string" default="Get all latest content delivered straight to your inbox." value="Get all latest content delivered straight to your inbox."/>

<Group description="Theme Colors" selector="body">
 <Variable name="main.color" description="Theme Color" type="color" default="#ff0000" value="#ff0000"/>
  <Variable name="title.color" description="Title Color" type="color" default="#060d17" value="#060d17"/>
  <Variable name="header.color" description="Header Color" type="color" default="$(title.color)" value="#060d17"/>
  <Variable name="footer.color" description="Footer Color" type="color" default="#ffffff" value="#ffffff"/>
  <Variable name="footer.link" description="Footer Link" type="color" default="#ff0000" value="#ff0000"/>
</Group>

<Group description="Dark Mode" selector="body">
<Variable name="body.dark.color" description="Body Color" type="color" default="#060d17" value="#060d17"/>
 <Variable name="main.dark.color" description="Theme Color" type="color" default="#0c131e" value="#0c131e"/>
<Variable name="title.dark.color" description="Title Dark Color" type="color" default="#fff" value="#ffffff"/>
</Group>

<Group description="Theme Body" selector="body">
  <Variable name="body.background.color" description="Body Background Color" type="color" default="$(footer.color)"  value="#ffffff"/>
<Variable name="body.font" description="Text Font" type="font" default="18px Outfit, sans-serif" value="18px Outfit, sans-serif"/>
  <Variable name="body.background" description="Background" type="background" color="$(body.background.color)" default="$(color) url() repeat fixed top left" value="$(color) url() repeat fixed top left"/>
  <Variable name="body.text.color" description="Text Color" type="color" default="#060d17"  value="#060d17"/>
  <Variable name="body.link.color" description="Link Color" type="color" default="#ff0000"  value="#ff0000"/>
</Group>

<Variable name="body.text.font" description="Font" hideEditor="true" type="font" default="$(body.font)"  value="16px Outfit, sans-serif"/>
<Variable name="posts.background.color" description="Post background color" hideEditor="true" type="color" default="$(footer.color)"  value="#ffffff"/>
<Variable name="tabs.font" description="Font 2" hideEditor="true" type="font" default="16px Outfit, sans-serif"  value="16px Outfit, sans-serif"/>
<Variable name="posts.title.color" description="Post title color" hideEditor="true" type="color" default="#222222"  value="#222222"/>
<Variable name="posts.text.color" description="Post text color" hideEditor="true" type="color" default="#777"  value="#777777"/>
<Variable name="posts.icons.color" description="Post icons color" hideEditor="true" type="color" default="$(main.color)"  value="#ff0000"/>
<Variable name="labels.background.color" description="Label background color" hideEditor="true" type="color" default="#ff0000"  value="#ff0000"/>
*/
/*CSS*/
@font-face{font-family:Anton;font-style:normal;font-weight:400;font-display:swap;src:url(https://fonts.gstatic.com/s/anton/v12/1Ptgg87LROyAm3Kz-C8.woff2) format('woff2')}
@font-face{font-family:'Material Icons';font-style:normal;font-weight:400;font-display:swap;src:url(https://fonts.gstatic.com/s/materialicons/v53/flUhRq6tzZclQEJ-Vdg-IuiaDsNc.woff2) format('woff2');font-display:swap}
dl,ul,ul li{list-style:none}
a,a:visited,abbr{text-decoration:none}
.center,img{position:relative}
 :after, :before{-webkit-box-sizing:border-box;-moz-box-sizing:border-box;box-sizing:border-box}
.CSS_LIGHTBOX_ATTRIBUTION_INDEX_CONTAINER .CSS_HCONT_CHILDREN_HOLDER>.CSS_LAYOUT_COMPONENT.CSS_HCONT_CHILD:first-child>.CSS_LAYOUT_COMPONENT{opacity:0}
a,abbr,acronym,address,applet,b,big,blockquote,body,caption,center,cite,code,dd,del,dfn,div,dl,dt,em,fieldset,font,form,h1,h2,h3,h4,h5,h6,html,i,iframe,img,ins,kbd,label,legend,li,object,p,pre,q,s,samp,small,span,strike,strong,sub,sup,table,tbody,td,tfoot,th,thead,tr,tt,u,ul,var{padding:0;outline:0;vertical-align:baseline;background:0;text-decoration:none}
button,form,input,textarea{-webkit-appearance:none;-moz-appearance:none;appearance:none;-webkit-border-radius:0;-moz-border-radius:0;border-radius:0}dl,ul{font-weight:400}ul li{margin-bottom:10px}caption,th{text-align:center}img{border:none;width:auto;height:auto;max-width:100%}.clr{clear:both}.section,.widget,.widget ul{margin:0;padding:0}a{color:$(footer.link)}a img{border:0}
*:before,*:after{-webkit-box-sizing:border-box;-moz-box-sizing:border-box;box-sizing:border-box;}
.CSS_LIGHTBOX{z-index:999999!important}
.separator a{clear:none!important;float:none!important;margin-left:0!important;margin-right:0!important}
#navbar-iframe,.feed-links,.home-link,.menu-wrapper h3,.widget-item-control,a.quickedit{display:none!important}
.center{display:table;margin:0 auto}
.custom-css,.add-javascript,.widget>h2,.widget>h3,.page-error #sidebar-wrapper{display:none}
.page-error #main-wrapper{width:100%!important;margin:0!important}
body.no-sidebar #sidebar-wrapper{display:none!important}
body.no-sidebar #main-wrapper{float:none!important;width:69%!important;max-width:69%!important;margin:0 auto!important;padding:0 10px!important}
#main-wrapper,#sidebar-wrapper{overflow:hidden;box-sizing:border-box;word-wrap:break-word}
#main-wrapper,#sidebar-wrapper,body{word-wrap:break-word}
body{background-color:#060d17;font:$(body.font);color:$(body.text.color);font-weight:300;line-height:1.7em;margin:0;padding:0}
#outer-wrapper{margin:-32px auto;}
.row{    width:100%}#content-wrapper{margin:-32px auto;}
.img-wrapper,.post-title a{display:block}
#content-wrapper>.container,.container{margin:0px auto}
#main-wrapper{float:left;width:69%;padding: 0px 0px 0px 10px;margin:0}
#sidebar-wrapper{float:right;width:30%;padding:0 0 0 20px;position:-webkit-sticky;position:sticky;top:4rem}
 #wraplist{   border-radius: 0!important;}
.comments .avatar-image-container{color:transparent!important}
