#menu{       position: relative;
    z-index: 999;
    color: #060d17;
    font-weight: 800;
    float: left;
    top: 20px;
    left: 8%;
    margin-left: 0;
    margin-right: 0;}
#menu li,#menu ul{margin:0;padding:0;list-style:none}
