.js-loaded{cursor:no-drop}
.blog-pager .js-load,.blog-pager .js-loaded,.blog-pager .js-loading{display:block;margin:20px auto 0;height:auto;border:0;color:$(footer.color);float:none;text-align:center;background: #111924;-webkit-border-radius:15px;-moz-border-radius:4px;border-radius:4px;padding:8px 20px;-webkit-transition:all .2s;transition:all .2s}
