.FollowByEmail .widget-content{position:relative;overflow:hidden;background-color:$(title.color);text-align:center;font-weight:400;box-sizing:border-box;padding:20px}
.FollowByEmail .widget-content>h3{font-size:18px;color:$(footer.color);font-weight:700;text-transform:uppercase;margin:0 0 13px}
.FollowByEmail .before-text{font-size:13px;color:#aaa;line-height:1.5em;margin:0 0 15px;display:block;padding:0 10px;overflow:hidden}
.FollowByEmail .follow-by-email-inner{position:relative}
.FollowByEmail .follow-by-email-inner .follow-by-email-address{width:100%;height:32px;color:$(title.color);font-size:11px;font-family:inherit;padding:0 10px;margin:0 0 10px;box-sizing:border-box;border:0;-webkit-border-radius:3px;-moz-border-radius:3px;border-radius:3px;-webkit-transition:all .17s;-moz-transition:all .17s;-ms-transition:all .17s;-o-transition:all .17s;transition:all .17s}
.FollowByEmail .follow-by-email-inner .follow-by-email-submit{width:100%;height:32px;font-family:inherit;font-size:11px;color:$(footer.color);background-color:$(main.color);text-transform:uppercase;text-align:center;font-weight:700;cursor:pointer;margin:0;border:0;-webkit-border-radius:3px;-moz-border-radius:3px;border-radius:3px;-webkit-transition:all .17s ease;-moz-transition:all .17s ease;-ms-transition:all .17s ease;-o-transition:all .17s ease;transition:all .17s ease}
.FollowByEmail .follow-by-email-inner .follow-by-email-submit:hover{opacity:.85}
#ArchiveList ul.flat li{color:$(title.color);margin:0;font-weight:400;padding:15px 0;border-bottom:1px solid rgba(255,255,255,.1)}
#ArchiveList ul.flat li:first-child{padding-top:0}
#ArchiveList ul.flat li:last-child{padding-bottom:0;border-bottom:0}
#ArchiveList .flat li>a{display:block;color:$(title.color)}
#ArchiveList .flat li>a:hover{color:$(main.color)}
#ArchiveList .flat li>a>span{position:relative;float:right;height:16px;color:$(main.color);font-size:11px;font-weight:400;text-align:center;line-height:16px;padding:0 5px}
.FeaturedPost .img-khusus{display:block;position:relative;width:100%;height:450px;overflow:hidden;margin:0 auto}
.FeaturedPost .overlay{position:absolute;z-index:6;top:0;width:100%;height:100%;background:#000;opacity:.5}
#footer-menu,#footer-menu ul li a,.footer .widget>.widget-title>h3,.footer-box{position:relative}
.FeaturedPost .post-title{font-size:22px;overflow:hidden;font-weight:600;line-height:1.5em;margin:25px 0;color:$(footer.color)}
.contact-form-button-submit,.contact-form-email,.contact-form-name{height:30px;line-height:30px}
.contact-form-email,.contact-form-email-message,.contact-form-name{padding:5px 10px;margin:0 0 10px;border:1px solid #ebebeb;float:left;width:100%;font-size:13px;box-sizing:border-box;font-family:inherit}
.FeaturedPost .post-title a{color:$(footer.color);display:block}
.FeaturedPost .post-title a:hover{color:#ddd}
.BlogSearch .search-action,.contact-form-button-submit{cursor:pointer;color:$(footer.color);-webkit-transition:background .17s ease;-moz-transition:background .17s ease;-ms-transition:background .17s ease;-o-transition:background .17s ease;transition:background .17s ease}
.contact-form-widget form{font-weight:400}
.contact-form-button-submit{float:left;width:100%;background-color:$(main.color);font-size:13px;box-sizing:border-box;padding:0 10px;margin:0;border:0}
.contact-form-error-message-with-border,.contact-form-success-message-with-border{width:100%;font-size:11px;text-align:center;line-height:11px;padding:3px 0;margin:10px 0;float:left}
.contact-form-button-submit:hover{background-color:$(title.color)}
.contact-form-error-message-with-border{background-color:#fbe5e5;box-sizing:border-box;border:1px solid #fc6262}
.contact-form-success-message-with-border{background-color:#eaf6ff;box-sizing:border-box;border:1px solid #5ab6f9}
.BlogSearch .search-action,.BlogSearch .search-input{height:30px;font-size:13px;line-height:30px;box-sizing:border-box}
.contact-form-cross{margin:0 0 0 3px}
.contact-form-error-message,.contact-form-success-message{margin:0}
.BlogSearch .search-input{float:left;width:75%;background-color:#0c131e;font-weight:400;padding:5px 10px;border:1px solid #ebebeb;border-right-width:0}
.BlogSearch .search-action{float:right;width:25%;font-family:inherit;background-color:$(main.color);padding:0 5px;border:0}
.BlogSearch .search-action:hover{background-color:$(title.color)}
.Profile .profile-img{float:left;width:80px;height:80px;margin:0 15px 0 0;-webkit-transition:all .17s ease;-moz-transition:all .17s ease;-ms-transition:all .17s ease;-o-transition:all .17s ease;transition:all .17s ease}
.Profile .profile-datablock{margin:0}
.Profile .profile-data .g-profile{display:block;font-size:14px;color:$(title.color);margin:0 0 5px}
.Profile .profile-data .g-profile:hover{color:$(main.color)}
.Profile .profile-info>.profile-link{color:$(title.color);font-size:11px;margin:5px 0 0}
.Profile .profile-info>.profile-link:hover{color:$(main.color)}
.Profile .profile-datablock .profile-textblock{display:none}
.common-widget .LinkList ul li,.common-widget .PageList ul li{width:calc(50% - 5px);padding:7px 0 0}
.common-widget .LinkList ul li:nth-child(odd),.common-widget .PageList ul li:nth-child(odd){float:left}
.common-widget .LinkList ul li:nth-child(even),.common-widget .PageList ul li:nth-child(even){float:right}
.common-widget .LinkList ul li a,.common-widget .PageList ul li a{display:block;color:$(title.color);font-size:13px;font-weight:400}
.common-widget .LinkList ul li a:hover,.common-widget .PageList ul li a:hover{color:$(main.color)}
.common-widget .LinkList ul li:first-child,.common-widget .LinkList ul li:nth-child(2),.common-widget .PageList ul li:first-child,.common-widget .PageList ul li:nth-child(2){padding:0}
#footer-wrapper{background-color:#0c131e;overflow:hidden;border-top:4px solid #edf3f3}
#footer-wrapper .container{position:relative;overflow:hidden;margin:0 auto;padding:25px 0 0}
.footer-box{display: block;
    overflow: hidden;
    max-width: 1705px; margin: 0px auto 30px;
    margin: 0px auto 30px;
}
#footer-wrapper .footer{display:inline-block;float:left;width:33.333%;box-sizing:border-box;padding:0 15px}
#footer-wrapper .footer p{font-size:15px}
#footer-wrapper .footer .widget-title{margin:0 0 20px}
#footer-wrapper .footer-logo{width:250px;height:auto}
#footer-wrapper .footer .widget{float:left;width:100%;padding:0;margin:25px 0 0}
#footer-wrapper .footer .widget:first-child{margin:0}
#footer-bottom .credit,#footer-menu ul li a{font-size:15px;line-height:34px;font-weight:400;color:#fff}
.footer .img-khusus{border-color:rgba(255,255,255,.1);width:100px;height:70px}
.footer .img-khusus:hover{border-color:$(main.color)}
.footer .FeaturedPost .post-title a,.footer .LinkList ul li a,.footer .PageList ul li a,.footer .Profile .profile-data .g-profile,.footer .Profile .profile-info>.profile-link{color:$(title.color)}
.footer .FeaturedPost .post-title a:hover,.footer .LinkList ul li a:hover,.footer .PageList ul li a:hover{color:$(footer.link)}
.footer #ArchiveList .flat li>a,.footer #ArchiveList .flat li>a:before,.footer .FollowByEmail .widget-content>h3,.footer .list-label li a,.footer .list-label li a:before{color:$(footer.color)}
.footer .FollowByEmail .widget-content{background-color:rgba(255,255,255,.05);border-color:rgba(255,255,255,.05)}
.footer .FollowByEmail .follow-by-email-inner .follow-by-email-submit:hover{background:#ff2aff}
.footer .FollowByEmail .follow-by-email-inner .follow-by-email-address{background-color:rgba(255,255,255,.05);color:$(footer.color);border-color:rgba(255,255,255,.05)}
.footer .BlogArchive #ArchiveList ul.flat li,.footer .list-label li{border-color:rgba(255,255,255,.05)}
.footer .list-label li:first-child{padding-top:0}
.footer #ArchiveList .flat li>a:hover,.footer .list-label li>a:hover{color:$(main.color)}
.footer #ArchiveList .flat li>a>span,.footer .list-label .label-count{background-color:rgba(255,255,255,.05);color:$(footer.color)}
.footer .cloud-label li a{color:$(footer.color)}
.footer .cloud-label li a:hover{color:$(main.color)}
.footer .BlogSearch .search-input,.footer .contact-form-email,.footer .contact-form-email-message,.footer .contact-form-name{background-color:rgba(255,255,255,.05);color:$(footer.color);border-color:rgba(255,255,255,.05)}
.footer .BlogSearch .search-action:hover,.footer .FollowByEmail .follow-by-email-inner .follow-by-email-submit:hover,.footer .contact-form-button-submit:hover{background-color:rgba(0,0,0,.3)}
#footer-bottom{display: block;
    padding: 20px 76px;
    overflow: hidden;
    border-top: 1px dotted rgb(7 5 18);
    WIDTH: 90%;
    max-width: 1260px;
