/* =========================================================
   PATCH MOBILE — carrossel topo (slidesone) e main-carousel
   Corrige imagens sumindo no mobile e melhora alinhamento.
   ========================================================= */
@media (max-width: 900px){
  .slidesone .carousel-item .box-image{
    background-position: center center !important;
    background-position-y: center !important;
    background-size: cover !important;
    box-shadow: inset 0 -120px 90px -40px #0c131e !important;
  }
  .slidesone, .slidesone .carousel-item { min-height: 260px; }
  .slidesone .owl-stage-outer, .slidesone .owl-stage,
  .slidesone .owl-item { height: 100% !important; }
  .slidesone .carousel-content{
    bottom: 1.2rem !important;
    padding: 0 14px !important;
  }
  .slidesone .carousel-item .recent-title a{
    font-size: 16px !important;
    line-height: 1.3 !important;
    -webkit-line-clamp: 3;
  }
  .main-carousel .carousel-item{
    flex-direction: column !important;
    align-items: stretch !important;
    padding: 10px !important;
  }
  .main-carousel .carousel-item .slide-image{
    height: 200px !important;
    width: 100% !important;
  }
  .main-carousel .carousel-item .carousel-content{
    width: 100% !important;
    padding: 12px 4px 4px !important;
  }
  .main-carousel .owl-prev, .main-carousel .owl-next{
    opacity: 1 !important;
  }
}
@media (max-width: 600px){
  .slidesone, .slidesone .carousel-item { min-height: 230px; height: 230px !important; }
  .slide_top{ margin: -20px auto 20px !important; }
}
/* Modal card (trend-news / news modal) — alinhamento mobile */
@media (max-width: 720px){
  .trend-news-modal-card,
  .news-modal-card,
  .modal-card{
    display: flex !important;
    flex-direction: column !important;
    gap: 10px !important;
    padding: 14px !important;
    border-radius: 14px !important;
  }
  .trend-news-modal-card img,
  .news-modal-card img,
  .modal-card img{
    width: 100% !important;
    height: auto !important;
    border-radius: 10px !important;
    display: block;
  }
  .trend-news-modal-card .meta,
  .news-modal-card .meta,
  .modal-card .meta{
    display: flex; flex-wrap: wrap; gap: 6px 10px;
    font-size: 12px; opacity: .8;
  }
  .trend-news-modal-card h3,
  .news-modal-card h3,
  .modal-card h3{ font-size: 17px; line-height: 1.25; margin: 4px 0 2px; }
  .trend-news-modal-card .comments-list,
  .news-modal-card .comments-list{ margin-top: 8px; }
  .trend-news-modal-card .comment,
  .news-modal-card .comment{
    display: grid;
    grid-template-columns: 36px 1fr auto;
    gap: 8px;
    align-items: start;
    padding: 8px 0;
    border-bottom: 1px solid rgba(255,255,255,.08);
  }
  .trend-news-modal-card .comment .avatar,
  .news-modal-card .comment .avatar{
    width:36px;height:36px;border-radius:50%;object-fit:cover;
  }
  .trend-news-modal-card .comment .body,
  .news-modal-card .comment .body{ min-width: 0; }
  .trend-news-modal-card .comment .body p,
  .news-modal-card .comment .body p{ margin:2px 0 0; font-size:14px; word-wrap:break-word; }
  .trend-news-modal-card .comment .delete-comment,
  .news-modal-card .comment .delete-comment{
    background:#f30;color:#fff;border:0;border-radius:6px;
    padding:4px 8px;font-size:12px;cursor:pointer;
  }
}

/* =========================================================
   CN-PROFILE-REDESIGN — Layout moderno para páginas de
   perfil (ator / filme) em posts individuais. Usa a paleta
   nativa do tema: $(main.color), $(title.color), $(body.background.color).
   Escopo: body.item-view (post individual do Blogger).
   ========================================================= */
body.item-view #main-wrapper{background:transparent}
body.item-view .post-outer{
  position:relative;
  background:$(posts.background.color);
  border-radius:22px;
  overflow:hidden;
  box-shadow:0 30px 80px -40px rgba(6,13,23,.35), 0 2px 6px rgba(6,13,23,.06);
  border:1px solid rgba(6,13,23,.06);
}
body.item-view .post-outer:before{
  content:"";
  position:absolute;left:0;right:0;top:0;height:280px;
  background:
    radial-gradient(1200px 280px at 20% 0%, color-mix(in srgb,$(main.color) 22%, transparent), transparent 60%),
    linear-gradient(135deg,$(title.color) 0%,#0c131e 55%,$(main.color) 130%);
  z-index:0;
}
body.item-view .post{position:relative;z-index:1;padding:0}
body.item-view .post .post-header{
  padding:180px 40px 28px;
  display:flex;flex-direction:column;gap:14px;
}
body.item-view .post .post-title,
body.item-view .post h1.post-title,
body.item-view .post h1.entry-title{
  font-family:Outfit,sans-serif;
  font-weight:800;
  font-size:clamp(28px,4vw,46px);
  line-height:1.05;
  letter-spacing:-.02em;
  color:#fff!important;
  text-shadow:0 4px 30px rgba(0,0,0,.35);
  margin:0;
}
body.item-view .post .post-title a,
body.item-view .post h1.post-title a{color:#fff!important}
body.item-view .post .post-header .meta,
body.item-view .post .post-info,
body.item-view .post .post-labels{
  display:inline-flex;flex-wrap:wrap;gap:8px;align-items:center;
  color:rgba(255,255,255,.85)!important;font-size:13px;
}
body.item-view .post .post-labels a{
  background:color-mix(in srgb,$(main.color) 92%, #000 8%);
  color:#fff!important;
  padding:6px 12px;border-radius:999px;
  font-size:11px;font-weight:700;letter-spacing:.08em;text-transform:uppercase;
  border:0;text-decoration:none;
  transition:transform .18s ease, box-shadow .18s ease;
}
body.item-view .post .post-labels a:hover{
  transform:translateY(-1px);
  box-shadow:0 10px 24px -8px color-mix(in srgb,$(main.color) 60%, transparent);
}

/* Corpo do post (perfil) — card interno flutuando sobre o hero */
body.item-view .post .post-body{
  position:relative;
  margin:8px 24px 24px;
  padding:32px clamp(20px,3.2vw,44px);
  background:$(posts.background.color);
  border-radius:18px;
  box-shadow:0 20px 60px -30px rgba(6,13,23,.25);
  color:$(posts.text.color);
  font-family:Outfit,sans-serif;
  font-size:16.5px;line-height:1.75;
}

/* Foto de destaque (poster / retrato) — Blogger insere como
   .separator > a > img no início do post. Deixamos em card. */
body.item-view .post .post-body > .separator:first-child,
body.item-view .post .post-body > div:first-child > .separator:first-child{
  float:left;
  margin:0 28px 18px 0;
  padding:8px;
  background:linear-gradient(135deg,$(main.color),#7a0000);
  border-radius:16px;
  box-shadow:0 18px 40px -18px color-mix(in srgb,$(main.color) 55%, transparent);
}
body.item-view .post .post-body > .separator:first-child img,
body.item-view .post .post-body > div:first-child > .separator:first-child img{
  display:block;
  width:260px;max-width:38vw;height:auto;
  border-radius:10px;
  transition:transform .35s ease;
}
body.item-view .post .post-body > .separator:first-child:hover img{transform:scale(1.02)}

/* Tipografia interna do perfil */
body.item-view .post .post-body h2,
body.item-view .post .post-body h3,
body.item-view .post .post-body h4{
  font-family:Outfit,sans-serif;font-weight:800;letter-spacing:-.01em;
  color:$(title.color);
  margin:1.6em 0 .6em;position:relative;padding-left:14px;
}
body.item-view .post .post-body h2:before,
body.item-view .post .post-body h3:before,
body.item-view .post .post-body h4:before{
  content:"";position:absolute;left:0;top:.35em;bottom:.35em;width:4px;
  background:$(main.color);border-radius:4px;
}
body.item-view .post .post-body strong,
body.item-view .post .post-body b{color:$(title.color)}
body.item-view .post .post-body a{
  color:$(main.color);text-decoration:none;
  background-image:linear-gradient(currentColor,currentColor);
  background-size:0 1.5px;background-repeat:no-repeat;background-position:0 100%;
  transition:background-size .25s ease;
}
body.item-view .post .post-body a:hover{background-size:100% 1.5px}
body.item-view .post .post-body ul{padding-left:0;list-style:none}
body.item-view .post .post-body ul li{
  position:relative;padding:6px 0 6px 22px;
  border-bottom:1px dashed rgba(6,13,23,.08);
}
body.item-view .post .post-body ul li:before{
  content:"";position:absolute;left:0;top:15px;width:8px;height:8px;
  background:$(main.color);border-radius:50%;
  box-shadow:0 0 0 3px color-mix(in srgb,$(main.color) 20%, transparent);
}
body.item-view .post .post-body blockquote{
  margin:18px 0;padding:16px 20px;
  background:color-mix(in srgb,$(main.color) 6%, transparent);
  border-left:4px solid $(main.color);
  border-radius:8px;color:$(title.color);font-style:normal;
}
body.item-view .post .post-body:after{content:"";display:block;clear:both}

/* Dark mode */
.dark body.item-view .post-outer,
body.dark.item-view .post-outer{
  background:$(main.dark.color);
  border-color:rgba(255,255,255,.06);
}
.dark body.item-view .post .post-body,
body.dark.item-view .post .post-body{
  background:#111a26;color:#c7cfda;
}
.dark body.item-view .post .post-body h2,
.dark body.item-view .post .post-body h3,
.dark body.item-view .post .post-body h4,
.dark body.item-view .post .post-body strong,
body.dark.item-view .post .post-body h2,
body.dark.item-view .post .post-body h3{color:#fff}
.dark body.item-view .post .post-body ul li{border-bottom-color:rgba(255,255,255,.08)}

/* Responsivo */
@media (max-width:720px){
  body.item-view .post-outer{border-radius:16px}
  body.item-view .post-outer:before{height:220px}
  body.item-view .post .post-header{padding:150px 20px 20px}
  body.item-view .post .post-body{margin:8px 12px 16px;padding:22px 18px}
  body.item-view .post .post-body > .separator:first-child img,
  body.item-view .post .post-body > div:first-child > .separator:first-child img{
    width:100%;max-width:100%;
  }
  body.item-view .post .post-body > .separator:first-child,
  body.item-view .post .post-body > div:first-child > .separator:first-child{
    float:none;margin:0 0 18px;
  }
}
/* ============ FIM CN-PROFILE-REDESIGN ============ */

b:includable.script:
