var no_image = "data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAABAAAAAJCAYAAAA7KqwyAAAABHNCSVQICAgIfAhkiAAAAAlwSFlzAAAD6AAAA+gBtXtSawAAABl0RVh0U29mdHdhcmUAd3d3Lmlua3NjYXBlLm9yZ5vuPBoAAAAYSURBVCiRY0xISOBgoAAwUaJ51IBhYwAAuQABOsYCprwAAAAASUVORK5CYII=";
/* ================================================================
 * getThumb(entry, content) — extração robusta da 1ª imagem do post
 * Ordem de tentativa:
 *   1. <img src="..."> dentro do conteúdo (HTML do post)
 *   2. iframe do YouTube -> media$thumbnail.url (mqdefault)
 *   3. media$thumbnail.url (imagem destacada do Blogger)
 *   4. no_image (fallback transparente)
 * Também remove crops do tipo /s72-c/ e /default.jpg para YouTube.
 * ================================================================ */
function getThumb(entry, content){
  var url = "";
  try {
    // 1) primeiro <img> no conteúdo
    if (content && content.indexOf("<img") > -1) {
      var m = content.match(/<img[^>]+src=["']([^"'>]+)["']/i);
      if (m && m[1]) url = m[1];
    }
    // 2/3) fallback para media$thumbnail
    if (!url && entry && entry.media$thumbnail && entry.media$thumbnail.url) {
      url = entry.media$thumbnail.url;
    }
  } catch (err) { url = ""; }
  if (!url) return no_image;
  // Normaliza tamanho / thumb do YouTube
  url = url.replace("/default.jpg", "/mqdefault.jpg");
  url = url.replace(/\/s72(-c)?\//, "/s1600/");
  url = url.replace("s72-c", "s1600");
  return url;
}

