                    d = l.substring(5, 7);
                    o = e.feed.entry[n].content.$t;
                    c = $("<div>").html(o);
                    u = o.replace(/<\S[^>]*>/g, "");

                    if (50 < u.length)
                        u = u.substring(0, 90) + " ..";

                    f = getThumb(e.feed.entry[n], o);

                    // Todos os labels (para reconhecer CRÍTICAS mesmo que não seja o primeiro)
                    var labels = e.feed.entry[n].category.map(function(cat) { return cat.term; });
                    var labelsUpper = labels.map(function(x){ return (x||'').toUpperCase(); });
                    firstLabel = labels.length > 0 ? labels[0] : 'No Label';

                    // Se CRÍTICAS estiver em QUALQUER label, buscar nota e gerar estrelas
                    var isCritica = labelsUpper.indexOf('CRÍTICAS') > -1 || labelsUpper.indexOf('CRITICAS') > -1;
                    var estrelasSlideTop = '';
                    if (isCritica) {
                        var notaStr = c.find('strike').first().text().trim().replace(',', '.');
                        var notaNum = parseFloat(notaStr);
                        if (!isNaN(notaNum) && notaNum >= 0.5 && notaNum <= 5) {
                            var starsHTML = '';
                            for (var si = 0; si < 5; si++) {
                                if (notaNum >= si + 1) starsHTML += '<span class="estrela-cheia">&#9733;</span>';
                                else if (notaNum > si && notaNum < si + 1) starsHTML += '<span class="estrela-meia">&#9733;</span>';
                                else starsHTML += '<span class="estrela-vazia">&#9734;</span>';
                            }
                            estrelasSlideTop = '<div class="nota-exibida-title"><span class="nota-label">CRÍTICA</span><span class="stars">'+starsHTML+'</span><span class="nota-score">'+notaNum.toFixed(1)+'<em>/5</em></span></div>';
                        }
                    }

                    s += '<li class="carousel-item">' +
                            '<a title="' + r + '" href="' + t + '">' +
                                '<span class="box-image lazyload shown lazied" style="background-image:url('+(f||"https://placehold.co/800x500/060d17/ffffff?text=Sem+Imagem")+')"/>' +
                                '<span class="carousel-overlay"/>' +
                            '</a>' +
                            '<div class="carousel-content">' +
                                '<div class="first-label">' + firstLabel + '</div>' +
                                '<h3 class="recent-title"><a href="' + t + '" title="' + r + '">' + r + '</a></h3>' +
                                estrelasSlideTop +
                                '<p class="formatted-summary">' + u + '</p>' +
                            '</div>' +
                            '<div class="clr"/>' +
                        '</li>';
                }

                s += "</div>";

                $(".gsrecent .widget-content").each(function() {
                    if ($(this).parent().attr("id") == a) {
                        $(this).html(s);
                        $(this).parent().addClass("dataslide");
                        // FIX CALLANGO: evita exibicao dupla do slide topo
                        // 1) remove containers .slidesone extras criados por execucoes repetidas
                        $(this).find(".slidesone").slice(1).remove();
                        // 2) inicializa APENAS o carrossel deste widget e somente uma vez
                        var $slideTopEl = $(this).find(".slidesone").first();
                        if ($slideTopEl.hasClass("owl-loaded") || $slideTopEl.data("cnSlideInit")) { return; }
                        $slideTopEl.data("cnSlideInit", true);
                        $slideTopEl.owlCarousel({
                            animateOut: "fadeOut",
                            margin: 0,
                            items: 1,
                            autoplay: true,
                            autoplayTimeout: 3500,
                            autoplayHoverPause: true,
                            loop: true,
                            mouseDrag: false,
                            dots: true,
                            nav: false,
                            responsive: {
                                0: { items: 1, nav: false },
                                601: { items: 1, nav: false }
                            }
                        });

                        // Botão discreto "próximo" combinando com o layout
                        if (!$('.slide_top .st-next-discrete').length) {
                            var $btn = $('<button type="button" class="st-next-discrete" aria-label="Próximo">&#8250;</button>');
                            $('.slide_top').append($btn);
                            $btn.on('click', function(){ $('.slide_top .slidesone').first().trigger('next.owl.carousel'); });
                        }

                        // Aplica formatação ao conteúdo do parágrafo
                        $(this).find(".formatted-summary").each(function() {
                            applyBoldToCapitalizedWords(this);
                            applyBoldToTextBetweenAsterisks(this);  // Aplicar negrito no texto entre asteriscos
                        });

                        $(this).find(".box-image").each(function() {
                            $(this).attr("style", function(e, t) {
                                return t.replace("/default.jpg", "/mqdefault.jpg");
                            }).attr("style", function(e, t) {
                                return t.replace("s72-c", "s1600");
                            });
                        });
                    }
                });
            }
        });
    }
});

// Função para aplicar negrito nas palavras que começam com letras maiúsculas
function applyBoldToCapitalizedWords(element) {
    var nodes = element.childNodes;

    nodes.forEach(function(node) {
        if (node.nodeType === Node.TEXT_NODE) {
            var text = node.nodeValue;
            var words = text.split(/\s+/);
            var fragment = document.createDocumentFragment();

            words.forEach(function(word, wordIndex) {
                var isEndOfSentence = /[\.\?\!]/.test(word);
                var span;

                if (/^[A-Z]/.test(word)) {
                    span = document.createElement('span');
                    span.textContent = word;
                    span.style.fontWeight = '600';
                    fragment.appendChild(span);
                } else {
                    fragment.appendChild(document.createTextNode(word));
                }

                if (wordIndex < words.length - 1 || isEndOfSentence) {
                    fragment.appendChild(document.createTextNode(' '));
                }
            });

            node.parentNode.replaceChild(fragment, node);
        } else if (node.nodeType === Node.ELEMENT_NODE) {
            applyBoldToCapitalizedWords(node);
        }
    });
}

// Função para aplicar negrito ao texto entre * * ou ** **
function applyBoldToTextBetweenAsterisks(element) {
    var html = element.innerHTML;

    // Substitui texto entre * * ou ** ** por um span com font-weight 600
    html = html.replace(/\*\*(.*?)\*\*/g, '<span style="font-weight: 600;">$1</span>');
    html = html.replace(/\*(.*?)\*/g, '<span style="font-weight: 600;">$1</span>');

    element.innerHTML = html;
}

