$(document).ready(function() {
    // Função para aplicar estilo ao texto em negrito e itálico
    function estilizarTextoEmNegritoEItalico() {
        $(".recent-summary").each(function() {
            var html = $(this).html();
            html = html.replace(/\*\*(.*?)\*\*/g, '<span style="font-weight: 600;">$1</span>'); // Negrito com **
            html = html.replace(/\*(.*?)\*/g, '<span style="font-weight: 600;">$1</span>'); // Itálico com *
            $(this).html(html);
        });
    }

    // Aplicar a estilização ao carregar a página
    estilizarTextoEmNegritoEItalico();

    $(".gsrecent .widget-content").each(function() {
        var e = $(this).find("span").attr("data-label"),
            t = $(this).parent().attr("id");

        if ($(this).find("span").attr("data-type").match("goom")) {
            $.ajax({
                url: "/feeds/posts/default/-/" + e + "?alt=json-in-script&max-results=11",
                type: "get",
                dataType: "jsonp",
                success: function(e) {
                    var jnewsContent = ""; // Conteúdo para jnews
                    var jnews2Content = "<ul>"; // Conteúdo para jnews2
                    var a = "";

                    for (var n = 0; n < e.feed.entry.length; n++) {
                        // Obter o link
                        for (var r = 0; r < e.feed.entry[n].link.length; r++) {
                            if ("alternate" == e.feed.entry[n].link[r].rel) {
                                a = e.feed.entry[n].link[r].href;
                                break;
                            }
                        } 

                        var l = e.feed.entry[n].title.$t,
                            i = e.feed.entry[n].category[0].term,
                            h = e.feed.entry[n].content.$t,
                            p = $("<div>").html(h),
                            m = obterNomeAutor(p),
                            c = e.feed.entry[n].published.$t,
                            d = c.substring(0, 4),
                            f = c.substring(5, 7),
                            o = c.substring(8, 10),
                            u = month_format[parseInt(f, 10)] + " " + o + ", " + d;

                        var g = "content" in e.feed.entry[n] ? e.feed.entry[n].content.$t : "summary" in b_rc ? e.feed.entry[n].summary.$t : "";

                        if ((g = g.replace(/<\S[^>]*>/g, "")).length > 120) g = g.substring(0, 120) + "...";

                        var v = getThumb(e.feed.entry[n], h);

                        var nota = parseFloat(p.find("strike").text().trim());
                        var estrelasHTML = '';
                        if (nota >= 1 && nota <= 5) {
                            estrelasHTML = identificarDeEstrelasPorNota(nota);
                        }

                        // O primeiro item vai para jnews
                        if (n === 0) {
                            jnewsContent += '<div class="jnews"><div class="gs-item"><div class="gsthumbnail"><a title="' + l + '" href="' + a + '"><span class="bf-thumb lazyload shown lazied" style="background-image:url('+(v||"https://placehold.co/800x500/060d17/ffffff?text=Sem+Imagem")+')"/><span class="gs-overlay"/></a></div><div class="gscontent"><h3 class="recent-title"><a href="' + a + '" title="' + l + '">' + l + '</a></h3><div class="carousel-meta"><span class="">' + m + '</span><a class="first-label" href="/search/label/' + i + '?&max-results=8" title="' + i + '">' + i + '</a><span class="recent-date">' + u + '</span></div><div id="nota-exibida-title">' + estrelasHTML + '</div><p class="recent-summary">' + g + '</p></div></div></div>';
                        } else {
                            // Os próximos itens vão para jnews2
                            jnews2Content += '<li><div class="gsthumbnail"><a title="' + l + '" href="' + a + '"><span class="box-image lazyload shown lazied" style="background-image:url('+(v||"https://placehold.co/800x500/060d17/ffffff?text=Sem+Imagem")+')"/><span class="gs-overlay"/></a></div><div class="recent-content"><h3 class="recent-title"><a href="' + a + '" title="' + l + '">' + l + '</a></h3><div class="carousel-meta"><span class="">' + m + '</span><a class="first-label" href="/search/label/' + i + '?&max-results=8" title="' + i + '">' + i + '</a><span class="recent-date">' + u + '</span></div><div id="nota-exibida-title">' + estrelasHTML + '</div></div><div class="clr"/></li>';
                        }
                    }

                    jnews2Content += "</ul>";

                    // Atualiza o conteúdo do widget
                    $(".gsrecent .widget-content").each(function() {
                        if ($(this).parent().attr("id") == t) {
                            $(this).html(jnewsContent + '<div class="jnews2">' + jnews2Content + '</div>'); // Insere jnews e jnews2
                            $(this).parent().addClass("goom");

                            // Ajusta o estilo das imagens
                            $(this).find(".box-image, .bf-thumb").each(function() {
                                $(this).attr("style", function(e, t) {
                                    return t.replace("/default.jpg", "/mqdefault.jpg");
                                }).attr("style", function(e, t) {
                                    return t.replace("s72-c", "s1600");
                                });
                            });
                        }
                    });

                    // Aplicar a estilização ao texto depois de atualizar o widget
                    estilizarTextoEmNegritoEItalico();
                }
            });
        }
    });

    // Função para obter o nome do autor
    function obterNomeAutor(p) {
        return p.find("h4").text().trim();
    }

    function identificarDeEstrelasPorNota(nota) {
        var estrelasHTML = '';
        for (var i = 0; i < 5; i++) {
            if (nota >= i + 1) {
                estrelasHTML += '<span class="estrela-cheia">&#9733;</span>'; // Estrela cheia
            } else if (nota > i && nota < i + 1) {
                estrelasHTML += '<span class="estrela-meia">&#9733;</span>'; // Meia estrela
            } else {
                estrelasHTML += '<span class="estrela-vazia">&#9734;</span>'; // Estrela vazia
            }
        }
        return estrelasHTML;
    }
});

