// backtop
"use strict";

// Função para rolar até o topo
function scrollToTop() {
    var verticalOffset = "undefined" != typeof verticalOffset ? verticalOffset : 0;
    var element = $("body");
    var offset = element.offset();
    var offsetTop = offset.top;
    $("html, body").animate({scrollTop: offsetTop}, 600, "linear");
}

// Executa a função quando o DOM estiver pronto
$(function() {
    // Mostra ou oculta o botão com base na rolagem da página
    $(document).on("scroll", function() {
        if ($(window).scrollTop() > 100) {
            $(".backtop, .bottom-bar").addClass("show");
        } else {
            $(".backtop, .bottom-bar").removeClass("show");
        }
    });

    // Configura o clique no botão para rolar para o topo
    $(".backtop").on("click", scrollToTop);

    // Garante que o botão funcione em dispositivos móveis
    $(".backtop").on("touchend", scrollToTop);
});

