head.script:
//
(function(){
  if(typeof jQuery==='undefined')return;
  jQuery(function($){
    var notaCache = {};

    function starsHTML(nota){
      var h = '';
      for (var i=0;i<5;i++){
        if (nota >= i+1)       h += '<span class="estrela-cheia">&#9733;</span>';
        else if (nota > i)     h += '<span class="estrela-meia">&#9733;</span>';
        else                   h += '<span class="estrela-vazia">&#9734;</span>';
      }
      return h;
    }

    function extractNota(html){
      // "Nota: 4.5" | "Nota - 4,5" | "Nota 4"
      var m = html.match(/Nota\s*[:\-–]?\s*([0-5](?:[.,]\d)?)/i);
      if (m) return parseFloat(m[1].replace(',', '.'));
      var doc = document.createElement('div'); doc.innerHTML = html;
      var el = doc.querySelector('#nota-exibida, #nota, .nota, [data-nota]');
      if (el){
        // Conta estrelas cheias/meias já renderizadas
        var full = el.querySelectorAll('.estrela-cheia').length;
        var half = el.querySelectorAll('.estrela-meia').length;
        if (full || half) return full + (half ? 0.5 : 0);
        var v = el.getAttribute('data-nota') || el.textContent || '';
        var mm = v.match(/([0-5](?:[.,]\d)?)/);
        if (mm) return parseFloat(mm[1].replace(',', '.'));
      }
      return null;
    }

    function ensureNota(item, href, isReview){
      if (!isReview) return;
      var content = item.find('.carousel-content');
      if (content.find('.nota-exibida-title, #nota-exibida-title').length) return;
      var holder = $('<div class="nota-exibida-title" aria-live="polite"></div>');
      // Insere logo abaixo do título (mesmo padrão dos outros widgets)
      content.find('.recent-title').after(holder);

      function render(nota){
        if (nota == null) { holder.remove(); return; }
        var pretty = (Math.round(nota*10)/10).toString().replace('.', ',');
        holder.html('<span class="nota-label">Nota</span>' + starsHTML(nota) +
                    '<span class="nota-score">' + pretty + '</span>');
      }

      if (notaCache[href] !== undefined) return render(notaCache[href]);
      $.ajax({ url: href, dataType: 'html' })
        .done(function(html){ var n = extractNota(html); notaCache[href]=n; render(n); })
        .fail(function(){ holder.remove(); });
    }

    function enrich(){
      var items = $('.slide_top .slidesone .carousel-item');
      if(!items.length) return false;
      items.each(function(){
        var it = $(this);
        if (it.data('stEnriched')) return;
        it.data('stEnriched', true);

        var href     = it.find('a').first().attr('href') || '#';
        var title    = (it.find('.recent-title').text() || '').toLowerCase();
        var firstLbl = (it.find('.first-label').text() || '').toLowerCase();
        var haystack = (href+' '+title+' '+firstLbl+' '+(it.attr('class')||'')).toLowerCase();
        var isReview = /cr[ií]tic|review|resenha|an[aá]lise/.test(haystack);

        ensureNota(it, href, isReview);
      });
      return true;
    }

    var tries=0, iv=setInterval(function(){ if(enrich() || (++tries)>40) clearInterval(iv); }, 250);
    var root=document.querySelector('.slide_top');
    if(root){
      var mo = new MutationObserver(function(muts){
        // Só reprocessa quando itens novos surgem — evita loop com class-toggle do Owl
        for (var i=0;i<muts.length;i++){
          if (muts[i].type === 'childList' && muts[i].addedNodes.length){ enrich(); return; }
        }
      });
      mo.observe(root, {childList:true, subtree:true});
    }
  });
})();
//

//
(function(){
  function ready(fn){ if(document.readyState!=='loading') fn(); else document.addEventListener('DOMContentLoaded', fn); }
  ready(function(){
    function markEntering(item){
      if(!item) return;
      item.classList.remove('is-entering');
      // reflow para reiniciar
      void item.offsetWidth;
      item.classList.add('is-entering');
    }

    // Primeiro slide visível
    var first = document.querySelector('.slide_top .slidesone .owl-item.active .carousel-item') ||
                document.querySelector('.slide_top .slidesone .carousel-item');
    if (first) markEntering(first);

    // Eventos oficiais do Owl (fonte confiável, sem loop)
    if (window.jQuery){
      window.jQuery(document).on('translated.owl.carousel', '.slide_top .slidesone', function(){
        var active = document.querySelector('.slide_top .slidesone .owl-item.active .carousel-item');
        markEntering(active);
      });
    }
  });
})();
//

//
(function(){
  function ready(fn){ if(document.readyState!=='loading') fn(); else document.addEventListener('DOMContentLoaded', fn); }
  function initOne(jnews2){
    if(!jnews2 || jnews2.dataset.carouselReady === '1') return true;
    var list = jnews2.querySelector('ul');
    if(!list) return false;
    // Envolve o UL em wrapper para posicionar as setas por cima da lista
    var wrap = document.createElement('div');
    wrap.className = 'jnews2-carousel-wrap';
    list.parentNode.insertBefore(wrap, list);
    wrap.appendChild(list);

    var prev = document.createElement('button');
    prev.type = 'button';
    prev.className = 'jnews2-arrow prev';
    prev.setAttribute('aria-label','Anterior');
    prev.innerHTML = '‹';

    var next = document.createElement('button');
    next.type = 'button';
    next.className = 'jnews2-arrow next';
    next.setAttribute('aria-label','Próximo');
    next.innerHTML = '›';

    wrap.appendChild(prev);
    wrap.appendChild(next);

    function step(){
      var first = list.querySelector('li');
      if(!first) return list.clientWidth * 0.8;
      var style = window.getComputedStyle(list);
      var gap = parseFloat(style.columnGap || style.gap || '18') || 18;
      return first.getBoundingClientRect().width + gap;
    }
    function update(){
      var max = list.scrollWidth - list.clientWidth - 2;
      prev.disabled = list.scrollLeft <= 2;
      next.disabled = list.scrollLeft >= max;
    }
    prev.addEventListener('click', function(){ list.scrollBy({left: -step(), behavior:'smooth'}); });
    next.addEventListener('click', function(){ list.scrollBy({left: step(), behavior:'smooth'}); });
    list.addEventListener('scroll', update, {passive:true});
    window.addEventListener('resize', update);
    setTimeout(update, 60);
    jnews2.dataset.carouselReady = '1';
    return true;
  }
  function initAll(){
    var all = document.querySelectorAll('.goom .jnews2');
    var ok = all.length > 0;
    all.forEach(function(el){ if(!initOne(el)) ok = false; });
    return ok;
  }
  ready(function(){
    if(initAll()) return;
    var tries = 0;
    var iv = setInterval(function(){
      tries++;
      if(initAll() || tries > 60) clearInterval(iv);
    }, 250);
  });
})();
//

body.script:
//
(function(){
  /* Marca a pagina como CRITICA o mais cedo possivel, ainda durante o parse do
     HTML, para a sidebar nunca chegar a ser pintada (nem no carregamento). */
  var html = document.documentElement;
  function norma(t){ return (t||'').normalize('NFD').replace(/[̀-ͯ]/g,'').toUpperCase().trim(); }
  function marcar(){
    html.classList.add('cn-critica');
    if(document.body){ document.body.classList.add('no-sidebar'); }
    var sb = document.getElementById('sidebar-wrapper');
    if(sb){ sb.style.display = 'none'; }
  }
  function achou(){
    var links = document.querySelectorAll('.post-labels a, .label-head.Label a, [rel="tag"]');
    for(var i=0;i<links.length;i++){ if(norma(links[i].textContent) === 'CRITICAS') return true; }
    return false;
  }
  if(document.body && document.body.classList.contains('no-sidebar')){ marcar(); }
  var obs = new MutationObserver(function(){
    if(achou()){ marcar(); obs.disconnect(); }
  });
  try{ obs.observe(html, {childList:true, subtree:true}); }catch(e){}
  document.addEventListener('DOMContentLoaded', function(){
    if(achou()) marcar();
    setTimeout(obs.disconnect.bind(obs), 4000);
  });
})();
