  ];
  // Gêneros TMDB relevantes: 878 sci-fi, 12 aventura, 28 ação, 16 animação
  var GENRES_MOVIE = [{id:878,name:'SCI-FI'},{id:12,name:'AVENTURA'},{id:28,name:'AÇÃO'},{id:16,name:'ANIMAÇÃO'}];
  // Anime: keyword 210024 (anime) + genero 16
  var KEYWORDS = [{id:210024,name:'ANIME'},{id:9715,name:'BASEADO EM QUADRINHOS'},{id:818,name:'BASEADO EM LIVRO'},{id:1721,name:'PREMIAÇÕES'}];

  var items = [];
  var track = document.getElementById('trendNewsTrack');
  var modal = document.getElementById('trendNewsModal');
  var modalBody = document.getElementById('trendNewsModalBody');
  var wrap = document.getElementById('trendNewsWrap');
  var viewport = wrap.querySelector('.trend-news-viewport');
  var carouselWrap = wrap.querySelector('.trend-news-carousel-wrap');
  var prevBtn = wrap.querySelector('.tn-arrow.tn-prev');
  var nextBtn = wrap.querySelector('.tn-arrow.tn-next');

  function fmtDate(d){try{var dt=new Date(d);var m=['JAN','FEV','MAR','ABR','MAI','JUN','JUL','AGO','SET','OUT','NOV','DEZ'];return m[dt.getMonth()]+' '+String(dt.getDate()).padStart(2,'0')+', '+dt.getFullYear();}catch(e){return '';}}
  function esc(s){return (s||'').replace(/[&<>"']/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c];});}
  function fetchJSON(url){return fetch(url).then(function(r){return r.json();}).catch(function(){return null;});}

  // ============ ALGORITMO DE LINGUAGEM ============
  // Amostra frases do próprio site (posts do Márcio) e mistura com um pool base.
  // Sem repetição: guarda últimos N usados por categoria; quando pool acaba, reseta.
  var STYLE = {
    openers: [
      'Segura essa, meus consagrados:',
      'Prepara o coração, nerdada, porque',
      'Olha o que caiu no radar do Callango:',
      'Chegou a hora, galera arretada &#8212;',
      'Bora sentar que o papo é reto:',
      'Bicho, isso aqui vai deixar geral em polvorosa:',
      'Pega o café e senta que tem novidade quente:',
      'A gente aqui na toca do Callango tava esperando por isso:',
      'Se liga na bomba que tá pipocando:',
      'Notícia fresca saindo do forno, colega:',
      'Meus caros, é oficial:',
      'Prepara o balde de pipoca e o coração fraco, porque',
      'A nerdada pode comemorar &#8212;',
      'Direto da redação Callango, sem enrolação:',
      'Nada de spoiler, mas',
      'Se você é fã do gênero, prepara-se:',
      'Vem coisa boa por aí:',
      'O universo geek não descansa nem por um segundo:',
      'Alerta trend, galera:',
      'Ó o que apareceu no nosso radar hoje:'
    ],
    bridges: [
      'promete agitar a próxima maratona',
      'já entrou na mira da nerdada braba',
      'tá dando pano pra manga nas redes',
      'chegou pra bagunçar o coreto',
      'tá deixando fã e crítico de queixo caído',
      'já virou assunto obrigatório entre os cinéfilos',
      'promete ser um marco pra cultura pop',
      'tem gostinho de coisa grande vindo aí',
      'já garante lugar cativo no bate-papo do bar',
      'tá com pinta de bombar de vez',
      'chegou fazendo barulho e nem estreou direito',
      'promete render horas de discussão nos grupos'
    ],
    closers: [
      'Bora acompanhar juntos e soltar o verbo aí nos comentários!',
      'Fica ligado no Callango que a gente traz mais novidades quentinhas do forno.',
      'Anota aí na agenda nerd e não perde por nada nesse mundo.',
      'É o Callango Nerd na cabeça &#8212; não fica de fora dessa!',
      'Se prepara, porque isso é só a ponta do iceberg dessa saga.',
      'A gente volta com mais no próximo drop &#8212; segue de olho.',
      'Comenta aí embaixo o que achou dessa &#8212; a gente lê tudinho.',
      'Bora manter o hype no talo até o dia D.',
      'Enquanto isso, corre atualizar a lista de lançamentos.',
      'A galera vai amar &#8212; ou vai fazer um textão. Ou os dois.',
      'Fim de papo por aqui, mas o assunto tá longe de acabar.',
      'A conferir &#8212; e a torcer pra não decepcionar.'
    ],
    headlines: {
      MARVEL: ['CASA DAS IDEIAS CONFIRMOU:', 'MARVEL SOLTOU A BOMBA:', 'MULTIVERSO EM POLVOROSA:', 'DIRETO DA MARVEL STUDIOS:', 'O UNIVERSO CINEMATOGRÁFICO NÃO PARA:'],
      DC: ['DC NÃO TÁ DE BRINCADEIRA:', 'GOTHAM EM ALERTA VERMELHO:', 'LIGA DA JUSTIÇA AVISA:', 'DC UNIVERSE MEXE OS PAUZINHOS:', 'JAMES GUNN VS. O MUNDO:'],
      TV: ['BOMBA NA TELINHA:', 'CHEGOU PRA QUEBRAR TUDO:', 'MARATONA GARANTIDA:', 'ALERTA MARATONISTA:', 'A NOVA OBSESSÃO DO STREAMING:'],
      MOVIE: ['CINEMA EM CHAMAS:', 'BOMBA NAS TELONAS:', 'PREPARA O CORAÇÃO:', 'A ESTREIA QUE PROMETE:', 'CINÉFILO, ACORDA:', 'ARRETADO DEMAIS:'],
      ANIME: ['O JAPÃO NÃO ERRA:', 'ANIME FANS EM CHOQUE:', 'OTAKU EM PANE:', 'DIRETO DO ESTÚDIO NIPÔNICO:'],
      AWARD: ['A DISPUTA DA ESTATUETA:', 'CORRIDA PELO PRÊMIO ESQUENTA:', 'A ACADEMIA JÁ TÁ DE OLHO:'],
      BOOK: ['LIVRO VIRA TELÃO:', 'ADAPTAÇÃO CONFIRMADA:', 'DOS LIVROS PRAS TELAS:'],
      SCIFI: ['A GALÁXIA CHAMA:', 'FICÇÃO CIENTÍFICA NO TALO:', 'FUTURO CHEGANDO CEDO:']
    },
    sitePhrases: [] // preenchido em runtime
  };
  var usedPools = {}; // controla repetição por categoria

  // Puxa amostra dos posts do site pra emular vocabulário do Márcio
  function harvestStyle(){
    return fetchJSON('/feeds/posts/default?alt=json&max-results=50').then(function(d){
      if(!d||!d.feed||!d.feed.entry) return;
      var phrases = [];
      d.feed.entry.forEach(function(en){
        var html = (en.content && en.content.$t) || '';
        var txt = html.replace(/<[^>]+>/g,' ').replace(/&nbsp;/g,' ').replace(/\s+/g,' ');
        // extrai frases de 6 a 20 palavras com sabor cearense/informal
        var sents = txt.split(/(?<=[\.\!\?])\s+/);
        sents.forEach(function(s){
          var w = s.trim().split(/\s+/);
          if(w.length<6 || w.length>22) return;
          if(/[a-zA-Z]/.test(s)===false) return;
          // filtra frases com marcadores expressivos
          if(/arretad|brabo|bicho|colega|nerd|cinéfilo|hype|pipoca|bomba|top|top demais|maratona|geek|otaku|fã|arraso|show|espetácul|magistr|imperd|estreia|lançamento/i.test(s)){
            phrases.push(s.trim());
          }
        });
      });
      STYLE.sitePhrases = phrases.slice(0,80);
    }).catch(function(){});
  }

  function pickNoRepeat(key, arr){
    if(!arr || !arr.length) return '';
    if(!usedPools[key]) usedPools[key] = [];
    var used = usedPools[key];
    var pool = arr.filter(function(x){ return used.indexOf(x)===-1; });
    if(!pool.length){ usedPools[key] = []; pool = arr.slice(); }
    var chosen = pool[Math.floor(Math.random()*pool.length)];
    usedPools[key].push(chosen);
    return chosen;
  }

  function makeHeadline(it){
    var c=(it.category||'').toUpperCase();
    var key='MOVIE';
    if(c.indexOf('MARVEL')>-1) key='MARVEL';
    else if(c==='DC'||c.indexOf('DC')>-1) key='DC';
    else if(c.indexOf('ANIME')>-1) key='ANIME';
    else if(c.indexOf('PREM')>-1||c.indexOf('AWARD')>-1) key='AWARD';
    else if(c.indexOf('LIVRO')>-1||c.indexOf('BOOK')>-1) key='BOOK';
    else if(c.indexOf('SCI')>-1) key='SCIFI';
    else if(it.tmdbType==='tv'||c==='SÉRIES'||c==='NETFLIX'||c==='HBO MAX'||c==='APPLE TV+'||c==='DISNEY+'||c==='PARAMOUNT+'||c==='PRIME VIDEO'||c==='AMAZON PRIME') key='TV';
    return pickNoRepeat('h_'+key, STYLE.headlines[key]);
  }

  function fetchByCompany(comp){
    var url=TMDB+'/discover/movie?api_key='+TMDB_KEY+'&language=pt-BR&sort_by=primary_release_date.desc&with_companies='+comp.id+'&page=1&include_adult=false&primary_release_date.lte='+new Date().toISOString().slice(0,10);
    return fetchJSON(url).then(function(d){if(!d||!d.results)return [];return d.results.slice(0,3).map(function(it){return mapItem(it,'movie',comp.name);});});
  }
  function fetchByNetwork(net){
    var url=TMDB+'/discover/tv?api_key='+TMDB_KEY+'&language=pt-BR&sort_by=first_air_date.desc&with_networks='+net.id+'&page=1&first_air_date.lte='+new Date().toISOString().slice(0,10);
    return fetchJSON(url).then(function(d){if(!d||!d.results)return [];return d.results.slice(0,2).map(function(it){return mapItem(it,'tv',net.name);});});
  }
  function fetchByGenre(g){
    var url=TMDB+'/discover/movie?api_key='+TMDB_KEY+'&language=pt-BR&sort_by=popularity.desc&with_genres='+g.id+'&page=1&include_adult=false';
    return fetchJSON(url).then(function(d){if(!d||!d.results)return [];return d.results.slice(0,2).map(function(it){return mapItem(it,'movie',g.name);});});
  }
  function fetchByKeyword(k){
    var url=TMDB+'/discover/movie?api_key='+TMDB_KEY+'&language=pt-BR&sort_by=popularity.desc&with_keywords='+k.id+'&page=1&include_adult=false';
    return fetchJSON(url).then(function(d){if(!d||!d.results)return [];return d.results.slice(0,2).map(function(it){return mapItem(it,'movie',k.name);});});
  }
  // === FEED UNIFICADO DE CULTURA POP BR (Márcio Oliveira mode ON) ===
  // Troca o /trending do TMDB por um agregador dos sites nerds BR.
  // Cada notícia ainda tenta casar com um título no TMDB para liberar
  // trailer em pop, página do filme e página do ator.
  var MEUS_FEEDS = [
    { nome:'Omelete',                url:'https://www.omelete.com.br/rss' },
    { nome:'Jovem Nerd',             url:'https://jovemnerd.com.br/feed/' },
    { nome:'CinePOP',                url:'https://cinepop.com.br/feed/' },
    { nome:'Canaltech Entretenimento', url:'https://canaltech.com.br/rss/entretenimento/' },
    { nome:'Variety',                url:'https://variety.com/feed/', intl:true },
    { nome:'Collider',               url:'https://collider.com/feed/', intl:true },
    { nome:'The Hollywood Reporter', url:'https://www.hollywoodreporter.com/feed/', intl:true },
    { nome:'CosmicBook News',        url:'https://cosmicbook.news/rss.xml', intl:true }
  ];
  // Universo editorial do widget: tudo gira em torno destas editorias.
  var FILTROS_POP = [
    'MARVEL','DC','WARNER','DISNEY','UNIVERSAL','COLUMBIA','DREAMWORKS','PIXAR','SONY','A24',
    'NETFLIX','AMAZON PRIME','PRIME VIDEO','HBO','MAX','APPLE TV','DISNEY+','PARAMOUNT+','STREAMING','GLOBOPLAY','CRUNCHYROLL',
    'CINEMA','FILME','FILMES','ESTREIA','BILHETERIA','SEQUEL','SEQUÊNCIA',
    'SÉRIE','SERIE','SÉRIES','SERIES','TEMPORADA','EPISÓDIO','TV','MINISSÉRIE',
    'ANIME','MANGÁ','MANGA','OTAKU','SHONEN','STUDIO GHIBLI','ONE PIECE','DRAGON BALL','NARUTO','JUJUTSU',
    'LIVRO','LIVROS','HQ','QUADRINHO','QUADRINHOS','ADAPTAÇÃO','ROMANCE',
    'TRAILER','TEASER','TRAILERS','PRÉVIA','PREVIA',
    'CURIOSIDADE','CURIOSIDADES','BASTIDORES','VOCÊ SABIA','EASTER EGG',
    'STAR WARS','SENHOR DOS ANÉIS','GAME OF THRONES','BATMAN','SUPERMAN','HOMEM-ARANHA','VINGADORES'
  ];

  // === EDITORIAS OFICIAIS DO WIDGET ===
  // CINEMA, SÉRIE, ANIME, LIVROS, CURIOSIDADES, TRAILER, MARVEL, DC, TV, STREAMING
  var EDITORIAS = [
    { nome:'MARVEL',       rx:/marvel|vingadores|avengers|homem[- ]aranha|spider[- ]man|x[- ]men|wanda|thor|deadpool|mcu|capit[ãa]o am[ée]rica|quarteto fant[áa]stico/i },
    { nome:'DC',           rx:/\bdc\b|batman|superman|coringa|joker|mulher[- ]maravilha|liga da justi[çc]a|gotham|james gunn|lanterna verde|flash/i },
    { nome:'ANIME',        rx:/anime|mang[áa]|otaku|shonen|ghibli|one piece|dragon ball|naruto|jujutsu|demon slayer|crunchyroll|jujutsu kaisen/i },
    { nome:'TRAILER',      rx:/trailer|teaser|pr[ée]via|primeiro olhar|first look/i },
    { nome:'LIVROS',       rx:/livro|livros|romance|hq|quadrinho|quadrinhos|adapta[çc][ãa]o liter[áa]ria|best[- ]seller|autor|escritor/i },
    { nome:'CURIOSIDADES', rx:/curiosidade|bastidores|voc[êe] sabia|easter egg|nos bastidores|por tr[áa]s das c[âa]meras/i },
    { nome:'STREAMING',    rx:/netflix|prime video|amazon prime|hbo|max\b|disney\+|apple tv|paramount\+|globoplay|streaming|cat[áa]logo/i },
    { nome:'SÉRIE',        rx:/s[ée]rie|s[ée]ries|temporada|epis[óo]dio|miniss[ée]rie|spin[- ]off/i },
    { nome:'TV',           rx:/\btv\b|emissora|canal|programa|reality/i },
    { nome:'CINEMA',       rx:/filme|cinema|estreia|bilheteria|longa[- ]metragem|sess[ãa]o|telona|dire[çc][ãa]o|elenco/i }
  ];
  function tnEditoria(n, hit){
    var texto = [ (n && n.title) || '', (n && n.description) || '',
                  (n && n.categories ? n.categories.join(' ') : '') ].join(' ');
    for(var i=0;i<EDITORIAS.length;i++){
      if(EDITORIAS[i].rx.test(texto)) return EDITORIAS[i].nome;
    }
    if(hit && hit.media_type==='tv') return 'SÉRIE';
    if(hit && hit.media_type==='movie') return 'CINEMA';
    return 'CURIOSIDADES';
  }
  function tnDecode(s){
    var t = String(s||'');
    if(t.indexOf('&') === -1) return t;
    try{ var d = document.createElement('textarea'); d.innerHTML = t; return d.value; }catch(e){ return t; }
  }
  // corrige texto colado: "palavra.Outra" -> "palavra. Outra"
  function tnAjustaTexto(s){
    return String(s||'')
      .replace(/\u00a0/g,' ')
      .replace(/\s*\n\s*/g,' ')
      .replace(/([a-z\u00e0-\u00fc0-9\)\]"'])([.!?;:,])([A-Z\u00c0-\u00dc])/g,'$1$2 $3')
      .replace(/([.!?])([A-Z\u00c0-\u00dc])/g,'$1 $2')
      .replace(/\s+([.,!?;:])/g,'$1')
      .replace(/\s{2,}/g,' ')
      .trim();
  }
  function stripHtml(s){
    var t = String(s||'')
      .replace(/<(script|style)[\s\S]*?<\/\1>/gi,' ')
      .replace(/<\/(p|div|li|h[1-6]|section|article)>/gi,'\n')
      .replace(/<br\s*\/?>/gi,'\n')
      .replace(/<[^>]+>/g,' ');
    return tnAjustaTexto(tnDecode(t));
  }
  function limparQuery(t){
    return String(t||'')
      .replace(/\|.*$/,'')
      .replace(/[""''`]/g,'')
      .replace(/\s*[-–—:]\s.*$/,'')
      .replace(/\b(trailer|teaser|review|cr[íi]tica|an[áa]lise|assista|confira|revela|ganha|estreia)\b/gi,'')
      .trim();
  }
  function fetchRSS(site){
    var api='https://api.rss2json.com/v1/api.json?rss_url='+encodeURIComponent(site.url);
    return fetch(api).then(function(r){return r.json();}).then(function(d){
      if(!d||d.status!=='ok'||!d.items) return [];
      return d.items.map(function(it){
        return {
          fonte: site.nome,
          intl: !!site.intl,
          title: it.title,
          pubDate: it.pubDate,
          link: it.link,
          guid: it.guid,
          author: it.author || site.nome,
          thumbnail: it.thumbnail || (it.enclosure && it.enclosure.link) || '',
          description: it.description || '',
          content: it.content || '',
          categories: it.categories || []
        };
      });
    }).catch(function(err){ console.warn('[FEED] falhou:', site.nome, err); return []; });
  }
  function fetchTrending(){
    return Promise.all(MEUS_FEEDS.map(fetchRSS)).then(function(all){
      var feed=[]; all.forEach(function(a){ feed=feed.concat(a); });
      feed.sort(function(a,b){ return new Date(b.pubDate) - new Date(a.pubDate); });
      var noticiasFiltradas = feed.filter(function(it){
        var texto=(it.title+' '+it.description).toUpperCase();
        return FILTROS_POP.some(function(t){ return texto.indexOf(t)!==-1; });
      });
      // Se o filtro esvaziar, cai pra manchete pura pra não deixar o widget vazio
      var base = noticiasFiltradas.length ? noticiasFiltradas : feed;
      // Completa ate MAX_TOTAL (30) com as manchetes mais recentes que sobraram,
      // para o carrossel sempre ter 5 em destaque + 25 no rolar.
      if(base.length < MAX_TOTAL){
        feed.forEach(function(f){ if(base.length<MAX_TOTAL && base.indexOf(f)===-1) base.push(f); });
      }
      var top = base.slice(0, MAX_TOTAL);
      // Fase 2: casa cada notícia com um item do TMDB (search/multi) pra liberar trailer/pop
      var jobs = top.map(function(n){
        var q = limparQuery(n.title);
        if(!q) return Promise.resolve(mapNews(n,null));
        var url = TMDB+'/search/multi?api_key='+TMDB_KEY+'&language=pt-BR&include_adult=false&query='+encodeURIComponent(q);
        return fetchJSON(url).then(function(d){
          var hit=null;
          if(d && d.results){
            for(var i=0;i<d.results.length;i++){
              var r=d.results[i];
              if(r.media_type==='movie' || r.media_type==='tv'){ hit=r; break; }
            }
          }
          return mapNews(n,hit);
        }).catch(function(){ return mapNews(n,null); });
      });
      return Promise.all(jobs);
    });
  }
  function mapNews(n, hit){
    // Imagem SEMPRE do TMDB quando houver correspondência (HD);
    // o thumbnail do RSS é apenas último recurso.
    var poster = hit && hit.poster_path  ? TMDB_IMG_POSTER + hit.poster_path
               : hit && hit.backdrop_path ? TMDB_IMG_BACK + hit.backdrop_path
               : (n.thumbnail || '');
    var back   = hit && hit.backdrop_path ? TMDB_IMG_BACK + hit.backdrop_path
               : hit && hit.poster_path   ? TMDB_IMG_POSTER + hit.poster_path
               : (poster || n.thumbnail || '');
    var cat    = tnEditoria(n, hit);
    var mapped = {
      // Sempre 'news': o texto exibido vem da materia real. O vinculo
      // TMDB (id/tipo) fica guardado so para imagem HD, trailer e o
      // botao "saber mais" no rodape do modal.
      type: 'news',
      tmdbType: hit ? hit.media_type : null,
      tmdbId:   hit ? hit.id : null,
      title:    n.title,
      summary:  stripHtml(n.description).slice(0,240),
      image:    poster,
      hero:     back,
      date:     n.pubDate || new Date().toISOString(),
      category: cat,
      rating:   hit ? (hit.vote_average||0) : 0,
      url:      n.link,       // link do artigo original (Omelete/JN/CinePOP/Canaltech)
      source:   n.fonte,      // fonte pra exibir "via Omelete", etc.
      intl:     !!n.intl,     // materia em ingles (Variety, Collider, THR, CosmicBook)
      author:   n.author,
      // Texto integral disponivel no feed (quando o RSS entrega o post inteiro)
      feedHtml: ((n.content||'').length >= (n.description||'').length ? (n.content||'') : (n.description||'')),
      html:     ((n.content||'').length >= (n.description||'').length ? (n.content||'') : (n.description||''))
    };
    mapped.headline = (typeof makeHeadline==='function') ? makeHeadline(mapped) : ('DIRETO DA REDAÇÃO — '+ (mapped.source||'').toUpperCase());
    return mapped;
  }

  function mapItem(it,type,cat){
    var title=it.title||it.name||'Sem título';
    var poster=it.poster_path?TMDB_IMG_POSTER+it.poster_path:'';
    var back=it.backdrop_path?TMDB_IMG_BACK+it.backdrop_path:poster;
    var date=it.release_date||it.first_air_date||new Date().toISOString();
    var mapped={type:'tmdb',tmdbType:type,tmdbId:it.id,title:title,summary:it.overview||'',image:poster,hero:back,date:date,category:cat,rating:it.vote_average||0};
    mapped.headline=makeHeadline(mapped);
    return mapped;
  }

  function fetchBlogger(){
    var url='/feeds/posts/default/-/'+encodeURIComponent(LABEL_BLOG)+'?alt=json&max-results=10';
    return fetchJSON(url).then(function(d){
      if(!d||!d.feed||!d.feed.entry) return [];
      return d.feed.entry.map(function(e){
        var title=e.title.$t;
        var html=(e.content&&e.content.$t)||(e.summary&&e.summary.$t)||'';
        var m=html.match(/<img[^>]+src=["']([^"']+)["']/i);
        var img=m?m[1]:'';
        var link='#';
        if(e.link){for(var i=0;i<e.link.length;i++){if(e.link[i].rel==='alternate'){link=e.link[i].href;break;}}}
        var tags=(e.category||[]).map(function(c){return c.term;});
        var mapped={type:'blog',title:title,image:img,hero:img,date:e.published.$t,category:(tags[0]||'REDAÇÃO').toUpperCase(),url:link,html:html,tags:tags};
        mapped.headline='DIRETO DA REDAÇÃO:';
        return mapped;
      });
    });
  }

  // === REAL NEWS — Cascata de 6 APIs (APITube -> WorldNews -> GNews -> TheNewsAPI -> Currents -> SerpAPI) ===
  // Chaves expostas por exigencia do Blogger (sem backend). Rotacionar
  // periodicamente e/ou colocar atras de um proxy (Cloudflare Worker).
  var NEWS_KEYS = {
    apitube:    'api_live_pSzFBZt0wbrVfgeiwih1lfT5LJ7yuGHq9HExsqDJmYyXR4keQD',
    worldnews:  '36c3d17d62414ddc900b76cc0afae105',
    gnews:      '85d437459b8eee8db07c84048703e3cc',
    thenewsapi: '18rETs8c9h0RrApnTNNJLRQW8grZABCU8ZxjXg5z',
    currents:   'PxY-6ChrGliVrc6uOlUezjFmTKSfuVy9TIdbaPbeFL186cNz',
    serpapi:    '559f1794bf61c6ad52a9e6b12f761771366ba9d5c7133e0e98d96678803282c8'
  };
  // Proxy leve para evitar CORS quando a API nao autoriza browser diretamente.
  // AllOrigins e publico e nao expoe a chave (a URL final ja carrega a chave
  // como parametro, entao continua publica de qualquer forma).
  function corsWrap(url){ return 'https://api.allorigins.win/raw?url=' + encodeURIComponent(url); }
  function safeFetchJSON(url, useProxy){
    var target = useProxy ? corsWrap(url) : url;
    return fetch(target, { headers: { 'accept':'application/json' } })
      .then(function(r){ if(!r.ok) throw new Error('HTTP '+r.status); return r.json(); })
      .catch(function(){ if(useProxy) return null; return fetch(corsWrap(url)).then(function(r){ return r.ok ? r.json() : null; }).catch(function(){ return null; }); });
  }

  // Nichos monitorados (13 categorias solicitadas)
  var WNEWS_QUERIES = [
    { q:'cinema OR filme',                    cat:'CINEMA' },
    { q:'series OR serie',                    cat:'SERIES' },
    { q:'TV OR television',                   cat:'TV' },
    { q:'anime OR manga',                     cat:'ANIME' },
    { q:'HBO',                                cat:'HBO' },
    { q:'HBO Max',                            cat:'HBOMAX' },
    { q:'Netflix',                            cat:'NETFLIX' },
    { q:'Paramount+ OR Paramount Pictures',   cat:'PARAMOUNT' },
    { q:'Apple TV+',                          cat:'APPLETV' },
    { q:'Warner Bros OR Warner',              cat:'WARNER' },
    { q:'DC Comics OR DCU',                   cat:'DC' },
    { q:'Marvel',                             cat:'MARVEL' },
    { q:'Prime Video OR Amazon Prime Video',  cat:'PRIME VIDEO' }
  ];

  // === FILTRO DE NICHO (garante que so entrem noticias dos nichos pedidos) ===
  // Termos globais de cultura pop/audiovisual: a materia precisa citar
  // pelo menos um deles no titulo/resumo, alem do termo do proprio feed.
  var NICHE_RX = new RegExp([
    'cinema','filme','filmes','movie','serie','series','seriado','temporada','episodio',
    'estreia','lancamento','trailer','teaser','elenco','diretor','diretora','ator','atriz',
    'bilheteria','streaming','anime','mangá','manga','otaku','quadrinho','hq','comics',
    'netflix','hbo','max','disney','star\\+','paramount','apple tv','prime video','amazon prime',
    'warner','dc','dcu','marvel','mcu','pixar','a24','oscar','emmy','globo de ouro','spin-?off',
    'reboot','franquia','showrunner','box office','tv','televisao','televisão'
  ].join('|'), 'i');
  // Assuntos que costumam vazar das APIs generalistas e nao pertencem ao blog.
  var OFFNICHE_RX = new RegExp([
    'futebol','eleic','eleiç','política','politica','senado','congresso','inflac','inflaç',
    'bolsa de valores','dólar','dolar','covid','vacina','homicid','assassinat','tráfico','trafico',
    'acidente','clima','previsao do tempo','previsão do tempo','guerra','concurso público',
    'concurso publico','loteria','mega-sena','arqueolog','saude','saúde','receita federal'
  ].join('|'), 'i');
  function isOnNiche(feed, item){
    var txt = ((item.title||'') + ' ' + (item.summary||'')).toLowerCase();
    if(!txt.trim()) return false;
    if(OFFNICHE_RX.test(txt)) return false;
    // termo especifico do feed (ex.: netflix, marvel, anime...) OU termo geral do nicho
    var feedTerms = (feed.q||'').split(/\s+OR\s+/i)
      .map(function(t){ return t.trim().toLowerCase(); })
      .filter(Boolean);
    var hitFeed = feedTerms.some(function(t){ return txt.indexOf(t) > -1; });
    return hitFeed || NICHE_RX.test(txt);
  }

  function extractImg(html){
    if(!html) return '';
    var m = html.match(/<img[^>]+src=["']([^"']+)["']/i);
    return m ? m[1] : '';
  }
  // Verniz pt-BR quando a API devolve em ingles
  // So traduz materia estrangeira: em texto ja em portugues o dicionario
  // quebrava palavras validas ("show", "star", "cast").
  function toPtBR(s, forcar){
    if(!s) return s;
    if(!forcar) return s;
    var dict = {
      '\\bseason\\b':'temporada','\\bseries\\b':'serie','\\bshow\\b':'serie',
      '\\bmovie\\b':'filme','\\bfilm\\b':'filme','\\btrailer\\b':'trailer',
      '\\brelease\\b':'lancamento','\\breleased\\b':'lancado','\\breleases\\b':'lancamentos',
      '\\bpremiere\\b':'estreia','\\bpremieres\\b':'estreia',
      '\\bepisode\\b':'episodio','\\bepisodes\\b':'episodios',
      '\\bcast\\b':'elenco','\\bstar\\b':'estrela','\\bstars\\b':'estrelam',
      '\\bdirector\\b':'diretor','\\bdirected\\b':'dirigido','\\bdirects\\b':'dirige',
      '\\bstreaming\\b':'streaming','\\bnews\\b':'noticia',
      '\\bconfirmed\\b':'confirmado','\\brevealed\\b':'revelado',
      '\\bannounced\\b':'anunciado','\\bteaser\\b':'teaser',
      '\\bsequel\\b':'continuacao','\\bprequel\\b':'preludio','\\bspin-?off\\b':'derivado',
      '\\breboot\\b':'reboot','\\bfranchise\\b':'franquia',
      '\\bshowrunner\\b':'showrunner','\\bfootage\\b':'imagens',
      '\\bactor\\b':'ator','\\bactress\\b':'atriz','\\bcharacter\\b':'personagem',
      '\\bcomics?\\b':'quadrinhos','\\bissue\\b':'edicao'
    };
    var out = s;
    for(var k in dict){ out = out.replace(new RegExp(k,'gi'), dict[k]); }
    return out;
  }

  // Normaliza qualquer artigo para o shape que o resto do widget espera
  function normalize(feed, n, providerLabel){
    var img = n.image || n.urlToImage || n.image_url
           || (n.media && (n.media.image || (n.media[0] && n.media[0].url)))
           || (n.thumbnail) || extractImg(n.body || n.content || n.text || n.snippet || '');
    var title = toPtBR(n.title || n.name || '');
    var summary = toPtBR((n.description || n.summary || n.body || n.content || n.snippet || '')
                         .replace(/<[^>]+>/g,'').slice(0,420));
    var src = (n.source && (n.source.name || n.source.domain))
           || n.source_name || n.author || providerLabel;
    return {
      type:'news',
      title:title, summary:summary,
      image:img, hero:img,
      date: n.published_at || n.publishedAt || n.publish_date || n.date || n.pubDate || new Date().toISOString(),
      category: feed.cat,
      url: n.href || n.url || n.link,
      source: src,
      wnRaw: n,
      headline: makeHeadline({ category: feed.cat })
    };
  }
  function finish(feed, list, providerLabel){
    return (list||[]).map(function(n){ return normalize(feed,n,providerLabel); })
                      .filter(function(x){ return !!x.image && !!x.title; })
                      .filter(function(x){ return isOnNiche(feed, x); });
  }

  // === Provedores individuais ===
  function providerAPITube(feed){
    var url = 'https://api.apitube.io/v1/news/everything?'
      + 'api_key=' + encodeURIComponent(NEWS_KEYS.apitube)
      + '&title=' + encodeURIComponent(feed.q)
      + '&language.code=pt&sort.by=published_at&sort.order=desc&per_page=6';
    return safeFetchJSON(url, false).then(function(d){
      var list = d && (d.results || d.articles || d.news || d.data) || [];
      if(!list.length) throw new Error('empty');
      return finish(feed, list, 'APITube');
    });
  }
  function providerWorldNews(feed){
    var url = 'https://api.worldnewsapi.com/search-news?'
      + 'api-key=' + encodeURIComponent(NEWS_KEYS.worldnews)
      + '&text=' + encodeURIComponent(feed.q)
      + '&language=pt&sort=publish-time&sort-direction=DESC&number=6';
    return safeFetchJSON(url, false).then(function(d){
      var list = (d && d.news) || [];
      if(!list.length) throw new Error('empty');
      return finish(feed, list, 'WorldNewsAPI');
    });
  }
  function providerGNews(feed){
    var url = 'https://gnews.io/api/v4/search?'
      + 'q=' + encodeURIComponent(feed.q)
      + '&lang=pt&max=6&sortby=publishedAt&apikey=' + encodeURIComponent(NEWS_KEYS.gnews);
    return safeFetchJSON(url, false).then(function(d){
      var list = (d && d.articles) || [];
      if(!list.length) throw new Error('empty');
      return finish(feed, list, 'GNews');
    });
  }
  function providerTheNewsAPI(feed){
    var url = 'https://api.thenewsapi.com/v1/news/all?'
      + 'api_token=' + encodeURIComponent(NEWS_KEYS.thenewsapi)
      + '&search=' + encodeURIComponent(feed.q)
      + '&language=pt&limit=6&sort=published_at';
    return safeFetchJSON(url, false).then(function(d){
      var list = (d && d.data) || [];
      if(!list.length) throw new Error('empty');
      return finish(feed, list, 'TheNewsAPI');
    });
  }
  function providerCurrents(feed){
    var url = 'https://api.currentsapi.services/v1/search?'
      + 'keywords=' + encodeURIComponent(feed.q)
      + '&language=pt&apiKey=' + encodeURIComponent(NEWS_KEYS.currents);
    return safeFetchJSON(url, false).then(function(d){
      var list = (d && d.news) || [];
      if(!list.length) throw new Error('empty');
      return finish(feed, list, 'CurrentsAPI');
    });
  }
  function providerSerpAPI(feed){
    // SerpAPI - Google News. Chamado via proxy porque SerpAPI nao habilita CORS.
    var url = 'https://serpapi.com/search.json?engine=google_news&hl=pt-br&gl=br'
      + '&q=' + encodeURIComponent(feed.q)
      + '&api_key=' + encodeURIComponent(NEWS_KEYS.serpapi);
    return safeFetchJSON(url, true).then(function(d){
      var raw = (d && d.news_results) || [];
      // flatten stories
      var list = [];
      raw.forEach(function(n){
        if(n.stories && n.stories.length){
          n.stories.forEach(function(s){ list.push({title:s.title, url:s.link, image:s.thumbnail, date:s.date, source:(s.source&&s.source.name)||''}); });
        } else {
          list.push({title:n.title, url:n.link, image:n.thumbnail, date:n.date, source:(n.source&&n.source.name)||''});
        }
      });
      list = list.slice(0,6);
      if(!list.length) throw new Error('empty');
      return finish(feed, list, 'GoogleNews');
    });
  }

  // Cascata: tenta providers em ordem. Primeiro que devolver >=1 item vence.
  function fetchWorldNews(feed){
    // Ordem validada em 27/07/2026 (teste real de cada chave):
    // APITube 200 OK | GNews 200 OK (plano free = atraso de 12h)
    // TheNewsAPI 200 OK | Currents 200 OK | SerpAPI 200 OK
    // WorldNewsAPI 402 (limite diario de pontos esgotado) -> vai para o fim da fila
    var chain = [providerAPITube, providerGNews, providerTheNewsAPI,
                 providerCurrents, providerSerpAPI, providerWorldNews];
    var i = 0;
    function tryNext(){
      if(i >= chain.length) return Promise.resolve([]);
      var fn = chain[i++];
      return fn(feed).then(function(arr){
        if(arr && arr.length) return arr;
        return tryNext();
      }).catch(function(){ return tryNext(); });
    }
    return tryNext();
  }


  // === SOMENTE TMDB (as APIs de noticia generalistas foram desligadas:
  // eram lentas e vazavam materias fora dos nichos). Aqui so entra
  // "breaking": lancamentos quentes da janela recente/proxima. ===
  var BREAK_BACK_DAYS = 45;   // ja lancado ha no maximo 45 dias
  var BREAK_FWD_DAYS  = 120;  // ou estreando nos proximos 120 dias
  function isBreaking(it){
    var t = new Date(it.date).getTime();
    if(isNaN(t)) return false;
    var now = Date.now(), DAY = 86400000;
    return t >= now - BREAK_BACK_DAYS*DAY && t <= now + BREAK_FWD_DAYS*DAY;
  }
  function dedupe(list){
    var seen = {};
    return list.filter(function(x){
      if(!x || !x.image) return false;
      var k = (x.title||'') + '|' + (x.tmdbId || x.url || '');
      if(seen[k]) return false; seen[k] = true;
      return true;
    });
  }
  // Fase 1: trending do dia (1 request) -> primeira pintura quase instantanea
  function loadFast(){
    return fetchTrending().then(function(list){
      return dedupe((list||[]).filter(isBreaking)).slice(0, MAX_TOTAL);
    });
  }
  // Fase 2: completa com estudios/streamings + redacao do proprio blog
  function loadAll(){
    var jobs = [fetchTrending(), fetchBlogger()]
      .concat(COMPANIES.map(fetchByCompany))
      .concat(NETWORKS.map(fetchByNetwork));
    return Promise.all(jobs.map(function(p){
      return p.catch(function(){ return []; });
    })).then(function(chunks){
      var all = [];
      chunks.forEach(function(arr){ if(arr && arr.length) all = all.concat(arr); });
      all = all.filter(function(x){ return x.type === 'blog' ? true : isBreaking(x); });
      all.sort(function(a,b){ return new Date(b.date) - new Date(a.date); });
      return dedupe(all).slice(0, MAX_TOTAL);
    });
  }


  function render(){
    if(!items.length){track.innerHTML='<div class="trend-news-loading">Nenhuma trend rolando agora. Volta já!</div>';return;}
    track.innerHTML=items.map(function(it,i){
      var img=it.image||'https://via.placeholder.com/500x750/131c30/9aa3b2?text=CALLANGO';
      var badge = it.type==='news' ? 'NOTÍCIA' : (it.type==='blog' ? 'REDAÇÃO' : 'TREND');
      return '<button class="tn-card" data-idx="'+i+'" type="button">'
        +'<div class="tn-thumb"><span class="tn-badge">'+badge+'</span><img loading="lazy" src="'+esc(img)+'" alt="'+esc(it.title)+'"/><div class="tn-cat-bottom">'+esc(it.category)+'</div></div>'
        +'<div class="tn-body"><div class="tn-headline">'+esc(it.headline||it.title)+'</div><div class="tn-title">'+esc(it.title)+'</div></div>'
        +'</button>';
    }).join('');
    updateArrows();
  }

  function fetchDetails(it){
    if(it.type!=='tmdb'||!it.tmdbId) return Promise.resolve(null);
    var url=TMDB+'/'+it.tmdbType+'/'+it.tmdbId+'?api_key='+TMDB_KEY+'&language=pt-BR&append_to_response=credits';
    return fetchJSON(url);
  }

  // Story builder — usa openers/bridges/closers + amostras do site, sem repetição
  function buildStory(it,det){
    var lines=[];
    var opener = pickNoRepeat('open', STYLE.openers);
    var bridge = pickNoRepeat('bridge', STYLE.bridges);
    var closer = pickNoRepeat('close', STYLE.closers);
    var whatIs = (it.tmdbType==='tv') ? 'A nova série' : (it.category==='ANIMAÇÃO'||it.category==='ANIME'?'A nova animação':'O novo título');
    var where  = (it.tmdbType==='tv') ? 'sua próxima maratona' : 'a próxima sessão de cinema';

    // Monta a abertura variando entre múltiplos templates,
    // sem a repetição do bordão "aqui na redação... não podia deixar passar batido".
    var introTemplates = [
      '<p>'+opener+' <strong>'+esc(it.title)+'</strong> '+bridge+'. '+whatIs+' promete agitar '+where+'.</p>',
      '<p>'+opener+' <strong>'+esc(it.title)+'</strong> — '+whatIs+' que '+bridge+'.</p>',
      '<p><strong>'+esc(it.title)+'</strong> chegou e '+bridge+'. '+opener.replace(/[:,]$/,'')+', olha só o tamanho da conversa que vem por aí.</p>',
      '<p>'+opener+' '+whatIs+' <strong>'+esc(it.title)+'</strong> '+bridge+', e a agenda de '+where+' precisa abrir espaço.</p>',
      '<p>Se depender de <strong>'+esc(it.title)+'</strong>, '+where+' ganha combustível novo — '+bridge+'.</p>'
    ];
    var intro = pickNoRepeat('intro', introTemplates);
    lines.push(intro);

    if(it.summary) lines.push('<p>'+esc(it.summary)+'</p>');

    // Injeta uma frase amostrada do site (se houver)
    if(STYLE.sitePhrases.length){
      var phrase = pickNoRepeat('site', STYLE.sitePhrases);
      if(phrase) lines.push('<p><em>Um trecho na vibe da casa:</em> &#8220;'+esc(phrase)+'&#8221;</p>');
    }

    if(det){
      if(det.genres&&det.genres.length) lines.push('<p><strong>Gêneros:</strong> '+det.genres.map(function(g){return esc(g.name);}).join(', ')+'.</p>');
      if(det.credits&&det.credits.cast&&det.credits.cast.length){
        var cast=det.credits.cast.slice(0,5).map(function(c){return esc(c.name);}).join(', ');
        lines.push('<p><strong>No elenco:</strong> '+cast+'.</p>');
      }
      if(det.tagline) lines.push('<div class="tn-quote">&#8220;'+esc(det.tagline)+'&#8221;</div>');
      if(det.production_companies&&det.production_companies.length) lines.push('<p><strong>Produção:</strong> '+det.production_companies.slice(0,3).map(function(c){return esc(c.name);}).join(', ')+'.</p>');
    }

    lines.push('<p><em>'+closer+'</em></p>');
    return lines.join('');
  }

  // === Reescrita de notícias reais no vocabulário do Márcio Oliveira ===
  // REGRA: nada de fato inventado. Só o conteúdo da matéria original,
  // com o tempero de linguagem do vocabulário oficial (MarcioVoice).
  function tnPickVoice(bucket, fallback){
    try{
      if(window.MarcioVoice && window.MarcioVoice.pick){
        var v = window.MarcioVoice.pick(bucket);
        if(v) return v;
      }
    }catch(e){}
    return fallback || '';
  }
  function tnTmdbUrl(it){
    if(!it || !it.tmdbId) return '';
    return 'https://www.themoviedb.org/' + (it.tmdbType==='tv'?'tv':'movie') + '/' + it.tmdbId + '?language=pt-BR';
  }
  // --- Limpeza: tira publicidade, chamadas internas e referencias ao site de origem
  var TN_LIXO_RX = /(publicidade|an[uú]ncio|advertisement|continua ap[oó]s|leia (também|mais|tamb[ée]m)|read more|veja também|assine|newsletter|siga o|inscreva|copyright|todos os direitos|all rights reserved|clique aqui|sign up|subscribe|related:|more from|this article|our site|our newsletter|foto:|imagem:|cr[ée]dito:|getty images|via\s)/i;
  var TN_FONTES_RX = /\b(variety|collider|the hollywood reporter|hollywood reporter|thr|cosmic ?book( news)?|deadline|omelete|jovem nerd|cinepop|canaltech|screen ?rant|comicbook\.com)\b/gi;

  function tnLimpaParagrafo(t){
    var s = tnAjustaTexto(tnDecode(t));
    if(!s) return '';
    if(s.length < 28) return '';                 // legendas, botoes, migalhas
    if(TN_LIXO_RX.test(s)) return '';            // ads / auto-promo / creditos
    // o nome da fonte so e removido quando o paragrafo inteiro e um
    // credito solto; antes ele era apagado no meio da frase
    if(!s.replace(TN_FONTES_RX,'').replace(/^\s*(por|by|via|fonte)\s*:?\s*/i,'').trim()) return '';
    s = s.replace(/^\s*(por|by|via|fonte)\s*:?\s*/i,'')
         .replace(/^[\s,;:–—-]+/,'')
         .replace(/\s{2,}/g,' ')
         .trim();
    if(s.length < 28) return '';
    return s;
  }

  // Extrai o corpo integral da materia original (via proxies publicos de CORS)
  function tnFetchArticle(url){
    if(!url || url === '#') return Promise.resolve([]);
    var proxies = [
      'https://api.allorigins.win/raw?url=' + encodeURIComponent(url),
      'https://corsproxy.io/?' + encodeURIComponent(url),
      'https://r.jina.ai/' + url
    ];
    function tenta(i){
      if(i >= proxies.length) return Promise.resolve([]);
      return fetch(proxies[i]).then(function(r){
        if(!r.ok) throw new Error('proxy ' + r.status);
        return r.text();
      }).then(function(txt){
        var paras = (proxies[i].indexOf('r.jina.ai') > -1)
          ? tnParagrafosDeTexto(txt)
          : tnParagrafosDeHTML(txt);
        if(!paras.length) throw new Error('vazio');
        return paras;
      }).catch(function(){ return tenta(i+1); });
    }
    return tenta(0);
  }

  function tnParagrafosDeHTML(html){
    var out = [];
    try{
      var doc = new DOMParser().parseFromString(html, 'text/html');
      ['script','style','noscript','iframe','aside','nav','footer','header','form',
       '.ad','.ads','.advert','.advertisement','[class*="ad-"]','[id*="ad-"]',
       '[class*="newsletter"]','[class*="related"]','[class*="share"]','[class*="promo"]',
       '[class*="subscribe"]','[class*="paywall"]','figcaption'].forEach(function(sel){
        try{ doc.querySelectorAll(sel).forEach(function(n){ n.remove(); }); }catch(e){}
      });
      var cand = doc.querySelector('article, [itemprop="articleBody"], .article-body, .articleBody, .entry-content, .post-content, .content-body, .c-content, main') || doc.body;
      if(!cand) return out;
      cand.querySelectorAll('p, h2, h3, h4, li, blockquote').forEach(function(el){
        try{ if(el.closest && el.closest('figure')) return; }catch(e){}
        var t = tnLimpaParagrafo(el.textContent);
        if(t && out.indexOf(t) === -1) out.push(t);
      });
      // feeds que entregam o texto sem <p> (bloco unico)
      if(!out.length){
        stripHtml(cand.innerHTML).split(/\n+/).forEach(function(linha){
          var t = tnLimpaParagrafo(linha);
          if(t && out.indexOf(t) === -1) out.push(t);
        });
      }
    }catch(e){}
    return out;
  }

  function tnParagrafosDeTexto(txt){
    return String(txt||'')
      .split(/\n{2,}/)
      .map(tnLimpaParagrafo)
      .filter(function(t, i, arr){ return t && arr.indexOf(t) === i; });
  }

  // Reinterpreta a materia no vocabulario do Marcio Oliveira (sem inventar fato)
  function tnReinterpreta(paras, it){
    var lines = [];
    var abertura = tnPickVoice('aberturas', 'Direto da redação');
    lines.push('<p>' + esc(abertura) + ': <strong>' + esc(it.title) + '</strong>.</p>');
    var usados = {};
    paras.forEach(function(p, i){
      var t = tnAjustaTexto(toPtBR(p, !!(it && it.intl)));
      // tempero: um conector da casa a cada 3 paragrafos, sem repetir
      if(i > 0 && i % 3 === 0){
        var con = tnPickVoice('conectores', '');
        if(con && !usados[con]){
          usados[con] = 1;
          t = con.charAt(0).toUpperCase() + con.slice(1) + ', ' + t.charAt(0).toLowerCase() + t.slice(1);
        }
      }
      lines.push('<p>' + esc(t) + '</p>');
    });
    var veredicto = tnPickVoice('veredictos', '');
    if(veredicto) lines.push('<p><em>' + esc(veredicto) + '</em></p>');
    return lines;
  }

  function tnRodape(it){
    var out = [];
    if(it.url && it.url !== '#'){
      out.push('<p style="font-size:.9em;opacity:.8;"><strong>Fonte:</strong> '
        + '<a href="' + esc(it.url) + '" target="_blank" rel="noopener" '
        + 'style="color:#e50914;font-weight:700;">' + esc(it.source || 'Ler matéria original') + ' &rarr;</a></p>');
    }
    out.push('<div class="tn-tmdb-extra" data-tn-extra="1"></div>');
    return out;
  }

  // Render imediato: usa o que ja veio do feed (integral quando disponivel)
  function buildNewsStory(it){
    var paras = [];
    if(it.feedHtml) paras = tnParagrafosDeHTML(it.feedHtml);
    if(!paras.length && it.summary) paras = tnParagrafosDeTexto(stripHtml(it.summary));
    if(!paras.length) paras = [];
    var lines = tnReinterpreta(paras, it);
    if(!paras.length) lines.push('<p class="tn-loading-full" style="opacity:.7;">Buscando a matéria completa...</p>');
    return lines.concat(tnRodape(it)).join('');
  }

  // Hidrata o modal com o texto INTEGRAL da materia original
  function tnHydrateFullStory(it, contentEl){
    if(!contentEl || !it || !it.url || it.url === '#') return;
    var alvo = it.url;
    tnFetchArticle(alvo).then(function(paras){
      if(!paras || paras.length < 2) return;
      if(!contentEl.isConnected) return;
      if(window.__tnCurrentUrl !== alvo) return; // usuario ja trocou de noticia
      contentEl.innerHTML = tnReinterpreta(paras, it).concat(tnRodape(it)).join('');
      tnEnrichTMDB(it, contentEl);
    }).catch(function(){});
  }

  // Rodapé: trailer oficial (quando existir) + CTA para o perfil TMDB
  function tnEnrichTMDB(it, root){
    if(!it || !root) return;
    var box = root.querySelector('.tn-tmdb-extra');
    if(!box) return;
    if(!it.tmdbId){ box.innerHTML=''; return; }
    var tipo = (it.tmdbType==='tv') ? 'tv' : 'movie';
    var base = TMDB + '/' + tipo + '/' + it.tmdbId;
    Promise.all([
      fetchJSON(base + '?api_key=' + TMDB_KEY + '&language=pt-BR').catch(function(){return null;}),
      fetchJSON(base + '/videos?api_key=' + TMDB_KEY + '&language=pt-BR').catch(function(){return null;}),
      fetchJSON(base + '/videos?api_key=' + TMDB_KEY + '&language=en-US').catch(function(){return null;})
    ]).then(function(res){
      var det = res[0] || {};
      var vids = [].concat((res[1]&&res[1].results)||[], (res[2]&&res[2].results)||[]);
      var trailer = null, teaser = null;
      vids.forEach(function(v){
        if(!v || v.site !== 'YouTube') return;
        if(!trailer && v.type === 'Trailer') trailer = v;
        if(!teaser && v.type === 'Teaser') teaser = v;
      });
      var video = trailer || teaser;
      var estreia = det.release_date || det.first_air_date || '';
      var html = '';

      // Ficha objetiva (dados do TMDB, sem opinião inventada)
      var ficha = [];
      if(det.title || det.name) ficha.push('<strong>'+esc(det.title || det.name)+'</strong>');
      if(estreia){
        var d = new Date(estreia + 'T00:00:00');
        if(!isNaN(d)){
          var futuro = d.getTime() > Date.now();
          ficha.push((futuro ? 'Estreia em ' : 'Lançado em ') + d.toLocaleDateString('pt-BR'));
        }
      }
      if(det.genres && det.genres.length) ficha.push(det.genres.slice(0,3).map(function(g){return esc(g.name);}).join(', '));
      if(det.vote_average) ficha.push('Nota TMDB ' + det.vote_average.toFixed(1));
      if(ficha.length) html += '<p style="font-size:.92em;opacity:.85;margin-top:14px;">'+ficha.join(' &bull; ')+'</p>';

      if(video){
        html += '<div class="tn-trailer" style="margin:14px 0;">'
          + '<div style="font-weight:800;letter-spacing:.04em;margin-bottom:8px;color:#e50914;">TRAILER OFICIAL</div>'
          + '<div style="position:relative;padding-top:56.25%;border-radius:12px;overflow:hidden;background:#000;">'
          + '<iframe src="https://www.youtube.com/embed/' + esc(video.key) + '?rel=0" '
          + 'title="Trailer" loading="lazy" allowfullscreen '
          + 'allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture" '
          + 'style="position:absolute;inset:0;width:100%;height:100%;border:0;"></iframe>'
          + '</div></div>';
      }

      // Botao interno: abre a pagina de obra do proprio Callango Nerd
      // (window.CN.obra), sem sair do site. Fallback: TMDB externo.
      html += '<p class="tn-cta-wrap" style="margin:20px 0 4px;">'
        + '<button type="button" class="tn-cn-obra" data-cn-type="' + esc(tipo) + '" data-cn-id="' + esc(String(it.tmdbId)) + '">'
        + '<span class="tn-cta-txt">Saiba mais ' + (tipo === 'tv' ? 'sobre a série' : 'sobre o filme') + '</span>'
        + '<span class="tn-cta-arrow">&rarr;</span></button></p>';

      box.innerHTML = html;

      var btnObra = box.querySelector('.tn-cn-obra');
      if(btnObra){
        btnObra.addEventListener('click', function(){
          var t = btnObra.getAttribute('data-cn-type')==='tv' ? 'tv' : 'movie';
          var id = btnObra.getAttribute('data-cn-id');
          if(window.CN && typeof window.CN.obra === 'function'){
            var backIdx = window.__tnCurrentIdx;
            try{ closeModal(); }catch(e){}
            if(typeof window.CN.setReturn === 'function'){
              window.CN.setReturn(function(){
                try{ openModal(backIdx); }catch(e){}
              });
            }
            window.CN.obra(t, id);
          } else {
            window.open(tnTmdbUrl(it), '_blank', 'noopener');
          }
        });
      }
    }).catch(function(){ box.innerHTML=''; });
  }

  // Clona o perfil oficial do Márcio (interligado — muda lá, muda aqui) SEM sobrescrever visual
  function buildAuthorBox(){
    var src=document.getElementById('marcioProfile');
    if(!src) return '';
    // Clona o innerHTML preservando exatamente o layout do rodapé do post
    return '<div class="trend-news-author-box" style="display:block;">'+src.innerHTML+'</div>';
  }

  function buildShareBar(it){
    var url = it.type==='blog' && it.url && it.url!=='#' ? it.url : SITE_ORIGIN + '/?trend=' + encodeURIComponent(it.title);
    var text = encodeURIComponent((it.headline?it.headline+' ':'')+it.title+' - via Callango Nerd');
    var u = encodeURIComponent(url);
    return '<div class="trend-news-share">'
      +'<div class="tn-share-label">Compartilhe</div>'
      +'<div class="tn-share-icons">'
      +'<a class="tn-share-ico wa" target="_blank" rel="noopener" aria-label="WhatsApp" title="WhatsApp" href="https://api.whatsapp.com/send?text='+text+'%20'+u+'"><i class="fa-brands fa-whatsapp"></i></a>'
      +'<a class="tn-share-ico tw" target="_blank" rel="noopener" aria-label="X (Twitter)" title="X" href="https://twitter.com/intent/tweet?text='+text+'&amp;url='+u+'"><i class="fa-brands fa-x-twitter"></i></a>'
      +'<a class="tn-share-ico fb" target="_blank" rel="noopener" aria-label="Facebook" title="Facebook" href="https://www.facebook.com/sharer/sharer.php?u='+u+'"><i class="fa-brands fa-facebook-f"></i></a>'
      +'<a class="tn-share-ico tg" target="_blank" rel="noopener" aria-label="Telegram" title="Telegram" href="https://t.me/share/url?url='+u+'&amp;text='+text+'"><i class="fa-brands fa-telegram"></i></a>'
      +'<button type="button" class="tn-share-ico copy" aria-label="Copiar link" title="Copiar link" data-copy="'+esc(url)+'"><i class="fa-solid fa-link"></i></button>'
      +'</div>'
      +'</div>';
  }

  function buildCommentsBox(it){
    var key = 'tnCmts:'+(it.tmdbId||it.url||it.title);
    var stored = [];
    try { stored = JSON.parse(localStorage.getItem(key)||'[]'); } catch(e){ stored=[]; }
    var listHTML = stored.map(function(c){
      return '<li><div class="tn-cmt-who">'+esc(c.name||'Anônimo')+'</div><div class="tn-cmt-txt">'+esc(c.text)+'</div></li>';
    }).join('') || '<li style="opacity:.5;"><div class="tn-cmt-txt">Nenhum comentário ainda. Solta o verbo aí!</div></li>';
    return '<div class="trend-news-comments" data-key="'+esc(key)+'">'
      +'<h3>Comenta <span>aí</span></h3>'
      +'<textarea class="tn-cmt-text" placeholder="Diz aí o que achou dessa trend..."></textarea>'
      +'<div class="tn-cmt-row">'
      +'  <input class="tn-cmt-name" type="text" placeholder="Seu nome (opcional)"/>'
      +'  <button class="tn-cmt-send" type="button">Enviar</button>'
      +'</div>'
      +'<div class="tn-cmt-note">Os comentários ficam salvos no seu navegador nesta prévia. A integração final entra na plataforma oficial.</div>'
      +'<ul class="tn-cmt-list">'+listHTML+'</ul>'
      +'</div>';
  }

  function openModal(idx){
    var it=items[idx]; if(!it) return;
    window.__tnCurrentIdx = idx;
    var nextIdx = (idx+1) % items.length;
    var nextIt = items[nextIdx];
    var prevIdx = (idx-1+items.length) % items.length;
    var prevIt = items.length>1 ? items[prevIdx] : null;

    var heroImg=it.hero||it.image;
    var authorBox=buildAuthorBox();
    var storedFS = parseInt(localStorage.getItem('cn-font-size')||'0',10);
    var initialFS = storedFS >= 14 && storedFS <= 22 ? storedFS : 17;
    var fontRegulatorHTML =
      '<div id="cn-font-regulator" class="tn-font-regulator">'+
        '<span class="tn-fr-label">Regule o tamanho do texto:</span>'+
        '<input type="range" class="tn-fr-range" min="14" max="22" step="1" value="'+initialFS+'" aria-label="Tamanho do texto">'+
        '<span class="tn-fr-max" id="cn-font-current">'+initialFS+'px</span>'+
        '</div>';
    // Categoria em vertical (estilo TREND NEWS / CRÍTICAS)
    var catRaw = (it.category||'NOTICIAS').toString();
    var catParts = catRaw.split(/\s+/);
    var verticalHTML = '<div class="tn-modal-vertical" aria-hidden="true">'
      + '<span class="tnv-word">'+esc(catParts[0]||'')+'</span>'
      + (catParts[1] ? '<span class="tnv-word tnv-alt">'+esc(catParts.slice(1).join(' '))+'</span>' : '')
      + '</div>';
    // Marca d'agua: imagem do post em blur atras do conteudo
    var bgVar = heroImg ? ' style="--tn-hero-bg:url(\''+esc(heroImg).replace(/'/g,"\\'")+'\')"' : '';
    var initial='<div class="tn-modal-shell"'+bgVar+'>'
      + verticalHTML
      +(heroImg?'<div class="tn-hero"><img src="'+esc(heroImg)+'" alt="'+esc(it.title)+'"/><div class="tn-hero-cap"><div class="tn-hero-headline">'+esc(it.headline||'')+'</div><h2>'+esc(it.title)+'</h2></div></div>':'')
      +'<div class="tn-inner">'
      +'  <div class="tn-meta-full">'+esc(it.category)+' <span class="dot">&#183;</span> <span class="tn-m">'+fmtDate(it.date)+'</span>'+(it.rating?' <span class="dot">&#183;</span> <span class="tn-m">&#9733; '+it.rating.toFixed(1)+'</span>':'')+'</div>'
      +'  '+fontRegulatorHTML
      +'  <div class="tn-content" id="tnContent" style="font-size:'+initialFS+'px;line-height:1.8;">'+(it.type==='blog'&&it.html?it.html:'<p>Carregando os detalhes...</p>')+'</div>'
      +(it.type==='blog'&&it.url&&it.url!=='#'?'<p style="margin-top:18px;"><a href="'+esc(it.url)+'" style="color:#e50914;font-weight:800;text-transform:uppercase;letter-spacing:1px;font-size:13px;">Ler post completo &rarr;</a></p>':'')
      +'  '+buildShareBar(it)
      // comentarios removidos
      +'</div>'
      // Perfil do autor SEMPRE no rodape (emula rodape dos posts de Marcio Oliveira)
      + authorBox
      // Botoes "Anterior / Proxima noticia" no rodape do modal-scroll
      + ((prevIt||nextIt) ? '<div class="tn-next-wrap'+((prevIt&&nextIt)?'':' single')+'">'
          + (prevIt ? '<button type="button" class="tn-next-btn prev" data-tn-prev-idx="'+prevIdx+'">'
              + '<span class="tn-next-arrow" aria-hidden="true">&larr;</span>'
              + '<span class="tn-next-label"><span class="tn-next-kicker">Notícia anterior</span><span class="tn-next-title">'+esc(prevIt.title)+'</span></span>'
              + '</button>' : '')
          + (nextIt ? '<button type="button" class="tn-next-btn next" data-tn-next-idx="'+nextIdx+'">'
              + '<span class="tn-next-label"><span class="tn-next-kicker">Próxima notícia</span><span class="tn-next-title">'+esc(nextIt.title)+'</span></span>'
              + '<span class="tn-next-arrow" aria-hidden="true">&rarr;</span>'
              + '</button>' : '')
          + '</div>' : '')
      +'</div>';


    // Escopa a marca d'agua para o scroll do modal
    var scrollEl = modal.querySelector('.trend-news-modal-scroll');
    if(scrollEl && heroImg){ scrollEl.style.setProperty('--tn-hero-bg', "url('"+heroImg.replace(/'/g,"\\'")+"')"); }
    modalBody.innerHTML=initial;
    modal.classList.remove('closing');
    modal.style.display='block';
    void modal.offsetWidth;
    modal.classList.add('open');
    document.body.style.overflow='hidden';

    // Handlers dinâmicos (share + comments)
    // Font regulator (dentro do modal)
    var fontReg = modalBody.querySelector('#cn-font-regulator');
    var tnContentEl = modalBody.querySelector('#tnContent');
    if(fontReg && tnContentEl){
      var fRange = fontReg.querySelector('input[type="range"]');
      var fOut = fontReg.querySelector('#cn-font-current');
      fRange.addEventListener('input', function(){
        var v = parseInt(fRange.value,10);
        tnContentEl.style.setProperty('--tn-fs', v + 'px');
        tnContentEl.style.setProperty('font-size', v + 'px', 'important');
        fOut.textContent = v + 'px';
        try{ localStorage.setItem('cn-font-size', String(v)); }catch(e){}
      });
    }
    var copyBtn = modalBody.querySelector('.tn-share-btn.copy');
    if(copyBtn){
      copyBtn.addEventListener('click', function(){
        var v = copyBtn.getAttribute('data-copy');
        if(navigator.clipboard){ navigator.clipboard.writeText(v); }
        copyBtn.classList.add('copied');
        copyBtn.textContent = 'Link copiado!';
        setTimeout(function(){ copyBtn.classList.remove('copied'); copyBtn.textContent='Copiar link'; }, 1800);
      });
    }
    // bloco de comentarios removido

    // Botoes "Anterior" e "Proxima noticia"
    var nextBtn = modalBody.querySelector('.tn-next-btn.next');
    if(nextBtn){
      nextBtn.addEventListener('click', function(){
        var ni = parseInt(nextBtn.getAttribute('data-tn-next-idx'),10);
        var scrollEl2 = modal.querySelector('.trend-news-modal-scroll');
        if(scrollEl2){ scrollEl2.scrollTop = 0; }
        openModal(ni);
      });
    }
    var prevBtnM = modalBody.querySelector('.tn-next-btn.prev');
    if(prevBtnM){
      prevBtnM.addEventListener('click', function(){
        var pi = parseInt(prevBtnM.getAttribute('data-tn-prev-idx'),10);
        var scrollEl3 = modal.querySelector('.trend-news-modal-scroll');
        if(scrollEl3){ scrollEl3.scrollTop = 0; }
        openModal(pi);
      });
    }


    if(it.type==='tmdb'){
      fetchDetails(it).then(function(det){
        var content=document.getElementById('tnContent');
        if(content){ content.innerHTML=buildStory(it,det); var fr=modalBody.querySelector('#cn-font-regulator input[type="range"]'); if(fr){ var vv=parseInt(fr.value,10); content.style.setProperty('--tn-fs', vv+'px'); content.style.setProperty('font-size', vv+'px', 'important'); } }
      });
    } else if(it.type==='news'){
      var content=document.getElementById('tnContent');
      if(content){ content.innerHTML=buildNewsStory(it); var fr=modalBody.querySelector('#cn-font-regulator input[type="range"]'); if(fr){ var vv=parseInt(fr.value,10); content.style.setProperty('--tn-fs', vv+'px'); content.style.setProperty('font-size', vv+'px', 'important'); } tnEnrichTMDB(it, content); window.__tnCurrentUrl = it.url; tnHydrateFullStory(it, content); }
    }
  }
  function closeModal(){
    if(!modal.classList.contains('open')) return;
    modal.classList.add('closing');
    modal.classList.remove('open');
    setTimeout(function(){
      modal.style.display='';
      modal.classList.remove('closing');
      document.body.style.overflow='';
      modalBody.innerHTML='';
    },340);
  }

  // Navegação carrossel
  function step(){
    var first = track.querySelector('.tn-card');
    if(!first) return viewport.clientWidth * 0.8;
    var style = window.getComputedStyle(track);
    var gap = parseFloat(style.columnGap || style.gap || '18') || 18;
    return first.getBoundingClientRect().width + gap;
  }
  function updateArrows(){
    var max = viewport.scrollWidth - viewport.clientWidth - 2;
    prevBtn.disabled = viewport.scrollLeft <= 2;
    nextBtn.disabled = viewport.scrollLeft >= max;
  }
  prevBtn.addEventListener('click', function(){ viewport.scrollBy({left:-step(), behavior:'smooth'}); });
  nextBtn.addEventListener('click', function(){ viewport.scrollBy({left:step(), behavior:'smooth'}); });
  viewport.addEventListener('scroll', updateArrows, {passive:true});
  window.addEventListener('resize', updateArrows);

  track.addEventListener('click',function(e){var b=e.target.closest('.tn-card');if(!b)return;openModal(parseInt(b.getAttribute('data-idx'),10));});
  modal.addEventListener('click',function(e){if(e.target.getAttribute('data-tn-close'))closeModal();});
  document.addEventListener('keydown',function(e){if(e.key==='Escape')closeModal();});

  function apply(list){
    if(!list || !list.length) return;
    items = list;
    items.forEach(function(it){ it.headline = makeHeadline(it); });
    render();
  }
  function refresh(){
    return loadAll().then(apply);
  }

  // ===== TMDB-backed news provider (substitui TVMaze) =====
  // Usa a mesma chave TMDB do restante do widget. Traz o que está em
  // alta hoje (filmes, séries e animes), monta a manchete no tom
  // Callango Nerd e enriquece os dados brutos para caber nos cards.
  var CN_HEADLINES = {
    PREMIERE: ['ESTREIA CONFIRMADA:','BOMBA GEEK:','DA REDAÇÃO CALLANGO:','PREPARE A PIPOCA:','ALERTA NERD:'],
    EP:       ['NOVO EPISÓDIO NO AR:','SAIU AGORA:','DIRETO DA REDAÇÃO:','EPISÓDIO IMPERDÍVEL:'],
    TREND:    ['NA MIRA DA REDAÇÃO:','FALADO NO MULTIVERSO:','TOPO DA AUDIÊNCIA:','QUEBRANDO A INTERNET:','O NERD APROVA:']
  };
  function cnPickHeadline(kind){
    var pool = CN_HEADLINES[kind] || CN_HEADLINES.TREND;
    return pool[Math.floor(Math.random()*pool.length)];
  }
  function cnPunchUp(txt){
    if(!txt) return '';
    var t = toPtBR ? toPtBR(txt) : txt;
    if(t.length > 260) t = t.slice(0,257).replace(/\s+\S*$/,'') + '...';
    return t;
  }
  function tmdbNewsCategory(it){
    var isTv = it.media_type === 'tv' || !!it.first_air_date;
    var genres = (it.genre_ids || []);
    if(genres.indexOf(16) > -1) return 'ANIMAÇÃO';
    if(genres.indexOf(878) > -1) return isTv ? 'SÉRIES' : 'FICÇÃO CIENTÍFICA';
    if(genres.indexOf(28) > -1) return isTv ? 'SÉRIES' : 'AÇÃO';
    if(genres.indexOf(27) > -1) return 'TERROR';
    if(genres.indexOf(35) > -1) return isTv ? 'SÉRIES' : 'COMÉDIA';
    return isTv ? 'SÉRIES' : 'CINEMA';
  }
  function tmdbNewsItem(it){
    var isTv = it.media_type === 'tv' || !!it.first_air_date;
    var title = it.title || it.name || 'Sem título';
    var overview = it.overview || '';
    var poster = it.poster_path ? TMDB_IMG_POSTER + it.poster_path : '';
    var back   = it.backdrop_path ? TMDB_IMG_BACK + it.backdrop_path : poster;
    if(!poster && !back) return null;
    var date = it.release_date || it.first_air_date || new Date().toISOString();
    var cat = tmdbNewsCategory(it);
    var kind = 'TREND';
    var headlineTitle = title;
    return {
      type: 'tmdb',
      tmdbType: isTv ? 'tv' : 'movie',
      tmdbId: it.id,
      title: headlineTitle,
      summary: cnPunchUp(overview),
      image: poster || back,
      hero: back || poster,
      date: date,
      category: cat,
      url: '#',
      source: 'Callango Nerd / TMDB',
      rating: it.vote_average || 0,
      headline: cnPickHeadline(kind)
    };
  }
  function tmdbFetchTrending(){
    // Trending do dia (all = filmes + séries), em pt-BR
    var url = TMDB + '/trending/all/day?language=pt-BR&api_key=' + TMDB_KEY;
    return fetch(url).then(function(r){return r.ok?r.json():{results:[]};})
      .catch(function(){return {results:[]};})
      .then(function(j){
        var arr = (j && j.results) || [];
        return arr.map(tmdbNewsItem).filter(function(x){ return !!x; });
      });
  }
  function tmdbFetchNowPlaying(){
    var url = TMDB + '/movie/now_playing?language=pt-BR&region=BR&api_key=' + TMDB_KEY + '&page=1';
    return fetch(url).then(function(r){return r.ok?r.json():{results:[]};})
      .catch(function(){return {results:[]};})
      .then(function(j){
        var arr = (j && j.results) || [];
        return arr.map(function(it){ it.media_type='movie'; return tmdbNewsItem(it); })
                  .filter(function(x){ return !!x; })
                  .map(function(x){ x.headline = cnPickHeadline('PREMIERE'); return x; });
      });
  }
  function tmdbFetchAiringToday(){
    var url = TMDB + '/tv/airing_today?language=pt-BR&api_key=' + TMDB_KEY + '&page=1';
    return fetch(url).then(function(r){return r.ok?r.json():{results:[]};})
      .catch(function(){return {results:[]};})
      .then(function(j){
        var arr = (j && j.results) || [];
        return arr.map(function(it){ it.media_type='tv'; return tmdbNewsItem(it); })
                  .filter(function(x){ return !!x; })
                  .map(function(x){ x.headline = cnPickHeadline('EP'); return x; });
      });
  }
  // === FLUXO ÚNICO: NOTÍCIAS REAIS (RSS) + ENRIQUECIMENTO TMDB ===
  // Estágio 1 removido (tmdbNewsLoadFast/trending). A primeira pintura
  // da tela já vem dos feeds reais (Omelete, Jovem Nerd, CinePOP,
  // Canaltech), filtrados por FILTROS_POP e cruzados no /search/multi
  // do TMDB para poster/backdrop em HD.
  function newsLoadAll(){
    return fetchTrending()
      .catch(function(err){ console.warn('[TREND NEWS] RSS falhou:', err); return []; })
      .then(function(list){
        var all = (list || []).filter(function(x){ return x && x.title; });
        all.sort(function(a,b){ return new Date(b.date) - new Date(a.date); });
        return dedupe(all).slice(0, MAX_TOTAL);
      });
  }
  function refreshTV(){ return newsLoadAll().then(apply); }

  // Boot: direto nas notícias reais; o estilo (MarcioVoice) é colhido
  // em paralelo e aplicado na reescrita/no modal assim que chega.
  harvestStyle().catch(function(){}).then(refreshTV).catch(function(){});
  setInterval(refreshTV, REFRESH_MS);

})();
