div.script:
//
// ====== Slot2: versao alternativa e independente do Slot1 ======
(function () {
  var API_KEY = '0344712bb861098caefcc9a8d67beb09';
  var TMDB = 'https://api.themoviedb.org/3';
  var CACHE_KEY = 'tmdbTrailerCache:v2:';
  var CACHE_TTL = 24 * 60 * 60 * 1000;

  function alvo(){ return document.getElementById('slot2-trailer'); }

  function fetchJSON(url, timeoutMs) {
    var ctrl = ('AbortController' in window) ? new AbortController() : null;
    var t = setTimeout(function () { if (ctrl) ctrl.abort(); }, timeoutMs || 8000);
    return fetch(url, ctrl ? { signal: ctrl.signal } : undefined)
      .then(function (r) { clearTimeout(t); if (!r.ok) throw new Error('HTTP ' + r.status); return r.json(); })
      .catch(function (e) { clearTimeout(t); throw e; });
  }
  function cacheGet(k){ try{var raw=sessionStorage.getItem(CACHE_KEY+k); if(!raw) return null; var o=JSON.parse(raw); return (Date.now()-o.t>CACHE_TTL)?null:o.v;}catch(e){return null;} }
  function cacheSet(k,v){ try{sessionStorage.setItem(CACHE_KEY+k,JSON.stringify({t:Date.now(),v:v}));}catch(e){} }

  function limparTitulo(nome) {
    try { nome = decodeURIComponent(nome); } catch (e) {}
    return String(nome)
      .replace(/\.[a-z0-9]{2,5}$/i, '')
      .replace(/[_\-\+]+/g, ' ')
      .replace(/\s\d{2,4}x\d{2,4}\b/gi, '')
      .replace(/\b(1080p|720p|480p|hd|4k|dublado|legendado|torrent|bluray|web-?dl|s\d{1,2}e\d{1,2})\b/gi, '')
      .replace(/\s+/g, ' ')
      .trim();
  }
  function escolherMelhorVideo(results) {
    if (!results || !results.length) return null;
    var yt = results.filter(function (v) { return v.site === 'YouTube' && v.key; });
    if (!yt.length) return null;
    var ordem = [
      function (v) { return v.type === 'Trailer' && v.official; },
      function (v) { return v.type === 'Trailer'; },
      function (v) { return v.type === 'Teaser' && v.official; },
      function (v) { return v.type === 'Teaser'; },
      function () { return true; }
    ];
    for (var i = 0; i < ordem.length; i++) { var m = yt.find(ordem[i]); if (m) return m; }
    return null;
  }
  function buscarVideos(mediaType, id) {
    var url = TMDB + '/' + mediaType + '/' + id + '/videos?api_key=' + API_KEY +
              '&language=pt-BR&include_video_language=pt,en,null';
    return fetchJSON(url).then(function (d) {
      var v = escolherMelhorVideo(d && d.results);
      if (v) return v;
      return fetchJSON(TMDB + '/' + mediaType + '/' + id + '/videos?api_key=' + API_KEY)
        .then(function (d2) { return escolherMelhorVideo(d2 && d2.results); });
    });
  }
  function buscarTrailer(titulo) {
    var cached = cacheGet(titulo);
    if (cached !== null) return Promise.resolve(cached || null);
    var url = TMDB + '/search/multi?api_key=' + API_KEY +
              '&language=pt-BR&include_adult=false&query=' + encodeURIComponent(titulo);
    return fetchJSON(url).then(function (data) {
      var r = ((data && data.results) || []).filter(function (x) { return x.media_type === 'movie' || x.media_type === 'tv'; });
      if (!r.length) { cacheSet(titulo, false); return null; }
      return buscarVideos(r[0].media_type, r[0].id).then(function (v) { cacheSet(titulo, v || false); return v; });
    }).catch(function () { return null; });
  }

  // Varios candidatos de titulo, do mais confiavel para o menos
  function candidatos() {
    var out = [], h = document.querySelector('.post-title, h1.post-title, h1, .entry-title');
    if (h) out.push(limparTitulo(h.textContent));
    var body = document.querySelector('.post-body, .entry-content, article');
    var img = body && body.querySelector('img');
    if (img && img.getAttribute('src')) {
      out.push(limparTitulo(img.getAttribute('src').split('/').pop().split(/[?#]/)[0]));
    }
    if (document.title) out.push(limparTitulo(document.title.split(/[|\-–]/)[0]));
    var vistos = {};
    return out.filter(function (t) { if (!t || t.length < 2 || vistos[t]) return false; vistos[t] = 1; return true; });
  }

  function montar(video) {
    var el = alvo();
    if (!el) return false;
    if (!video || !video.key) return false;
    el.classList.remove('slot2-loading');
    el.innerHTML = '<iframe class="tmdb-trailer-2" loading="lazy" title="Trailer" ' +
      'src="https://www.youtube.com/embed/' + video.key + '?rel=0" frameborder="0" ' +
      'allowfullscreen="true" width="100%" height="360"></iframe>';
    // ==== fundo blur com a propria capa do trailer ====
    var thumb = 'https://i.ytimg.com/vi/' + video.key + '/maxresdefault.jpg';
    var probe = new Image();
    probe.onload = function () {
      var url = (probe.naturalWidth < 200)
        ? 'https://i.ytimg.com/vi/' + video.key + '/hqdefault.jpg'
        : thumb;
      el.style.setProperty('--slot2-bg', 'url("' + url + '")');
      el.classList.add('slot2-has-bg');
    };
    probe.onerror = function () {
      el.style.setProperty('--slot2-bg', 'url("https://i.ytimg.com/vi/' + video.key + '/hqdefault.jpg")');
      el.classList.add('slot2-has-bg');
    };
    probe.src = thumb;
    el.setAttribute('data-slot2-ok', '1');
    return true;
  }

  // Fallback: reaproveita um video do YouTube ja presente no post/slot1
  function fallbackLocal() {
    var el = alvo();
    if (!el) return false;
    var f = document.querySelector('.post-body iframe[src*="youtube"], .post-iframe-wrap iframe[src*="youtube"]');
    if (!f) return false;
    var src = f.getAttribute('src') || '';
    var m = src.match(/(?:embed\/|v=|youtu\.be\/)([A-Za-z0-9_-]{6,})/);
    if (!m) return false;
    return montar({ key: m[1] });
  }

  function semTrailer() {
    var el = alvo();
    if (!el) return;
    if (fallbackLocal()) return;
    el.classList.remove('slot2-loading');
    el.innerHTML = '';
    el.setAttribute('data-slot2-empty', '1');
  }

  var iniciado = false;
  function iniciar() {
    if (iniciado) return; iniciado = true;
    var el = alvo();
    if (!el) return;
    var lista = candidatos();
    if (!lista.length) { semTrailer(); return; }
    (function tentar(i) {
      if (i >= lista.length) { semTrailer(); return; }
      buscarTrailer(lista[i]).then(function (v) {
        if (!montar(v)) tentar(i + 1);
      }).catch(function () { tentar(i + 1); });
    })(0);
  }

  function agendar() {
    var el = alvo();
    if (!el) return;
    // comeca logo se ja estiver visivel; senao observa, com limite de 2s
    if ('IntersectionObserver' in window) {
      var io = new IntersectionObserver(function (entries) {
        if (entries.some(function (e) { return e.isIntersecting; })) { io.disconnect(); iniciar(); }
      }, { rootMargin: '600px' });
      io.observe(el);
    }
    setTimeout(iniciar, 2000);
  }

  if (document.readyState !== 'loading') agendar();
  else document.addEventListener('DOMContentLoaded', agendar);
  window.addEventListener('load', function () { setTimeout(iniciar, 500); });
})();
//

// 
        // Define a URL do seu blog
        const blogUrl = 'https://www.callangonerd.com';

        // Variáveis para controle do carrossel
        let scrollAmount = 0;

        // Função para verificar se a página atual é uma página de postagem
        function isPostPage() {
            const url = window.location.href;
            const postPattern = /\/\d{4}\/\d{2}\/[^\/]+\.html$/; // /YYYY/MM/slug.html
            return postPattern.test(url);
        }

        // Função para ocultar o widget se for uma página de postagem
        function hideWidgetOnPostPage() {
            const widget = document.getElementById('custom-streaming-widget');
            if (widget && isPostPage()) {
                widget.style.display = 'none';
            } else if (widget) {
                widget.style.display = 'flex';
            }
        }

        // Função para atualizar o estado das setas (habilitar/desabilitar)
        function updateArrowStates() {
            const carouselWrapper = document.getElementById('movieCarousel');
            const prevArrow = document.getElementById('prevArrow');
            const nextArrow = document.getElementById('nextArrow');

            if (!carouselWrapper || !prevArrow || !nextArrow) return;

            prevArrow.disabled = carouselWrapper.scrollLeft <= 0;
            nextArrow.disabled = (carouselWrapper.scrollWidth - carouselWrapper.scrollLeft - carouselWrapper.clientWidth) < 5;
        }

        // Função de callback global que será chamada pelo feed JSONP do Blogger
        window.handleBloggerPosts = function(data) {
            const carouselWrapper = document.getElementById('movieCarousel');
            if (!carouselWrapper) {
                console.error('Elemento #movieCarousel não encontrado.');
                return;
            }

            if (data && data.feed && data.feed.entry) {
                const posts = data.feed.entry;

                if (posts.length === 0) {
                    carouselWrapper.innerHTML = '<p class="error-message">Nenhum post encontrado no blog.</p>';
                    updateArrowStates();
                    return;
                }

                carouselWrapper.innerHTML = '';

                posts.forEach((post, index) => {
                    const postLink = post.link.find(link => link.rel === 'alternate' && link.type === 'text/html').href;

                    let thumbnailUrl = '';
                    if (post.media$thumbnail && post.media$thumbnail.url) {
                        thumbnailUrl = post.media$thumbnail.url;
                        thumbnailUrl = thumbnailUrl.replace(/\/s\d+(-c)?\//, '/s500/');
                    } else if (post.content && post.content.$t) {
                        const tempDiv = document.createElement('div');
                        tempDiv.innerHTML = post.content.$t;
                        const img = tempDiv.querySelector('img');
                        if (img && img.src) {
                            thumbnailUrl = img.src;
                            thumbnailUrl = thumbnailUrl.replace(/\/s\d+(-c)?\//, '/s500/');
                        }
                    }

                    const movieCard = document.createElement('a');
                    movieCard.href = postLink;
                    movieCard.classList.add('movie-card');
                    movieCard.setAttribute('target', '_blank');

                    const cardNumber = document.createElement('div');
                    cardNumber.classList.add('card-number');
                    cardNumber.textContent = index + 1;

                    const cardImage = document.createElement('div');
                    cardImage.classList.add('card-image');
                    cardImage.style.backgroundImage = `url('${thumbnailUrl || 'https://placehold.co/500x750/333333/FFFFFF?text=Sem+Imagem'}')`;

                    movieCard.appendChild(cardNumber);
                    movieCard.appendChild(cardImage);
                    carouselWrapper.appendChild(movieCard);
                });

                // Calcula o scrollAmount após os cards serem adicionados ao DOM
                // Usando setTimeout para garantir que as dimensões sejam calculadas após a renderização
                setTimeout(() => {
                    const firstCard = carouselWrapper.querySelector('.movie-card');
                    if (firstCard) {
                        const cardWidth = firstCard.offsetWidth;
                        const margin = parseInt(getComputedStyle(firstCard).marginRight) || 0;
                        scrollAmount = cardWidth + margin;
                        console.log('Calculated scrollAmount:', scrollAmount); // Para depuração
                    } else {
                        console.warn('No movie cards found to calculate scrollAmount.'); // Para depuração
                    }
                    updateArrowStates(); // Atualiza o estado das setas após scrollAmount ser calculado
                }, 0); // Delay de 0ms para deferir a execução
            } else {
                console.error('Estrutura de dados do Blogger feed inesperada:', data);
                carouselWrapper.innerHTML = '<p class="error-message">Erro ao carregar posts: Estrutura de dados inesperada.</p>';
                updateArrowStates();
            }
        };

        // Função para carregar o feed JSONP do Blogger
        function loadBloggerFeed() {
            const carouselWrapper = document.getElementById('movieCarousel');
            if (!carouselWrapper) {
                console.error('Elemento #movieCarousel não encontrado.');
                return;
            }
            carouselWrapper.innerHTML = '<p class="loading-message">Carregando posts...</p>';

            // max-results=10 para 10 posts no total
            const feedUrl = `${blogUrl}/feeds/posts/default?alt=json-in-script&max-results=10&orderby=published&callback=handleBloggerPosts`;

            const script = document.createElement('script');
            script.src = feedUrl;
            script.onerror = function() {
                carouselWrapper.innerHTML = '<p class="error-message">Erro ao carregar posts. Verifique a URL do blog ou sua conexão.</p>';
                console.error('Erro ao carregar o script do feed do Blogger.');
                updateArrowStates();
            };
            document.head.appendChild(script);
        }

        // Funções de navegação do carrossel
        function scrollCarousel(direction) {
            const carouselWrapper = document.getElementById('movieCarousel');
            if (!carouselWrapper || scrollAmount === 0) {
                console.warn('Scroll not possible: carouselWrapper not found or scrollAmount is 0.'); // Para depuração
                return;
            }

            if (direction === 'left') {
                carouselWrapper.scrollLeft -= scrollAmount;
            } else {
                carouselWrapper.scrollLeft += scrollAmount;
            }
        }

        document.addEventListener('DOMContentLoaded', () => {
            // Primeiro, verifique e oculte o widget se estiver em uma página de postagem
            hideWidgetOnPostPage();

            // Se o widget não estiver oculto, inicialize o carrossel
            const widgetElement = document.getElementById('custom-streaming-widget');
            if (widgetElement && widgetElement.style.display !== 'none') {
                const prevArrow = document.getElementById('prevArrow');
                const nextArrow = document.getElementById('nextArrow');
                const carouselWrapper = document.getElementById('movieCarousel');

                if (prevArrow) {
                    prevArrow.addEventListener('click', () => scrollCarousel('left'));
                }
                if (nextArrow) {
                    nextArrow.addEventListener('click', () => scrollCarousel('right'));
                }

                if (carouselWrapper) {
                    carouselWrapper.addEventListener('scroll', updateArrowStates);
                }

                loadBloggerFeed();
            }
        });
    //

b:if.script:
//
        (function(){
          /* === Paginação numérica com acesso a posts antigos (server-side) ===
             Mostra 6 posts por página. Usa /feeds/posts/summary para descobrir
             o total e a data-limite (updated-max) de cada página, gerando
             links reais no formato /search?updated-max=... para navegar
             entre páginas antigas mantendo a mesma quantidade de posts. */
          var PER_PAGE = 6;
          function currentPageFromURL(){
            try{
              var p = new URLSearchParams(location.search).get('cn-page');
              var n = parseInt(p||'1',10);
              return isNaN(n) || n < 1 ? 1 : n;
            }catch(e){ return 1; }
          }
          function updatedMaxFromURL(){
            try{ return new URLSearchParams(location.search).get('updated-max'); }
            catch(e){ return null; }
          }
          function buildPageURL(page, cursor){
            // page 1 = home; demais páginas usam cursor updated-max
            var origin = location.origin;
            if(page <= 1) return origin + '/';
            var q = 'updated-max=' + encodeURIComponent(cursor)
                  + '&max-results=' + PER_PAGE
                  + '&cn-page=' + page;
            return origin + '/search?' + q;
          }
          function feedURL(startIndex){
            return '/feeds/posts/summary?alt=json&start-index=' + startIndex
                 + '&max-results=1&orderby=published';
          }
          function fetchJSON(url){
            return fetch(url, {credentials:'same-origin'}).then(function(r){
              if(!r.ok) throw new Error('feed'); return r.json();
            });
          }
          function renderPager(total, currentPage, cursorsByPage){
            var container = document.querySelector('#main-wrapper .blog-posts.hfeed');
            if(!container) return;
            var oldPager = document.getElementById('cn-numeric-pager');
            if(oldPager) oldPager.remove();
            var totalPages = Math.max(1, Math.ceil(total / PER_PAGE));
            if(totalPages <= 1) return;
            var pager = document.createElement('div');
            pager.id = 'cn-numeric-pager';
            var caption = document.createElement('div');
            caption.className = 'cn-pager-caption';
            caption.textContent = 'Página ' + currentPage + ' de ' + totalPages + ' — acesse posts antigos';
            var nav = document.createElement('div');
            nav.className = 'cn-pager-nav';
            function mkBtn(label, page, opts){
              opts = opts || {};
              var el;
              if(opts.disabled){
                el = document.createElement('button');
                el.disabled = true;
              } else {
                el = document.createElement('a');
                el.href = buildPageURL(page, cursorsByPage[page]);
              }
              el.textContent = label;
              if(opts.active) el.classList.add('active');
              return el;
            }
            function dots(){
              var s = document.createElement('span');
              s.className = 'cn-dots'; s.textContent = '…';
              return s;
            }
            // Prev
            if(currentPage > 1) nav.appendChild(mkBtn('‹', currentPage-1));
            else nav.appendChild(mkBtn('‹', 1, {disabled:true}));
            // Numbers window
            var pages = [];
            if(totalPages <= 7){ for(var i=1;i<=totalPages;i++) pages.push(i); }
            else{
              pages.push(1);
              if(currentPage > 3) pages.push('...');
              for(var j=Math.max(2,currentPage-1); j<=Math.min(totalPages-1,currentPage+1); j++) pages.push(j);
              if(currentPage < totalPages-2) pages.push('...');
              pages.push(totalPages);
            }
            pages.forEach(function(p){
              if(p === '...') nav.appendChild(dots());
              else nav.appendChild(mkBtn(String(p), p, {active: p === currentPage}));
            });
            if(currentPage < totalPages) nav.appendChild(mkBtn('›', currentPage+1));
            else nav.appendChild(mkBtn('›', totalPages, {disabled:true}));

            pager.appendChild(caption);
            pager.appendChild(nav);
            container.parentNode.insertBefore(pager, container.nextSibling);
          }
          function initPager(){
            var container = document.querySelector('#main-wrapper .blog-posts.hfeed');
            if(!container || container.dataset.cnPaged === '1') return;
            container.dataset.cnPaged = '1';
            // 1) total de posts do blog
            fetchJSON('/feeds/posts/summary?alt=json&max-results=0').then(function(d){
              var total = parseInt((d.feed['openSearch$totalResults']||{}).$t || '0', 10);
              if(!total) return;
              var totalPages = Math.ceil(total / PER_PAGE);
              var currentPage = currentPageFromURL();
              // 2) coleta cursor (published) do 1º post de cada página
              //    limita a busca a até 12 páginas ao redor da atual p/ leveza
              var wanted = [];
              wanted.push(1);
              var from = Math.max(2, currentPage - 3);
              var to   = Math.min(totalPages, currentPage + 4);
              for(var i=from; i<=to; i++) wanted.push(i);
              wanted.push(totalPages);
              wanted = wanted.filter(function(v,i,a){return a.indexOf(v)===i && v>=1 && v<=totalPages;});
              var cursors = { 1: null };
              var jobs = wanted.filter(function(p){return p>1;}).map(function(p){
                var idx = (p - 1) * PER_PAGE + 1;
                return fetchJSON(feedURL(idx)).then(function(fd){
                  var e = fd.feed && fd.feed.entry && fd.feed.entry[0];
                  if(e && e.published && e.published.$t){
                    cursors[p] = e.published.$t;
                  }
                }).catch(function(){});
              });
              Promise.all(jobs).then(function(){
                renderPager(total, currentPage, cursors);
              });
            }).catch(function(){});
          }
          if(document.readyState==='loading') document.addEventListener('DOMContentLoaded', initPager);
          else initPager();
          setTimeout(initPager, 800);
          setTimeout(initPager, 2000);
        })();
      //

//
(function(){
  var LIMITE = 6;
  function iso(el){
    var t = el.querySelector('time[datetime], .published[datetime], abbr.published[title]');
    if(!t) return null;
    return t.getAttribute('datetime') || t.getAttribute('title');
  }
  function aplicar(){
    var wrap = document.querySelector('.blog-posts');
    if(!wrap) return;
    var itens = Array.prototype.filter.call(wrap.children, function(el){
      return /post-outer|post-item|hentry|index-post/.test(el.className||'');
    });
    if(itens.length < 2) itens = Array.prototype.slice.call(wrap.querySelectorAll(':scope > div'));
    if(itens.length <= LIMITE) return;
    var corte = itens[LIMITE - 1];
    for(var i = LIMITE; i < itens.length; i++){ itens[i].style.display = 'none'; }
    // Refaz o link de "Postagens antigas" a partir da data da 6a postagem,
    // para que nenhuma postagem seja pulada na paginacao.
    var data = iso(corte);
    if(!data) return;
    var url = '/search?updated-max=' + encodeURIComponent(data) + '&max-results=' + LIMITE + '&start=' + LIMITE + '&by-date=false';
    var links = document.querySelectorAll('.blog-pager-older-link, #blog-pager-older-link a, a.pre-btn, a.js-load');
    for(var j = 0; j < links.length; j++){ links[j].setAttribute('href', url); }
  }
  if(document.readyState !== 'loading') aplicar();
  else document.addEventListener('DOMContentLoaded', aplicar);
})();
