b:if.script:
//
(function(){
  var PANEL='#drk1.gsrecent1', ROTATE=4000, PAGE_STEP=3, FALLBACK='https://placehold.co/1600x900/060d17/ffffff?text=Callango+Nerd';
  function txt(el){ return el ? (el.textContent||'').trim() : ''; }
  function bgOf(item){
    var b=item.querySelector('.box-image');
    if(b){ var m=(b.getAttribute('style')||'').match(/url\(['"]?(.*?)['"]?\)/); if(m&&m[1]) return m[1]; }
    var img=item.querySelector('img'); if(img&&img.src) return img.src;
    return FALLBACK;
  }
  function collect(panel){
    var out=[], seen={};
    panel.querySelectorAll('.carousel-item').forEach(function(it){
      var a=it.querySelector('.recent-title a'); if(!a) return;
      var href=a.getAttribute('href')||'#'; if(seen[href]) return; seen[href]=1;
      var lab=it.querySelector('.carousel-meta a');
      out.push({ title:txt(a), href:href, img:bgOf(it),
        label:txt(lab)||'CURIOSIDADES', labelHref:lab?(lab.getAttribute('href')||'#'):'#',
        date:txt(it.querySelector('.recent-date')) });
    });
    return out;
  }
  function esc(s){ return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;'); }
  function build(panel, posts, titleText){
    var html=''+
      '<div class="fn__w_posts"><div class="interactive_wrapper">'+
        '<ul class="bg_list"></ul>'+
        '<div class="container">'+
          '<div class="drk1_vtitle">'+esc(titleText)+'</div>'+
          '<div class="drk1_sub"><span class="drk1_pulse"></span>Últimas Notícias</div>'+
          '<ul class="interactive_items"></ul>'+
        '</div>'+
        '<div class="drk1_progress"><span></span></div>'+
      '</div></div>';
    var wc=panel.querySelector('.widget-content');
    wc.innerHTML=html;
    var h2=panel.querySelector(':scope > h2, .widget > h2'); if(h2) h2.style.display='none';
    var wt=panel.querySelector('.widget-title'); if(wt) wt.style.display='none';

    var bgList=wc.querySelector('.bg_list'), items=wc.querySelector('.interactive_items'), bar=wc.querySelector('.drk1_progress span');
    var page=0, active=0, timer=null, elapsed=0, hovering=false;

    function render(){
      var slice=[];
      for(var i=0;i<PAGE_STEP;i++){ slice.push(posts[(page*PAGE_STEP+i)%posts.length]); }
      bgList.innerHTML=slice.map(function(p,i){
        return '<li data-i="'+i+'" style="background-image:url(\''+p.img+'\')" class="'+(i===active?'active':'')+'"></li>';
      }).join('');
      items.innerHTML=slice.map(function(p,i){
        return '<li class="interactive_item'+(i===active?' active':'')+'" data-i="'+i+'">'+
          '<div class="interactive__item" style="--cn-thumb:url(\''+p.img+'\')"><div class="title_holder">'+
            '<div class="fn__meta"><p><a class="fn_last_category" href="'+esc(p.labelHref)+'">'+esc(p.label)+'</a>'+
            '<span class="meta_sep"></span><span class="meta_item meta_date">'+esc(p.date)+'</span></p></div>'+
            '<h3 class="post_title"><a href="'+esc(p.href)+'">'+esc(p.title)+'</a></h3>'+
          '</div></div></li>';
      }).join('');
      items.querySelectorAll('.interactive_item').forEach(function(li){
        li.addEventListener('mouseenter', function(){ hovering=true; elapsed=0; setActive(+li.getAttribute('data-i')); });
        li.addEventListener('mouseleave', function(){ hovering=false; });
      });
    }
    function setActive(i){
      active=i;
      bgList.querySelectorAll('li').forEach(function(l){ l.classList.toggle('active', +l.getAttribute('data-i')===i); });
      items.querySelectorAll('.interactive_item').forEach(function(l){ l.classList.toggle('active', +l.getAttribute('data-i')===i); });
    }
    function tick(){
      if(hovering){ elapsed=0; bar.style.width='0%'; return; }
      elapsed+=200; bar.style.width=Math.min(100,(elapsed/ROTATE)*100)+'%';
      if(elapsed>=ROTATE){
        elapsed=0; bar.style.width='0%';
        if(active+1 < PAGE_STEP){ setActive(active+1); }
        else if(posts.length > PAGE_STEP){ page=(page+1)%Math.ceil(posts.length/PAGE_STEP); active=0; render(); }
        else { setActive(0); }
      }
    }
    render();
    clearInterval(timer); timer=setInterval(tick,200);
  }
  function boot(){
    var panel=document.querySelector(PANEL); if(!panel) return;
    var titleEl=panel.querySelector('h2');
    var titleText=titleEl?(titleEl.textContent||'Curiosidades').trim():'Curiosidades';
    var tries=0;
    var iv=setInterval(function(){
      tries++;
      var posts=collect(panel);
      if(posts.length){
        clearInterval(iv);
        try{ if(window.jQuery){ var oc=window.jQuery(panel).find('.main-carousel');
          if(oc.length && oc.data('owl.carousel')){ oc.trigger('destroy.owl.carousel'); } } }catch(e){}
        build(panel, posts, titleText);
      }
      if(tries>60) clearInterval(iv);
    },250);
  }
  if(document.readyState==='loading') document.addEventListener('DOMContentLoaded', boot); else boot();
})();
//

div.script:
//
(function () {
  var API_KEY = '0344712bb861098caefcc9a8d67beb09';
  var BASE = 'https://api.themoviedb.org/3';
  var IMG = 'https://image.tmdb.org/t/p/w500';
  var BACKDROP = 'https://image.tmdb.org/t/p/w1280';
  var YT = 'https://www.youtube.com/embed/';

  var stage = document.getElementById('estStage');
  var overlay = document.getElementById('estOverlay');
  var modalIn = document.getElementById('estModalIn');
  var modal = document.getElementById('estModal');
  var closeBtn = document.getElementById('estClose');
  var loading = document.getElementById('estLoading');
  var tabs = document.querySelectorAll('.est-tab');

  function esc(s) {
    return String(s == null ? '' : s).replace(/[&<>"']/g, function (c) {
      return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c];
    });
  }
  function year(m) {
    var d = m.release_date || m.first_air_date || '';
    return d ? d.substring(0, 4) : '';
  }
  function typeOf(m) {
    return m.media_type || (m.title ? 'movie' : 'tv');
  }
  function label(m) {
    return typeOf(m) === 'tv' ? 'Série' : 'Filme';
  }

  function endpointFor(filter) {
    if (filter === 'cinema') return '/movie/now_playing?api_key=' + API_KEY + '&language=pt-BR&region=BR';
    if (filter === 'tv') return '/tv/on_the_air?api_key=' + API_KEY + '&language=pt-BR&region=BR';
    return '/trending/all/week?api_key=' + API_KEY + '&language=pt-BR';
  }

  function render(results) {
    // Layout carrossel: fileira horizontal de pôsteres
    if(!results || !results.length){
      stage.innerHTML = '<div class="est-msg">Sem estreias no momento.</div>';
      return;
    }
    stage.innerHTML = results.map(function (m, i) {
      var poster = m.poster_path ? IMG + m.poster_path
                 : (m.backdrop_path ? BACKDROP + m.backdrop_path : '');
      var t = esc(m.title || m.name);
      return '<div class="est-slide" data-id="' + m.id + '" data-type="' + typeOf(m) + '">' +
               '<div class="est-poster">' +
                 '<img src="' + poster + '" alt="' + t + '" loading="' + (i < 4 ? 'eager' : 'lazy') + '">' +
                 '<span class="est-rank" data-n="' + (i + 1) + '"><i class="est-rank-num">' + String(i + 1).padStart(2,"0") + '</i></span>' +
                 '<span class="est-tag">' + label(m) + '</span>' +
                 '<span class="est-score"><span class="est-star">&#9733;</span>' + (m.vote_average || 0).toFixed(1) + '</span>' +
               '</div>' +
               '<div class="est-info">' +
                 '<h4>' + t + '</h4>' +
                 '<div class="est-meta"><span>' + esc(year(m)) + '</span><span class="dot">&middot;</span><span>Ver detalhes</span></div>' +
               '</div>' +

             '</div>';
    }).join('');
    stage.querySelectorAll('[data-id]').forEach(function (el) {
      el.addEventListener('click', function () {
        openDetails(this.getAttribute('data-id'), this.getAttribute('data-type'));
      });
    });
    updateNav();
  }

  var prevBtn = document.getElementById('estPrev');
  var nextBtn = document.getElementById('estNext');
  function step(){
    var first = stage.querySelector('.est-slide');
    var w = first ? first.getBoundingClientRect().width + 18 : 240;
    return Math.max(w, Math.floor(stage.clientWidth * 0.8 / w) * w);
  }
  function updateNav(){
    if(!prevBtn || !nextBtn) return;
    var max = stage.scrollWidth - stage.clientWidth - 2;
    prevBtn.disabled = stage.scrollLeft <= 2;
    nextBtn.disabled = stage.scrollLeft >= max;
  }
  if (prevBtn) prevBtn.addEventListener('click', function(){ stage.scrollLeft -= step(); });
  if (nextBtn) nextBtn.addEventListener('click', function(){ stage.scrollLeft += step(); });
  if (stage) stage.addEventListener('scroll', updateNav);
  window.addEventListener('resize', updateNav);

  function load(filter) {
    if (!stage) return;
    stage.innerHTML = '<div class="est-msg">Carregando conteúdo...</div>';
    fetch(BASE + endpointFor(filter))
      .then(function (r) { if (!r.ok) throw new Error('api'); return r.json(); })
      .then(function (data) {
        var results = (data.results || []).filter(function (m) { return m.poster_path || m.backdrop_path; }).slice(0, 20);
        if (!results.length) {
          stage.innerHTML = '<div class="est-msg is-error">Nenhum resultado.</div>';
          return;
        }
        render(results);
      })
      .catch(function () {
        stage.innerHTML = '<div class="est-msg is-error">Erro ao carregar dados.</div>';
      });
  }

  function openDetails(id, type) {
    if (!overlay) return;
    overlay.style.display = 'flex';
    document.body.style.overflow = 'hidden';
    modalIn.innerHTML = '';
    loading.style.display = 'block';

    Promise.all([
      fetch(BASE + '/' + type + '/' + id + '?api_key=' + API_KEY + '&language=pt-BR').then(function (r) { return r.json(); }),
      fetch(BASE + '/' + type + '/' + id + '/videos?api_key=' + API_KEY + '&language=pt-BR').then(function (r) { return r.json(); })
    ]).then(function (res) {
      var d = res[0], v = res[1];
      loading.style.display = 'none';
      var trailer = (v.results || []).filter(function (x) { return x.site === 'YouTube' && x.type === 'Trailer'; })[0] || (v.results || [])[0];
      if (d.backdrop_path) {
        modal.style.backgroundImage = 'linear-gradient(rgba(0,0,0,.85),rgba(0,0,0,.85)),url(' + BACKDROP + d.backdrop_path + ')';
        modal.style.backgroundSize = 'cover';
      }
      modalIn.innerHTML =
        '<div class="est-col-poster"><img src="' + (d.poster_path ? IMG + d.poster_path : '') + '" alt="' + esc(d.title || d.name) + '"></div>' +
        '<div class="est-col-info"><h3>' + esc(d.title || d.name) + '</h3><p>' + esc(d.overview || 'Sinopse não disponível.') + '</p></div>' +
        '<div class="est-col-trailer"><div class="est-embed">' +
          (trailer ? '<iframe src="' + YT + trailer.key + '?autoplay=1" allowfullscreen></iframe>' : 'Trailer não disponível') +
        '</div></div>';
    }).catch(function () {
      loading.style.display = 'none';
      modalIn.innerHTML = '<div class="est-msg is-error">Erro ao carregar detalhes.</div>';
    });
  }

  if (closeBtn) {
    closeBtn.onclick = function () {
      overlay.style.display = 'none';
      document.body.style.overflow = 'auto';
      modalIn.innerHTML = '';
      modal.style.backgroundImage = '';
    };
  }
  if (overlay) {
    overlay.addEventListener('click', function (e) {
      if (e.target === overlay) closeBtn.onclick();
    });
  }

  tabs.forEach(function (btn) {
    btn.addEventListener('click', function () {
      tabs.forEach(function (b) { b.classList.remove('is-active'); });
      this.classList.add('is-active');
      load(this.getAttribute('data-filter'));
    });
  });

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', function () { load('streaming'); });
  } else {
    load('streaming');
  }
})();
//

//
    // CHAVE DE API DO TMDB
    var tmdbApiKey = '0344712bb861098caefcc9a8d67beb09';

    // URLs da API e das imagens do TMDB
    var tmdbApiBaseUrl = 'https://api.themoviedb.org/3';
    var tmdbBackdropBaseUrl = 'https://image.tmdb.org/t/p/w1280';
    var tmdbStillBaseUrl = 'https://image.tmdb.org/t/p/w300';
    var tmdbPosterBaseUrl = 'https://image.tmdb.org/t/p/w500';

    // Elementos DOM
    var mainPlayerContainer = document.getElementById('mainPlayerContainer');
    var sideListContainer = document.getElementById('sideListContainer');
    var trailerScroller = document.getElementById('trailerScroller');
    var popupOverlay = document.getElementById('popupOverlay');
    var videoWrapper = document.getElementById('videoWrapper');
    var closeButton = document.getElementById('closeButton');
    var selector = document.querySelector('.selector');
    var gstrailerWidget = document.querySelector('.gstrailer');

    // Mapeamento dos grupos de trailers
    var apiEndpoints = {
        'popular': tmdbApiBaseUrl + '/trending/all/week?api_key=' + tmdbApiKey + '&language=pt-BR',
        'streaming': tmdbApiBaseUrl + '/trending/all/week?api_key=' + tmdbApiKey + '&language=pt-BR',
        'on-the-air': tmdbApiBaseUrl + '/tv/on_the_air?api_key=' + tmdbApiKey + '&language=pt-BR',
        'for-rent': tmdbApiBaseUrl + '/discover/movie?api_key=' + tmdbApiKey + '&language=pt-BR&with_watch_monetization_types=rent',
        'in-theatres': tmdbApiBaseUrl + '/movie/now_playing?api_key=' + tmdbApiKey + '&language=pt-BR',
    };

    // ===== fetch-based loader (rapido e sem callbacks pendurados) =====
    function tmdbFetch(url){
      return fetch(url, {cache:'default'}).then(function(r){ if(!r.ok) throw new Error(r.status); return r.json(); });
    }
    function pickTrailer(videoData){
      var vids = (videoData && videoData.results) || [];
      var yt = vids.filter(function(v){ return v.site==='YouTube' && (v.type==='Trailer' || v.type==='Teaser'); });
      var pt = yt.filter(function(v){
        var n = (v.name||'').toLowerCase();
        return v.iso_639_1==='pt' || n.indexOf('dublado')>-1 || n.indexOf('legendado')>-1 || n.indexOf('br')>-1;
      });
      return (pt[0] || yt[0] || null);
    }
    window.processTmdbData = function(data){
        var mediaList = (data && data.results) || [];
        if (!mediaList.length){
          if(mainPlayerContainer) mainPlayerContainer.innerHTML = '<div class="trailer-error">Nenhum trailer encontrado.</div>';
          return;
        }
        var mediaToFetch = mediaList.slice(0, 15);
        // Timeout de seguranca: se nada resolver em 8s, renderiza o que temos
        var settled = false;
        var partial = [];
        function finish(list){
          if(settled) return; settled = true;
          list.sort(function(a,b){ return new Date(b.release_date||0) - new Date(a.release_date||0); });
          if(!list.length){
            if(mainPlayerContainer) mainPlayerContainer.innerHTML = '<div class="trailer-error">Nenhum trailer disponivel no momento.</div>';
            return;
          }
          renderMedia(list);
        }
        var promises = mediaToFetch.map(function(media){
          var mediaType = media.media_type || (media.title ? 'movie' : 'tv');
          var url = tmdbApiBaseUrl + '/' + mediaType + '/' + media.id + '/videos?api_key=' + tmdbApiKey + '&language=pt-BR';
          return tmdbFetch(url).then(function(vd){
            var t = pickTrailer(vd);
            if(!t) return null;
            return {
              id: media.id,
              title: media.title || media.name,
              backdrop_path: media.backdrop_path,
              poster_path: media.poster_path,
              youtubeKey: t.key,
              release_date: media.release_date || media.first_air_date
            };
          }).catch(function(){ return null; });
        });
        setTimeout(function(){ if(!settled) finish(partial.slice()); }, 8000);
        Promise.all(promises).then(function(list){
          partial = list.filter(Boolean);
          finish(partial);
        });
    };

    function displayTrailers(group){
        group = group || 'popular';
        if(mainPlayerContainer) mainPlayerContainer.innerHTML = '<div class="trailer-loading">🎥 Carregando...</div>';
        tmdbFetch(apiEndpoints[group]).then(window.processTmdbData).catch(function(){
          if(mainPlayerContainer) mainPlayerContainer.innerHTML = '<div class="trailer-error">Erro ao carregar trailers. Tente novamente.</div>';
        });
    }

    function renderMedia(mediaList) {
        if(!mainPlayerContainer) return;
        mainPlayerContainer.innerHTML = '';
        if(sideListContainer) sideListContainer.innerHTML = '';
        if(trailerScroller) trailerScroller.innerHTML = '';

        if (mediaList.length === 0) {
            mainPlayerContainer.innerHTML = '<div class="trailer-error">Nenhum trailer encontrado.</div>';
            return;
        }

        var mainTrailer = mediaList[0];
        mainPlayerContainer.appendChild(createMainPlayerCard(mainTrailer));

        if (gstrailerWidget && mainTrailer.backdrop_path) {
            gstrailerWidget.style.backgroundImage = 'url(' + tmdbBackdropBaseUrl + mainTrailer.backdrop_path + ')';
        }

        mediaList.slice(1, 6).forEach(media => sideListContainer && sideListContainer.appendChild(createSideListCard(media)));
        mediaList.slice(6).forEach(media => trailerScroller && trailerScroller.appendChild(createHorizontalScrollerCard(media)));

        setupCarouselNavigation();
    }

    function createMainPlayerCard(media) {
        var div = document.createElement('div');
        div.className = 'main-player-card';
        var imageUrl = media.backdrop_path ? tmdbBackdropBaseUrl + media.backdrop_path : 'https://via.placeholder.com/1280x720';
        div.innerHTML = `<img src="${imageUrl}" alt="${media.title}"><div class="player-overlay"><h4>${media.title}</h4><div class="play-button"><svg viewBox="0 0 24 24"><path d="M8 5v14l11-7z"/></svg></div></div>`;
        div.onclick = () => openVideo(media.youtubeKey);
        return div;
    }

    function createSideListCard(media) {
        var div = document.createElement('div');
        div.className = 'trailer-card';
        var imageUrl = media.poster_path ? tmdbStillBaseUrl + media.poster_path : 'https://via.placeholder.com/100x60';
        div.innerHTML = `<img src="${imageUrl}"> <div class="info"><h5>${media.title}</h5></div>`;
        div.onclick = () => openVideo(media.youtubeKey);
        return div;
    }

    function createHorizontalScrollerCard(media) {
        var div = document.createElement('div');
        div.className = 'trailer-card-scroller';
        var imageUrl = media.backdrop_path ? tmdbBackdropBaseUrl + media.backdrop_path : 'https://via.placeholder.com/250x140';
        div.innerHTML = `<div class="image-container"><img src="${imageUrl}"><div class="play-button"><svg viewBox="0 0 24 24"><path d="M8 5v14l11-7z"/></svg></div></div><div class="content"><h4>${media.title}</h4></div>`;
        div.onclick = () => openVideo(media.youtubeKey);
        return div;
    }

    function openVideo(youtubeKey) {
        if (!youtubeKey) return;
        videoWrapper.innerHTML = `<iframe src="https://www.youtube.com/embed/${youtubeKey}?autoplay=1&rel=0" allow="autoplay; encrypted-media" allowfullscreen></iframe>`;
        popupOverlay.style.display = 'flex';
        document.body.style.overflow = 'hidden';
    }

    function closeVideo() {
        popupOverlay.style.display = 'none';
        videoWrapper.innerHTML = '';
        document.body.style.overflow = '';
    }

    if(closeButton) closeButton.onclick = closeVideo;
    if(popupOverlay) popupOverlay.onclick = (e) => e.target === popupOverlay && closeVideo();

    if(selector) {
selector.addEventListener('click', function(e) {
    e.preventDefault();
    var anchor = e.target.closest('.anchor');
    if (anchor) {
        var group = anchor.getAttribute('data-group');

        // Remove seleção de todos e adiciona no clicado
        document.querySelectorAll('.selector .anchor').forEach(el => el.classList.remove('selected'));
        anchor.classList.add('selected');

        // Move a barrinha vermelha
        var background = document.getElementById('selectorBg');
        background.style.left = anchor.offsetLeft + 'px';
        background.style.width = anchor.offsetWidth + 'px';

        displayTrailers(group);
    }
});
    }

    function setupCarouselNavigation() {
        document.querySelectorAll('.carrousel-nav-button').forEach(button => {
            button.onclick = function() {
                var target = document.getElementById(this.getAttribute('data-target'));
                if(target) target.scrollBy({ left: this.classList.contains('prev') ? -300 : 300, behavior: 'smooth' });
            };
        });
    }

    document.addEventListener('DOMContentLoaded', function() {
        displayTrailers('popular');
        // Seletor inicial
        var active = document.querySelector('.selector .anchor.selected');
        var bg = document.querySelector('.selector .background');
        if(active && bg) { bg.style.left = active.offsetLeft + 'px'; bg.style.width = active.offsetWidth + 'px'; }
    });
//

body.script:
