// Função para atualizar o conteúdo de data-text para efeitos de CSS
function updateDataText() {
    var selectors = [
        '.latestposts-title h3', '.recentbtm h3', '.related-post h4',
        '.widget-title h3', 'ol', '.comments h3', '#ficha ol'
    ];

    selectors.forEach(function(selector) {
        var elements = document.querySelectorAll(selector);
        elements.forEach(function(element) {
            var text = element.textContent.trim();
            element.setAttribute('data-text', text);
        });
    });
}
document.addEventListener('DOMContentLoaded', updateDataText);

//
(function(){
  var TMDB_KEY = '0344712bb861098caefcc9a8d67beb09';
  var TMDB_LANG = 'pt-BR';

  /* ---------- utils ---------- */
  function h(tag, attrs, children){
    var el = document.createElement(tag);
    if(attrs){
      for(var k in attrs){
        if(k === 'class') el.className = attrs[k];
        else if(k === 'html') el.innerHTML = attrs[k];
        else if(k === 'on') { for(var e in attrs.on) el.addEventListener(e, attrs.on[e]); }
        else if(attrs[k] != null) el.setAttribute(k, attrs[k]);
      }
    }
    (children||[]).forEach(function(c){ if(c) el.appendChild(typeof c === 'string' ? document.createTextNode(c) : c); });
    return el;
  }
  function tmdb(path, params){
    var u = new URL('https://api.themoviedb.org/3' + path);
    u.searchParams.set('api_key', TMDB_KEY);
    u.searchParams.set('language', TMDB_LANG);
    if(params) for(var k in params) u.searchParams.set(k, params[k]);
    return fetch(u.toString()).then(function(r){ if(!r.ok) throw new Error('TMDB '+r.status); return r.json(); });
  }
  function fmtDate(iso){
    if(!iso) return '';
    try{ return new Date(iso).toLocaleDateString('pt-BR',{day:'2-digit',month:'long',year:'numeric'});}catch(e){return iso;}
  }

  /* ---------- 1) Font-size regulator ---------- */
  function initFontRegulator(){
    // Movido para dentro do popup Trend News — não injeta mais no post-body.
    return;
    var body = document.querySelector('.post-body');
    if(!body || document.getElementById('cn-font-regulator')) return;
    var stored = parseInt(localStorage.getItem('cn-font-size')||'0',10);
    var initial = stored >= 14 && stored <= 22 ? stored : 16;
    var reg = h('div',{id:'cn-font-regulator', class:'cn-font-regulator'});
    reg.innerHTML =
      '<span class="label">Regule o tamanho do texto</span>'+
      '<span class="value" id="cn-font-min">14px</span>'+
      '<input type="range" min="14" max="22" step="1" value="'+initial+'" aria-label="Tamanho do texto">'+
      '<span class="value" id="cn-font-current">'+initial+'px</span>'+
      '<span class="value">22px</span>';
    body.parentNode.insertBefore(reg, body);
    body.style.fontSize = initial + 'px';
    body.style.lineHeight = '1.7';
    var range = reg.querySelector('input[type="range"]');
    var out = reg.querySelector('#cn-font-current');
    range.addEventListener('input', function(){
      var v = parseInt(range.value,10);
      body.style.fontSize = v + 'px';
      out.textContent = v + 'px';
      try{ localStorage.setItem('cn-font-size', String(v)); }catch(e){}
    });
  }

  /* ---------- 2) Author card (Márcio Oliveira) ---------- */
  function initAuthorCard(){
    // Movido para dentro do popup Trend News — não injeta mais no post-body.
    return;
    var body = document.querySelector('.post-body');
    if(!body || document.querySelector('.cn-author-card')) return;
    // Only render on single post view — check for typical Blogger post class
    if(!document.body.classList.contains('is-post') && !document.querySelector('.post.hentry')) return;

    var card = h('aside',{class:'cn-author-card', 'aria-label':'Sobre o autor'});
    card.innerHTML =
      '<div class="cn-author-inner">'+
        '<div class="cn-author-avatar">'+
          '<img src="https://blogger.googleusercontent.com/img/b/R29vZ2xl/AVvXsEjM/marcio.jpg" '+
            'onerror="this.onerror=null;this.src=\'data:image/svg+xml;utf8,'+
            encodeURIComponent('<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 96 96"><rect width="96" height="96" fill="#1a2231"/><text x="50%" y="55%" fill="#e50914" font-family="Arial Black" font-size="32" text-anchor="middle">MO</text></svg>')+
            '\'" alt="Márcio Oliveira" width="96" height="96" loading="lazy">'+
        '</div>'+
        '<div class="cn-author-info">'+
          '<p class="cn-author-label">Assinado por</p>'+
          '<h3 class="cn-author-name">MÁRCIO OLIVEIRA</h3>'+
          '<p class="cn-author-bio">Cearense com gosto de gás! CEO do Callango Nerd, cinéfilo, crítico, redator, desenhista, designer gráfico, professor de Cearensês e Mestre Jedi na arte de fazer piada ruim.</p>'+
          '<div class="cn-author-social">'+
            '<a href="https://www.threads.net/@callangonerd" target="_blank" rel="noopener" aria-label="Threads" title="Threads"><i class="fa-brands fa-threads"></i></a>'+
            '<a href="https://www.facebook.com/profile.php?id=100026292841096" target="_blank" rel="noopener" aria-label="Facebook" title="Facebook"><i class="fa-brands fa-facebook-f"></i></a>'+
            '<a href="https://www.instagram.com/marciooliveiracn" target="_blank" rel="noopener" aria-label="Instagram" title="Instagram"><i class="fa-brands fa-instagram"></i></a>'+
          '</div>'+
        '</div>'+
      '</div>';
    body.parentNode.insertBefore(card, body.nextSibling);
  }

  /* ---------- 3) Actor detection + TMDB modal ---------- */
  // Auto-detect: sequences of 2+ capitalized words inside <strong>/<b>/<em>
  // OR any element with data-cn-actor="Name". Uses a whitelist of known actor
  // patterns to avoid false positives (skips common movie titles).
  var STOP_WORDS = ['A','O','As','Os','Um','Uma','De','Da','Do','Das','Dos','E','Em','Ilíada','Odisseia','Nolan','Homero','Callango','Nerd','Guerra','Troia','Aquiles','Heitor','Ítaca','Penélope','Odisseu','Calipso','Circe','Poseidon','Telêmaco'];
  function looksLikePersonName(text){
    text = (text||'').trim();
    if(text.length < 5 || text.length > 60) return false;
    var parts = text.split(/\s+/);
    if(parts.length < 2 || parts.length > 4) return false;
    for(var i=0;i<parts.length;i++){
      var w = parts[i];
      if(!/^[A-ZÁÉÍÓÚÂÊÎÔÛÃÕÇ][a-záéíóúâêîôûãõçA-Z'’.-]*$/.test(w)) return false;
      if(STOP_WORDS.indexOf(w) !== -1 && i===0) return false;
    }
    return true;
  }
  function markActors(){
    var container = document.querySelector('.post-body');
    if(!container) return;
    // explicit data-cn-actor spans
    container.querySelectorAll('[data-cn-actor]').forEach(function(el){
      if(!el.classList.contains('cn-actor')) el.classList.add('cn-actor');
    });
    // Wrap <strong>/<b> that look like person names
    container.querySelectorAll('strong, b').forEach(function(el){
      if(el.closest('.cn-actor')) return;
      if(el.querySelector('a,img')) return;
      var txt = el.textContent;
      if(!looksLikePersonName(txt)) return;
      el.classList.add('cn-actor');
      el.setAttribute('role','button');
      el.setAttribute('tabindex','0');
      el.setAttribute('data-cn-actor', txt.trim());
    });
    // Delegate click
    container.addEventListener('click', function(ev){
      var t = ev.target.closest('.cn-actor,[data-cn-actor]');
      if(!t || !container.contains(t)) return;
      ev.preventDefault();
      var name = t.getAttribute('data-cn-actor') || t.textContent.trim();
      openActorModal(name);
    });
    container.addEventListener('keydown', function(ev){
      if(ev.key !== 'Enter' && ev.key !== ' ') return;
      var t = ev.target.closest('.cn-actor,[data-cn-actor]');
      if(!t) return;
      ev.preventDefault();
      openActorModal(t.getAttribute('data-cn-actor') || t.textContent.trim());
    });
  }

  var overlay = null;
  function ensureOverlay(){
    if(overlay) return overlay;
    overlay = h('div',{class:'cn-tmdb-overlay','aria-modal':'true',role:'dialog'});
    overlay.addEventListener('click', function(ev){
      if(ev.target === overlay) closeModal();
    });
    document.addEventListener('keydown', function(ev){
      if(ev.key === 'Escape' && overlay.classList.contains('open')) closeModal();
    });
    document.body.appendChild(overlay);
    return overlay;
  }
  function closeModal(){
    if(!overlay) return;
    overlay.classList.remove('open');
    overlay.innerHTML = '';
    document.body.classList.remove('cn-modal-open');
  }
  function renderLoading(){
    overlay.innerHTML =
      '<div class="cn-tmdb-modal">'+
        '<button class="cn-tmdb-close" aria-label="Fechar">×</button>'+
        '<div class="cn-tmdb-loading"><div class="spinner"></div>Buscando perfil no TMDB…</div>'+
      '</div>';
    overlay.querySelector('.cn-tmdb-close').addEventListener('click', closeModal);
  }
  function renderError(msg){
    overlay.innerHTML =
      '<div class="cn-tmdb-modal">'+
        '<button class="cn-tmdb-close" aria-label="Fechar">×</button>'+
        '<div class="cn-tmdb-error"><p>Não encontramos esse nome no TMDB.</p><p style="font-size:12px;opacity:.7">'+(msg||'')+'</p></div>'+
      '</div>';
    overlay.querySelector('.cn-tmdb-close').addEventListener('click', closeModal);
  }

  // ===== Perfil de atores/diretores (otimizado) =====
  // 1 requisicao unica (append_to_response=combined_credits) em vez de 3 em cadeia
  // Pintura imediata do perfil; trailers carregam depois sem travar a abertura
  // Cache em sessionStorage (30 min) por nome pesquisado
  var CN_PCACHE='cnPersonCache:v1:', CN_PTTL=30*60*1000;
  function pcGet(k){ try{var r=sessionStorage.getItem(CN_PCACHE+k); if(!r) return null; var o=JSON.parse(r); return (Date.now()-o.t>CN_PTTL)?null:o.v;}catch(e){return null;} }
  function pcSet(k,v){ try{sessionStorage.setItem(CN_PCACHE+k,JSON.stringify({t:Date.now(),v:v}));}catch(e){} }

  function openActorModal(name){
    ensureOverlay();
    overlay.classList.add('open');
    document.body.classList.add('cn-modal-open');
    var key=(name||'').toLowerCase().trim();
    var cached=pcGet(key);
    if(cached){ renderActor(prepActor(cached)); enrichTrailers(prepActor(cached)).then(renderActor).catch(function(){}); return; }
    renderLoading();
    tmdb('/search/person',{query:name,include_adult:'false'})
      .then(function(res){
        if(!res.results || !res.results.length) throw new Error('sem resultados');
        res.results.sort(function(a,b){ return (b.popularity||0)-(a.popularity||0); });
        var p = res.results[0];
        return tmdb('/person/'+p.id,{append_to_response:'combined_credits'});
      })
      .then(function(person){
        pcSet(key, person);
        var d = prepActor(person);
        renderActor(d);                 // pinta ja com biografia e filmografia
        return enrichTrailers(d).then(renderActor).catch(function(){});
      })
      .catch(function(err){ renderError(err && err.message); });
  }

  function prepActor(person){
    var credits = person.combined_credits || {};
    var d = {person:person, credits:credits, trailers:[]};
    var cast = (credits.cast||[]).filter(function(c){return c.media_type==='movie'||c.media_type==='tv';});
    cast.sort(function(a,b){return (b.vote_count||0)-(a.vote_count||0);});
    d.top = cast.slice(0,20);
    return d;
  }

  function enrichTrailers(d){
    var topMovies = (d.top||[]).filter(function(c){return c.media_type==='movie';}).slice(0,4);
    if(!topMovies.length) return Promise.resolve(d);
    return Promise.all(topMovies.map(function(m){
      return tmdb('/movie/'+m.id+'/videos',{language:'en-US'})
        .then(function(v){
          var yt = (v.results||[]).find(function(r){return r.site==='YouTube' && (r.type==='Trailer'||r.type==='Teaser');});
          return yt ? {key:yt.key,name:yt.name,movieTitle:m.title||m.name,id:yt.id} : null;
        })
        .catch(function(){return null;});
    })).then(function(trailers){ d.trailers = trailers.filter(Boolean); return d; });
  }
  function renderActor(d){
    var p = d.person, top = d.top || [], trailers = d.trailers || [];
    var profile = p.profile_path ? 'https://image.tmdb.org/t/p/w500'+p.profile_path : '';
    var backdropSrc = top.find(function(c){return c.backdrop_path;});
    var bg = backdropSrc ? 'https://image.tmdb.org/t/p/original'+backdropSrc.backdrop_path : '';

    var filmsHtml = top.map(function(c){
      var poster = c.poster_path ? 'https://image.tmdb.org/t/p/w342'+c.poster_path : '';
      var score = c.vote_average && c.vote_average > 0 ? '<span class="score">★ '+c.vote_average.toFixed(1)+'</span>' : '';
      return '<div class="cn-tmdb-film">'+
        '<div class="poster">'+ (poster ? '<img loading="lazy" src="'+poster+'" alt="'+esc(c.title||c.name||'')+'">' : '<div style="display:grid;place-items:center;height:100%;font-size:32px">🎞️</div>') + score +'</div>'+
        '<div class="body"><p class="title">'+esc(c.title||c.name||'Sem título')+'</p>'+
        (c.character ? '<p class="character">como '+esc(c.character)+'</p>' : '') + '</div>'+
      '</div>';
    }).join('');

    var trailersHtml = trailers.length ? (
      '<section class="cn-tmdb-section"><h3>Trailers</h3><div class="cn-tmdb-trailers">'+
      trailers.map(function(t){
        return '<div class="cn-tmdb-trailer">'+
          '<div class="frame"><iframe src="https://www.youtube.com/embed/'+t.key+'" title="'+esc(t.name)+'" allowfullscreen allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture"></iframe></div>'+
          '<div class="caption"><p class="movie">'+esc(t.movieTitle)+'</p><p class="name">'+esc(t.name)+'</p></div>'+
          '</div>';
      }).join('')+
      '</div></section>'
    ) : '';

    overlay.innerHTML =
      '<div class="cn-tmdb-modal">'+
        '<button class="cn-tmdb-close" aria-label="Fechar">×</button>'+
        '<div class="cn-tmdb-hero">'+
          (bg ? '<div class="cn-tmdb-hero-bg" style="background-image:url('+bg+')"></div>' : '')+
          '<div class="cn-tmdb-hero-inner">'+
            '<div class="cn-tmdb-profile">'+ (profile ? '<img src="'+profile+'" alt="'+esc(p.name)+'">' : '<div style="display:grid;place-items:center;height:100%;font-size:48px">🎬</div>') +'</div>'+
            '<div>'+
              '<p class="cn-tmdb-dept">'+esc(p.known_for_department||'Perfil')+'</p>'+
              '<h2 class="cn-tmdb-name">'+esc(p.name)+'</h2>'+
              '<dl class="cn-tmdb-meta">'+
                (p.birthday ? '<div><dt>Nascimento</dt><dd>'+esc(fmtDate(p.birthday))+'</dd></div>' : '')+
                (p.place_of_birth ? '<div><dt>Local</dt><dd>'+esc(p.place_of_birth)+'</dd></div>' : '')+
              '</dl>'+
              (p.biography ? '<p class="cn-tmdb-bio">'+esc(p.biography.slice(0,600))+(p.biography.length>600?'…':'')+'</p>' : '')+
            '</div>'+
          '</div>'+
        '</div>'+
        (top.length ? '<section class="cn-tmdb-section"><h3>Filmografia</h3><div class="cn-tmdb-films">'+filmsHtml+'</div></section>' : '')+
        trailersHtml +
      '</div>';
    overlay.querySelector('.cn-tmdb-close').addEventListener('click', closeModal);
    overlay.scrollTop = 0;
  }
  function esc(s){ return String(s==null?'':s).replace(/[&<>"']/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c];}); }

  /* ---------- boot ---------- */
  function boot(){
    initFontRegulator();
    initAuthorCard();
    markActors();
  }
  if(document.readyState === 'loading'){
    document.addEventListener('DOMContentLoaded', boot);
  } else {
    boot();
  }
  // Re-run late in case Blogger injects content after load
  setTimeout(boot, 800);
  setTimeout(boot, 2400);
})();
