/* PATCH: excluir comentário (modal) + aviso WhatsApp */
(function(){
  var WA_NUMBER = '5585986001996'; // número destino (formato internacional)
  var seenKey  = 'j2n_seen_comments_v1';

  function getSeen(){ try{return JSON.parse(localStorage.getItem(seenKey)||'[]');}catch(e){return[];} }
  function markSeen(id){ var a=getSeen(); if(a.indexOf(id)<0){a.push(id); localStorage.setItem(seenKey,JSON.stringify(a.slice(-500)));} }
  function waLink(text){ return 'https://wa.me/'+WA_NUMBER+'?text='+encodeURIComponent(text); }

  // Botão "Excluir" nos comentários dentro do modal trend-news/news
  function attachDelete(){
    document.querySelectorAll('.trend-news-modal-card .comment, .news-modal-card .comment, .modal-card .comment')
      .forEach(function(el){
        if(el.querySelector('.delete-comment')) return;
        var btn = document.createElement('button');
        btn.type='button';
        btn.className='delete-comment';
        btn.textContent='Excluir';
        btn.addEventListener('click', function(ev){
          ev.preventDefault();
          if(!confirm('Excluir este comentário?')) return;
          // Se o item tem data-blogger-comment-id, abre o painel de moderação do Blogger.
          var cid = el.getAttribute('data-comment-id') || el.getAttribute('data-blogger-comment-id');
          if(cid){
            window.open('https://www.blogger.com/comment-iframe.g?blogID='+ (window.BLOG_ID||'') +'&commentID='+cid, '_blank');
          }
          el.style.transition='opacity .25s';
          el.style.opacity='0';
          setTimeout(function(){ el.remove(); }, 260);
        });
        el.appendChild(btn);
      });
  }

  // Notificação por WhatsApp: aparece um botão flutuante quando um comentário novo é detectado.
  // Observação: Blogger não permite enviar WhatsApp automaticamente sem serviço externo.
  // Este patch abre o WhatsApp Web/App já com a mensagem pronta para você confirmar o envio.
  // Para envio 100% automático, cadastre-se em https://www.callmebot.com/blog/free-api-whatsapp-messages/
  // e substitua CALLMEBOT_APIKEY abaixo pela sua chave.
  var CALLMEBOT_APIKEY = ''; // <-- coloque sua APIKEY do CallMeBot aqui (opcional)

  function notifyWhatsApp(comment){
    var msg = 'Novo comentário em ' + (comment.postTitle || document.title) +
              '\nAutor: ' + (comment.author||'anônimo') +
              '\n"' + (comment.text||'').slice(0,200) + '"\n' + (comment.url||location.href);
    if(CALLMEBOT_APIKEY){
      // Envio automático via CallMeBot (requer cadastro prévio no número destino)
      var u = 'https://api.callmebot.com/whatsapp.php?phone='+WA_NUMBER+
              '&text='+encodeURIComponent(msg)+'&apikey='+encodeURIComponent(CALLMEBOT_APIKEY);
      var img = new Image(); img.src = u; // beacon GET
    } else {
      // Fallback: mostra botão discreto para você abrir o WhatsApp e enviar.
      showToast(msg);
    }
  }

  function showToast(msg){
    var t = document.getElementById('j2n-wa-toast');
    if(!t){
      t = document.createElement('a');
      t.id='j2n-wa-toast';
      t.style.cssText='position:fixed;right:16px;bottom:16px;z-index:99999;background:#25d366;color:#fff;padding:10px 14px;border-radius:24px;font:600 13px system-ui,sans-serif;text-decoration:none;box-shadow:0 8px 24px rgba(0,0,0,.25);display:flex;align-items:center;gap:8px;';
      t.target='_blank';
      t.rel='noopener';
      t.innerHTML='<svg width="16" height="16" viewBox="0 0 24 24" fill="#fff"><path d="M20.5 3.5A11 11 0 0 0 3.2 17.3L2 22l4.8-1.3A11 11 0 1 0 20.5 3.5zM12 20a8 8 0 0 1-4.1-1.1l-.3-.2-2.9.8.8-2.8-.2-.3A8 8 0 1 1 12 20zm4.6-5.9c-.3-.1-1.5-.7-1.7-.8s-.4-.1-.6.1-.7.8-.8 1-.3.2-.5.1a6.6 6.6 0 0 1-3.3-2.9c-.2-.4.2-.3.6-1.1.1-.1 0-.3 0-.4l-.8-1.9c-.2-.5-.4-.4-.6-.4h-.5c-.2 0-.5.1-.7.3s-1 1-1 2.4 1 2.8 1.2 3 2 3 4.8 4.2c.7.3 1.2.5 1.6.6.7.2 1.3.2 1.8.1.6-.1 1.5-.6 1.7-1.2s.2-1.1.2-1.2-.2-.2-.5-.3z"/></svg><span>Novo comentário — enviar no WhatsApp</span>';
      document.body.appendChild(t);
    }
    t.href = waLink(msg);
    t.style.display='flex';
    clearTimeout(t._h);
    t._h = setTimeout(function(){ t.style.display='none'; }, 20000);
  }

  // Detecta novos comentários dentro do modal
  function scanComments(){
    document.querySelectorAll('.trend-news-modal-card .comment, .news-modal-card .comment, .modal-card .comment')
      .forEach(function(el){
        var id = el.getAttribute('data-comment-id') || el.getAttribute('data-blogger-comment-id') || (el.textContent||'').trim().slice(0,80);
        if(!id) return;
        if(getSeen().indexOf(id) >= 0) return;
        markSeen(id);
        notifyWhatsApp({
          author: (el.querySelector('.author,.name')||{}).textContent,
          text:   (el.querySelector('.body,.text,p')||{}).textContent,
          postTitle: document.title,
          url: location.href
        });
      });
  }

  function boot(){ attachDelete(); scanComments(); }
  if(document.readyState==='loading') document.addEventListener('DOMContentLoaded', boot); else boot();

  // Observa aberturas do modal (SPA-like)
  var mo = new MutationObserver(function(){ attachDelete(); scanComments(); });
  mo.observe(document.body, {childList:true, subtree:true});
})();
