(function(){
  // === CONFIGURAÇÃO ===
  // ⚠️ SUBSTITUA pela sua chave TMDB v3 em https://www.themoviedb.org/settings/api
  var TMDB_KEY = '0344712bb861098caefcc9a8d67beb09';
  var TMDB = 'https://api.themoviedb.org/3';
  var IMG = 'https://image.tmdb.org/t/p/';
  var LANG = 'pt-BR';
  var BLOG_URL = (window.location.origin) || 'https://www.callangonerd.com';

  // === NAVEGAÇÃO / STACK ===
  var stack = [];
  var returnFn = null;      // como voltar para a pagina/contexto anterior ao abrir a obra
  var histPushed = false;   // se ja empilhamos uma entrada no historico do navegador
  function setReturn(fn){ returnFn = (typeof fn === 'function') ? fn : null; }
  function pushState(fn){
    stack.push(fn);
    if(!histPushed){
      histPushed = true;
      try{ history.pushState({cnObra:1}, '', location.href); }catch(e){}
    }
  }
  function goBack(){
    stack.pop();
    var prev = stack[stack.length-1];
    if(prev){ prev(); return; }
    // Pilha vazia: volta para a pagina/contexto anteriormente acessado
    closeOverlay();
    var back = returnFn; returnFn = null;
    if(back){ try{ back(); }catch(e){} }
    else if(document.referrer && document.referrer.indexOf(location.host) > -1){ history.back(); }
  }
  function goHome(){ stack=[]; returnFn=null; closeOverlay(); window.location.href='/'; }
  // Botao "voltar" do navegador tambem fecha a pagina de obra
  window.addEventListener('popstate', function(){
    if(document.getElementById('cn-overlay') && document.getElementById('cn-overlay').classList.contains('cn-open')){
      histPushed = false;
      stack = [];
      closeOverlay();
      var back = returnFn; returnFn = null;
      if(back){ try{ back(); }catch(e){} }
    }
  });

  // === OVERLAY ===
  function ensureOverlay(){
    var o = document.getElementById('cn-overlay');
    if(!o){
      o = document.createElement('div');
      o.id = 'cn-overlay';
      o.innerHTML = '<div class="cn-page" id="cn-page-content"></div>';
      document.body.appendChild(o);
      o.addEventListener('click', function(e){ if(e.target===o) closeOverlay(); });
    }
    return o;
  }
  function openOverlay(html){
    var o = ensureOverlay();
    document.getElementById('cn-page-content').innerHTML = html;
    o.classList.add('cn-open');
    document.body.classList.add('cn-obra-open');
    document.body.style.overflow='hidden';
    window.scrollTo(0,0);
    o.scrollTop=0;
  }
  function closeOverlay(){
    var o = document.getElementById('cn-overlay');
    if(o){ o.classList.remove('cn-open'); document.body.classList.remove('cn-obra-open'); document.body.style.overflow=''; }
    stack = [];
    if(histPushed){ histPushed = false; }
  }

  function topbar(backLabel){
    return '<div class="cn-topbar">'+
      '<button class="cn-btn cn-tb-btn" onclick="CN.back()"><span class="cn-tb-ico">&#8592;</span>'+(backLabel||'Voltar')+'</button>'+
      '<button class="cn-btn cn-tb-btn cn-tb-home" onclick="CN.home()"><span class="cn-tb-ico">&#9679;</span>Página Principal</button>'+
      '<button class="cn-btn cn-tb-close" style="margin-left:auto" aria-label="Fechar" onclick="CN.close()">&#10005;</button>'+
    '</div>';
  }

  // === TMDB ===
  function tmdb(path, extra){
    var url = TMDB+path+(path.indexOf('?')>-1?'&':'?')+'api_key='+TMDB_KEY+'&language='+LANG+(extra?'&'+extra:'');
    return fetch(url).then(function(r){ return r.json(); });
  }
  function poster(p,size){ return p? IMG+(size||'w342')+p : 'https://via.placeholder.com/300x450/1a1a24/8b5cf6?text=Sem+Imagem'; }

  // === BUSCA NOTÍCIAS DO BLOG ===
  function blogNews(title, cb){
    var q = encodeURIComponent(title);
    var url = BLOG_URL+'/feeds/posts/default?q='+q+'&alt=json&max-results=6';
    var s = document.createElement('script');
    var cbName = 'cnBlog'+Date.now();
    window[cbName] = function(data){
      var items = (data && data.feed && data.feed.entry) || [];
      cb(items.map(function(e){
        var link=''; (e.link||[]).forEach(function(l){ if(l.rel==='alternate') link=l.href; });
        var img=''; var content=(e.content&&e.content.$t)||(e.summary&&e.summary.$t)||'';
        var m = content.match(/<img[^>]+src=["']([^"']+)["']/i);
        if(m) img = m[1];
        return { title:(e.title&&e.title.$t)||'', link:link, img:img, date:(e.published&&e.published.$t)||'' };
      }));
      delete window[cbName]; s.remove();
    };
    s.src = url+'&callback='+cbName;
    document.body.appendChild(s);
  }

  // === PÁGINA DA OBRA ===
  function renderObra(type, id){
    openOverlay('<div class="cn-loading">Carregando obra</div>');
    var kind = type==='tv'?'tv':'movie';
    Promise.all([
      tmdb('/'+kind+'/'+id,'append_to_response=videos,credits,images&include_image_language=pt,null'),
    ]).then(function(res){
      var d = res[0];
      var title = d.title || d.name || 'Sem título';
      var year = (d.release_date||d.first_air_date||'').slice(0,4);
      var genres = (d.genres||[]).map(function(g){return g.name;}).join(', ');
      var rating = d.vote_average? d.vote_average.toFixed(1):'N/A';
      var director = '';
      if(d.credits && d.credits.crew){
        var dir = d.credits.crew.find(function(c){return c.job==='Director';});
        if(dir) director = dir.name;
        if(!director){
          var creator = (d.created_by||[])[0]; if(creator) director = creator.name;
        }
      }
      var trailer = ((d.videos&&d.videos.results)||[]).find(function(v){return v.site==='YouTube' && (v.type==='Trailer'||v.type==='Teaser');});
      var backdrop = d.backdrop_path? IMG+'original'+d.backdrop_path : (d.poster_path?IMG+'original'+d.poster_path:'');
      var cast = ((d.credits&&d.credits.cast)||[]).slice(0,12);
      var images = ((d.images&&d.images.backdrops)||[]).slice(0,8);

      var html = topbar('Voltar')+
        '<div class="cn-hero" style="background-image:linear-gradient(180deg,rgba(15,15,20,.3),rgba(15,15,20,.95)),url('+backdrop+')">'+
          '<img class="cn-poster" src="'+poster(d.poster_path,'w500')+'" alt="'+title+'"/>'+
          '<div class="cn-hero-meta">'+
            '<div class="cn-tags">'+(genres?genres.split(', ').map(function(g){return '<span>'+g+'</span>';}).join(''):'')+'</div>'+
            '<h1>'+title+'</h1>'+
            '<p class="cn-synopsis">'+(d.overview||'Sinopse não disponível.')+'</p>'+
            '<div class="cn-facts">'+
              (year?'<div><b>'+year+'</b>Ano</div>':'')+
              (director?'<div><b>'+director+'</b>Direção</div>':'')+
              '<div><b>⭐ '+rating+'</b>Avaliação</div>'+
            '</div>'+
            (trailer?'<div style="margin-top:16px"><button class="cn-btn cn-btn-primary" onclick="CN.trailer(\''+trailer.key+'\')">▶ Assistir ao Trailer</button></div>':'')+
          '</div>'+
        '</div>'+
        (trailer?'<div class="cn-section"><h2>Trailer Oficial</h2><div class="cn-trailer-wrap"><iframe src="https://www.youtube.com/embed/'+trailer.key+'" allowfullscreen></iframe></div></div>':'')+
        (images.length?'<div class="cn-section"><h2>Galeria</h2><div class="cn-gallery">'+images.map(function(i){return '<img src="'+IMG+'w780'+i.file_path+'" alt=""/>';}).join('')+'</div></div>':'')+
        (cast.length?'<div class="cn-section"><h2>Elenco</h2><div class="cn-cast">'+cast.map(function(a){
          return '<div class="cn-actor" onclick="CN.person('+a.id+')"><img src="'+poster(a.profile_path,'w185')+'" alt="'+a.name+'"/><b>'+a.name+'</b><small>'+(a.character||'')+'</small></div>';
        }).join('')+'</div></div>':'')+
        '<div class="cn-section"><h2>Últimas Notícias no Callango Nerd</h2><div class="cn-news" id="cn-news-list"><div class="cn-loading">Buscando notícias</div></div></div>';

      pushState(function(){ openOverlay(html); });
      openOverlay(html);

      blogNews(title, function(items){
        var el = document.getElementById('cn-news-list');
        if(!el) return;
        if(!items.length){ el.innerHTML='<p style="color:#a1a1aa;grid-column:1/-1">Nenhuma notícia relacionada encontrada.</p>'; return; }
        el.innerHTML = items.map(function(n){
          return '<a href="'+n.link+'">'+(n.img?'<img src="'+n.img+'" alt=""/>':'')+'<div><h4>'+n.title+'</h4><small>'+new Date(n.date).toLocaleDateString('pt-BR')+'</small></div></a>';
        }).join('');
      });
    }).catch(function(){
      openOverlay(topbar('Voltar')+'<div class="cn-loading" style="color:#ec4899">Não foi possível carregar. Verifique a chave TMDB.</div>');
    });
  }

  // === PÁGINA DA PESSOA ===
  function renderPerson(id){
    openOverlay('<div class="cn-loading">Carregando perfil</div>');
    tmdb('/person/'+id,'append_to_response=combined_credits,images').then(function(d){
      var bio = d.biography || 'Biografia não disponível em português.';
      var photo = poster(d.profile_path,'w500');
      var backdrop = ((d.images&&d.images.profiles)||[])[0];
      backdrop = backdrop? IMG+'original'+backdrop.file_path : photo;
      var credits = ((d.combined_credits&&d.combined_credits.cast)||[]).concat((d.combined_credits&&d.combined_credits.crew)||[]);
      var seen={}; credits = credits.filter(function(c){ if(seen[c.id+'_'+c.media_type]) return false; seen[c.id+'_'+c.media_type]=1; return c.poster_path;});
      credits.sort(function(a,b){ return (b.popularity||0)-(a.popularity||0); });
      credits = credits.slice(0,18);

      var html = topbar('Voltar')+
        '<div class="cn-hero" style="background-image:linear-gradient(180deg,rgba(15,15,20,.3),rgba(15,15,20,.95)),url('+backdrop+')">'+
          '<img class="cn-poster" src="'+photo+'" alt="'+d.name+'" style="aspect-ratio:2/3;object-fit:cover"/>'+
          '<div class="cn-hero-meta">'+
            '<div class="cn-tags"><span>'+(d.known_for_department||'Cinema')+'</span></div>'+
            '<h1>'+d.name+'</h1>'+
            '<p class="cn-synopsis">'+bio.slice(0,600)+(bio.length>600?'...':'')+'</p>'+
            '<div class="cn-facts">'+
              (d.birthday?'<div><b>'+new Date(d.birthday).toLocaleDateString('pt-BR')+'</b>Nascimento</div>':'')+
              (d.place_of_birth?'<div><b>'+d.place_of_birth+'</b>Local</div>':'')+
            '</div>'+
          '</div>'+
        '</div>'+
        '<div class="cn-section"><h2>Filmografia</h2><div class="cn-filmo">'+credits.map(function(c){
          var t = c.title||c.name||'';
          var y = (c.release_date||c.first_air_date||'').slice(0,4);
          var role = c.character?('como '+c.character):(c.job||'');
          return '<div class="cn-film" onclick="CN.obra(\''+c.media_type+'\','+c.id+')"><img src="'+poster(c.poster_path,'w342')+'" alt=""/><div><b>'+t+'</b><small>'+y+' · '+role+'</small></div></div>';
        }).join('')+'</div></div>';

      pushState(function(){ openOverlay(html); });
      openOverlay(html);
    }).catch(function(){
      openOverlay(topbar('Voltar')+'<div class="cn-loading" style="color:#ec4899">Não foi possível carregar o perfil.</div>');
    });
  }

  // === TRAILER FLUTUANTE ===
  function openTrailer(key){
    var m = document.getElementById('cn-video-modal');
    if(!m){
      m = document.createElement('div');
      m.id='cn-video-modal';
      m.innerHTML='<div class="cn-vwrap"><button class="cn-close" onclick="CN.closeTrailer()">✕</button><iframe id="cn-video-frame" allowfullscreen></iframe></div>';
      document.body.appendChild(m);
      m.addEventListener('click',function(e){ if(e.target===m) closeTrailer(); });
    }
    document.getElementById('cn-video-frame').src='https://www.youtube.com/embed/'+key+'?autoplay=1';
    m.classList.add('cn-open');
  }
  function closeTrailer(){
    var m = document.getElementById('cn-video-modal');
    if(m){ m.classList.remove('cn-open'); document.getElementById('cn-video-frame').src=''; }
  }

  // === BARRA DA OBRA NO POST ===
  function initObraBar(){
    var post = document.querySelector('.post-body, .post, [class*="post-body"]');
    if(!post) return;
    var marker = post.querySelector('[data-cn-obra], .cn-obra');
    var type='movie', id=null, title=null;
    if(marker){
      var t = marker.getAttribute('data-cn-obra') || marker.getAttribute('data-tmdb') || '';
      if(t.indexOf('/')>-1){ type=t.split('/')[0]; id=t.split('/')[1]; }
      else if(/^\d+$/.test(t)){ id=t; type = marker.getAttribute('data-tipo')==='serie'?'tv':'movie'; }
      title = marker.getAttribute('data-titulo') || marker.getAttribute('data-title');
    }
    if(!id && !title){
      // fallback: primeiro label que pareça uma obra (label com "Filme:" ou "Série:")
      var labels = document.querySelectorAll('.post-labels a, [rel="tag"]');
      for(var i=0;i<labels.length;i++){
        var txt = labels[i].textContent.trim();
        var mm = txt.match(/^(Filme|Série|Serie|Anime):\s*(.+)$/i);
        if(mm){ title = mm[2]; type = /série|serie|anime/i.test(mm[1])?'tv':'movie'; break; }
      }
    }
    if(!id && !title) return;

    var bar = document.createElement('div');
    bar.id='cn-obra-bar';
    bar.innerHTML = '<div class="cn-loading" style="padding:0;color:#fff">Carregando obra…</div>';
    post.appendChild(bar);

    var resolve = id? Promise.resolve({id:id,type:type}) :
      tmdb('/search/multi','query='+encodeURIComponent(title)).then(function(d){
        var r = (d.results||[]).filter(function(x){return x.media_type==='movie'||x.media_type==='tv';})[0];
        if(!r) throw new Error('nao encontrado');
        return {id:r.id, type:r.media_type};
      });

    resolve.then(function(ref){
      return tmdb('/'+ref.type+'/'+ref.id,'append_to_response=videos').then(function(d){
        return {ref:ref, d:d};
      });
    }).then(function(x){
      var d = x.d, ref = x.ref;
      var t = d.title || d.name;
      var g = (d.genres||[]).map(function(x){return x.name;}).slice(0,2).join(' · ');
      var tr = ((d.videos&&d.videos.results)||[]).find(function(v){return v.site==='YouTube'&&(v.type==='Trailer'||v.type==='Teaser');});
      bar.innerHTML =
        (tr?'<div class="cn-inline-trailer" data-key="'+tr.key+'" role="button" tabindex="0" aria-label="Assistir trailer de '+t+'">'+
            '<img class="cn-inline-thumb" loading="lazy" src="https://i.ytimg.com/vi/'+tr.key+'/hqdefault.jpg" alt="Trailer de '+t+'"/>'+
            '<span class="cn-inline-play" aria-hidden="true">▶</span>'+
          '</div>':'')+
        '<img src="'+poster(d.poster_path,'w185')+'" alt="'+t+'"/>'+
        '<div class="cn-obra-info"><span>'+(ref.type==='tv'?'Série · ':'Filme · ')+g+'</span><h4>'+t+'</h4></div>'+
        '<div class="cn-btns">'+
          '<button class="cn-btn-primary" onclick="CN.obra(\''+ref.type+'\','+ref.id+')">Saiba mais sobre '+t+'</button>'+
        '</div>';
      if(tr){
        var face = bar.querySelector('.cn-inline-trailer');
        var play = function(){
          var f = document.createElement('iframe');
          f.src='https://www.youtube.com/embed/'+tr.key+'?autoplay=1&rel=0';
          f.setAttribute('allow','autoplay; encrypted-media; picture-in-picture; fullscreen');
          f.setAttribute('allowfullscreen','');
          f.className='cn-inline-frame';
          face.replaceWith(f);
        };
        face.addEventListener('click', play);
        face.addEventListener('keydown', function(e){ if(e.key==='Enter'||e.key===' '){ e.preventDefault(); play(); } });
      }
    }).catch(function(){ bar.remove(); });
  }

  // === BUSCA DO SITE: ENRIQUECE COM RESULTADOS DE OBRAS ===
  function initSearchEnrichment(){
    // Detecta página de resultados de busca do Blogger
    var q = null;
    var m = window.location.search.match(/[?&]q=([^&]+)/);
    if(m){ q = decodeURIComponent(m[1].replace(/\+/g,' ')); }
    if(!q) return;
    // Container: injeta no topo da área principal de resultados — layout alinhado ao padrão do site
    var host = document.querySelector('.blog-posts, #main .widget, .main-inner, main, #content') || document.body;
    var box = document.createElement('div');
    box.id = 'cn-search-enrich';
    box.style.cssText = 'margin:0 0 24px;padding:22px;background:#12161f;border:1px solid #232735;border-radius:10px;color:#e6e8ee;font-family:Open Sans,system-ui,sans-serif;box-shadow:0 12px 30px -18px rgba(0,0,0,.65);position:relative;overflow:hidden';
    box.innerHTML = '<h3 style="margin:0 0 14px;font-size:13px;font-weight:800;text-transform:uppercase;letter-spacing:.14em;color:#fff;display:flex;align-items:center;gap:10px"><span style="width:4px;height:20px;background:linear-gradient(180deg,#c9142a,#7a0e1c);border-radius:4px"></span>Filmes, Séries e Animes encontrados para <span style="color:#ff8a95">&laquo;'+q+'&raquo;</span></h3><div id="cn-search-enrich-results" class="cn-loading" style="color:#8b93a7;padding:10px">Buscando…</div>';
    host.insertBefore(box, host.firstChild);
    tmdb('/search/multi','query='+encodeURIComponent(q)).then(function(d){
      var r = (d.results||[]).filter(function(x){return (x.media_type==='movie'||x.media_type==='tv') && x.poster_path;}).slice(0,10);
      var el = document.getElementById('cn-search-enrich-results');
      if(!r.length){ box.remove(); return; }
      el.className = '';
      el.style.cssText='display:grid;grid-template-columns:repeat(auto-fill,minmax(130px,1fr));gap:12px';
      el.innerHTML = r.map(function(x){
        var t = x.title||x.name;
        var y = (x.release_date||x.first_air_date||'').slice(0,4);
        var tipo = x.media_type==='tv'?'Série':'Filme';
        return '<div class="cn-film" onclick="CN.obra(\''+x.media_type+'\','+x.id+')" style="cursor:pointer;background:#0c131e;border:1px solid #232735;border-radius:8px;overflow:hidden;transition:transform .2s,border-color .2s" onmouseover="this.style.transform=\'translateY(-3px)\';this.style.borderColor=\'#c9142a\'" onmouseout="this.style.transform=\'\';this.style.borderColor=\'#232735\'"><img style="width:100%;aspect-ratio:2/3;object-fit:cover" src="'+poster(x.poster_path,'w342')+'"/><div style="padding:8px"><b style="font-size:12px;display:block;color:#fff">'+t+'</b><small style="color:#8b93a7;font-size:10px;text-transform:uppercase;letter-spacing:.08em">'+tipo+(y?' · '+y:'')+'</small></div></div>';
      }).join('');
    }).catch(function(){ box.remove(); });
  }

  // === LIGHTBOX PARA .cn-gallery ===
  function initGalleryLightbox(){
    if(window.__cnLbInit) return; window.__cnLbInit = true;
    document.addEventListener('click', function(e){
      var img = e.target.closest('.cn-gallery img, .cn-hero img.cn-poster');
      if(!img) return;
      e.preventDefault();
      var gallery = img.closest('.cn-gallery');
      var list = gallery ? Array.prototype.slice.call(gallery.querySelectorAll('img')) : [img];
      var idx = list.indexOf(img);
      openLightbox(list, idx);
    });
    document.addEventListener('keydown', function(e){
      var lb = document.getElementById('cn-lightbox');
      if(!lb || !lb.classList.contains('cn-open')) return;
      if(e.key==='Escape') closeLightbox();
      if(e.key==='ArrowRight') stepLightbox(1);
      if(e.key==='ArrowLeft') stepLightbox(-1);
    });
  }
  function openLightbox(list, idx){
    var lb = document.getElementById('cn-lightbox');
    if(!lb){
      lb = document.createElement('div');
      lb.id = 'cn-lightbox';
      lb.innerHTML = '<button class="cn-lb-close" type="button" aria-label="Fechar">&times;</button>'
        + '<button class="cn-lb-nav cn-lb-prev" type="button" aria-label="Anterior">&#8249;</button>'
        + '<img alt=""/>'
        + '<button class="cn-lb-nav cn-lb-next" type="button" aria-label="Próxima">&#8250;</button>';
      document.body.appendChild(lb);
      lb.addEventListener('click', function(ev){
        if(ev.target===lb) closeLightbox();
        else if(ev.target.classList.contains('cn-lb-close')) closeLightbox();
        else if(ev.target.classList.contains('cn-lb-prev')){ ev.stopPropagation(); stepLightbox(-1); }
        else if(ev.target.classList.contains('cn-lb-next')){ ev.stopPropagation(); stepLightbox(1); }
      });
    }
    lb.__list = list;
    lb.__idx = idx;
    lb.querySelector('img').src = list[idx].getAttribute('data-full') || list[idx].src;
    lb.querySelector('.cn-lb-prev').style.display = list.length>1?'flex':'none';
    lb.querySelector('.cn-lb-next').style.display = list.length>1?'flex':'none';
    lb.classList.add('cn-open');
  }
  function stepLightbox(dir){
    var lb = document.getElementById('cn-lightbox'); if(!lb || !lb.__list) return;
    var n = lb.__list.length;
    lb.__idx = (lb.__idx + dir + n) % n;
    lb.querySelector('img').src = lb.__list[lb.__idx].getAttribute('data-full') || lb.__list[lb.__idx].src;
  }
  function closeLightbox(){
    var lb = document.getElementById('cn-lightbox'); if(lb) lb.classList.remove('cn-open');
  }

  // === API PÚBLICA ===
  window.CN = {
    obra: renderObra,
    person: renderPerson,
    trailer: openTrailer,
    closeTrailer: closeTrailer,
    back: goBack,
    setReturn: setReturn,
    home: goHome,
    close: closeOverlay,
    search: initSearchEnrichment,
    lightbox: openLightbox
  };

  // === INIT ===
  function init(){
    try{ initSearchEnrichment(); }catch(e){}
    try{ initObraBar(); }catch(e){}
    try{ initGalleryLightbox(); }catch(e){}
    try{ if(window.MarcioVoice) MarcioVoice.init(); }catch(e){}
  }
  if(document.readyState==='loading'){ document.addEventListener('DOMContentLoaded', init); }
  else { init(); }

  // ESC fecha overlays
  document.addEventListener('keydown', function(e){
    if(e.key==='Escape'){ closeTrailer(); closeOverlay(); }
  });

})();
