(function(){
  var STORAGE_KEY = 'cn_marcio_vocab_v1';
  // Dicionário base extraído do estilo editorial de Márcio Oliveira em callangonerd.com
  // (tom coloquial-crítico, referências geek/pop, cadência analítica, humor seco, expressões recorrentes).
  var BASE = {
    aberturas: [
      'Vamos combinar uma coisa', 'Olha, sem enrolação', 'Direto ao ponto',
      'Preparem o café, porque', 'Segura essa', 'Anota aí, nerd',
      'É oficial', 'Pausa dramática', 'Sem spoilers, mas',
      'Papo reto', 'Análise rápida', 'Do meu ponto de vista',
      'Deixando a empolgação de lado', 'Com os pés no chão',
      'Falando como espectador', 'Se me perguntar', 'Vamos ao que interessa',
      'Fora do hype', 'Na real', 'Cinéfilo aqui avisa'
    ],
    conectores: [
      'e aqui mora o detalhe', 'e é aí que a porca torce o rabo',
      'e não é força de expressão', 'no melhor estilo Callango',
      'com a assinatura da casa', 'e a gente sabe onde isso vai dar',
      'sem meias palavras', 'para o bem e para o mal'
    ],
    adjetivos: [
      'contundente','ousado','afiado','visceral','tecnicamente impecável',
      'nostálgico na medida','narrativamente ambicioso','esteticamente potente',
      'divisivo','autoral','irregular mas fascinante','cinéfilo de raiz'
    ],
    veredictos: [
      'Vale cada minuto.', 'Fica o registro.', 'Recomendo com ressalvas.',
      'Não é para todos, mas quem gosta vai amar.', 'Um golaço.',
      'Cumpre o que promete e entrega mais.', 'Fica a dica.',
      'Assista com atenção — merece.'
    ],
    referenciasGeek: [
      'na melhor tradição de Spielberg','com pegada de Denis Villeneuve',
      'lembrando o auge da Amblin','com DNA Studio Ghibli',
      'flertando com o Universo Nolan','no espírito dos clássicos oitentistas'
    ],
    assinatura: 'Callango Nerd — cultura pop com opinião.'
  };

  function load(){
    try{
      var raw = localStorage.getItem(STORAGE_KEY);
      if(!raw) return JSON.parse(JSON.stringify(BASE));
      var d = JSON.parse(raw);
      // merge preservando novidades da BASE
      Object.keys(BASE).forEach(function(k){
        if(Array.isArray(BASE[k])){
          d[k] = Array.from(new Set([].concat(d[k]||[], BASE[k])));
        } else if(!d[k]) d[k]=BASE[k];
      });
      return d;
    }catch(e){ return JSON.parse(JSON.stringify(BASE)); }
  }
  function save(d){ try{ localStorage.setItem(STORAGE_KEY, JSON.stringify(d)); }catch(e){} }

  // Enriquece o vocabulário a partir de novos posts (extrai n-grams curtos frequentes)
  function harvestFromPosts(){
    var d = load();
    var texts = [];
    document.querySelectorAll('.post-body, .post .entry-content, article').forEach(function(el){
      var t = (el.innerText||'').replace(/\s+/g,' ').trim();
      if(t.length>200) texts.push(t);
    });
    if(!texts.length){ save(d); return d; }
    var corpus = texts.join(' ').toLowerCase();
    // frases coloquiais recorrentes (2-4 palavras) com marcadores tipicos do Marcio
    var patterns = [
      /vamos combinar[^.,;!?]{0,40}/g,
      /a verdade[^.,;!?]{0,40}/g,
      /no fim das contas[^.,;!?]{0,40}/g,
      /a gente sabe[^.,;!?]{0,40}/g,
      /fica o registro[^.,;!?]{0,40}/g,
      /cumpre o que promete[^.,;!?]{0,40}/g
    ];
    patterns.forEach(function(rx){
      var m; while((m=rx.exec(corpus))){
        var s = m[0].trim();
        if(s.length>6 && s.length<60){
          if(d.conectores.indexOf(s)===-1) d.conectores.push(s);
        }
        if(d.conectores.length>120) break;
      }
    });
    save(d);
    return d;
  }

  // Retorna um item aleatorio de uma categoria
  function pick(cat){
    var d = load();
    var arr = d[cat]||BASE[cat]||[];
    return arr[Math.floor(Math.random()*arr.length)] || '';
  }

  // Reescreve/tempera um texto (usado por integracoes TMDB e geradores locais)
  function marcioTone(txt){
    if(!txt) return txt;
    var abertura = pick('aberturas');
    var conector = pick('conectores');
    var adj = pick('adjetivos');
    var veredicto = pick('veredictos');
    return abertura + ': ' + txt.trim().replace(/\.$/,'') + '. E ' + conector + ' — um trabalho ' + adj + '. ' + veredicto;
  }

  window.MarcioVoice = {
    init: function(){ try{ harvestFromPosts(); }catch(e){} },
    vocab: load,
    pick: pick,
    tone: marcioTone,
    reset: function(){ try{ localStorage.removeItem(STORAGE_KEY); }catch(e){} }
  };
  if(document.readyState==='loading'){
    document.addEventListener('DOMContentLoaded', function(){ try{ harvestFromPosts(); }catch(e){} });
  } else { try{ harvestFromPosts(); }catch(e){} }
})();
