(function(){
  function ready(fn){ if(document.readyState!=='loading'){fn();} else {document.addEventListener('DOMContentLoaded',fn);} }
  ready(function(){
    if(!document.body.classList.contains('is-homepage')) return;

    /* --- Kill infinite scroll on homepage --- */
    try{ if(window.infinite_scroll){ window.infinite_scroll = null; } }catch(e){}

    var POSTS_PER_PAGE = 6;

    /* --- 1) Limit visible posts to POSTS_PER_PAGE (listing header removed) --- */
    var blogPosts = document.querySelector('.blog-posts');
    if(blogPosts){
      blogPosts.classList.add('view-grid');
      var items = blogPosts.children;
      var shown = 0;
      for(var i=0;i<items.length;i++){
        if(!items[i].classList || !items[i].classList.contains('blog-post')) continue;
        if(shown >= POSTS_PER_PAGE) items[i].style.display = 'none';
        else shown++;
      }
    }

    /* --- 2) Numeric pagination via Blogger feed --- */
    var pager = document.getElementById('blog-pager');
    if(pager){
      var wrap = document.createElement('div');
      wrap.className = 'numbered-pager';
      wrap.innerHTML = '<span class="current">1</span>';
      pager.appendChild(wrap);

      var qs = new URLSearchParams(location.search);
      var updatedMax = qs.get('updated-max');
      var pageParam = parseInt(qs.get('page')||'1', 10);

      fetch('/feeds/posts/summary?alt=json&max-results=1')
        .then(function(r){return r.json();})
        .then(function(j){
          var total = parseInt((j.feed.openSearch$totalResults||{}).$t || '0', 10);
          var pages = Math.max(1, Math.ceil(total/POSTS_PER_PAGE));

          /* Determine current page from ?page or from updated-max index */
          var current = pageParam;
          var promise = Promise.resolve(current);
          if(updatedMax){
            promise = fetch('/feeds/posts/summary?alt=json&max-results=1&updated-max='+encodeURIComponent(updatedMax))
              .then(function(r){return r.json();})
              .then(function(j2){
                var remaining = parseInt((j2.feed.openSearch$totalResults||{}).$t || '0', 10);
                return Math.max(1, pages - Math.ceil(remaining/POSTS_PER_PAGE) + 1);
              }).catch(function(){return 1;});
          }

          promise.then(function(cur){
            renderPager(cur, pages);
            if(pageParam>1 && !updatedMax){
              /* Redirect to correct offset once */
              var offset = (pageParam-1)*POSTS_PER_PAGE + 1;
              fetch('/feeds/posts/summary?alt=json&start-index='+offset+'&max-results=1')
                .then(function(r){return r.json();})
                .then(function(j3){
                  var e = j3.feed.entry && j3.feed.entry[0];
                  if(!e) return;
                  location.replace('/search?updated-max='+encodeURIComponent(e.published.$t)+'&max-results='+POSTS_PER_PAGE);
                });
            }
          });
        }).catch(function(){});

      function renderPager(current, pages){
        var html = '';
        if(current>1){
          var prev = current-1;
          html += '<a href="'+(prev===1?'/':'/?page='+prev)+'" title="Anterior">&lsaquo;</a>';
        }
        var range = [];
        for(var i=1;i<=pages;i++){
          if(i===1 || i===pages || Math.abs(i-current)<=2) range.push(i);
        }
        var last = 0;
        range.forEach(function(n){
          if(last && n-last>1) html += '<span class="dots">…</span>';
          if(n===current) html += '<span class="current">'+n+'</span>';
          else if(n===1) html += '<a href="/">'+n+'</a>';
          else html += '<a href="/?page='+n+'">'+n+'</a>';
          last = n;
        });
        if(current<pages) html += '<a href="/?page='+(current+1)+'" title="Próxima">&rsaquo;</a>';
        wrap.innerHTML = html;

        /* Footer counter — acesso a posts mais antigos */
        var counter = document.getElementById('pager-counter');
        if(!counter){
          counter = document.createElement('div');
          counter.id = 'pager-counter';
          counter.className = 'pager-counter';
          pager.appendChild(counter);
        }
        var older = '';
        if(current<pages){
          older = '<a class="pc-older" href="/?page='+(current+1)+'"><i class="fa fa-clock-rotate-left"></i> Ver posts mais antigos</a>';
        }
        counter.innerHTML =
          '<span class="pc-label">Página <strong>'+current+'</strong> de <strong>'+pages+'</strong></span>' +
          older;
      }
    }

    /* --- 3) Sidebar widgets --- */
    var sidebar = document.getElementById('sidebar-wrapper') || document.querySelector('.sidebar');
    if(!sidebar) return;

    /* 3b) Popular of the week (custom via feed JSON) */
    var pw = document.createElement('div');
    pw.id = 'popular-week';
    pw.innerHTML =
      '<div class="pw-head"><span class="pw-ico"><i class="fa fa-fire"></i></span><h3>Mais lidos</h3></div>' +
      '<ul class="is-loading">' +
        '<li class="pw-empty">Carregando…</li>' +
      '</ul>';
    sidebar.insertBefore(pw, sidebar.firstChild);

    function loadFeed(){
      var url = '/feeds/posts/summary?alt=json&max-results=20&orderby=published';
      fetch(url).then(function(r){return r.json();}).then(function(j){
        var entries = (j.feed && j.feed.entry) || [];
        entries.sort(function(a,b){
          var ca = (a.thr$total && parseInt(a.thr$total.$t,10)) || 0;
          var cb = (b.thr$total && parseInt(b.thr$total.$t,10)) || 0;
          return cb - ca;
        });
        renderPW(entries);
      }).catch(function(){ renderPW([]); });
    }
    loadFeed();

    function renderPW(entries){
      var ul = pw.querySelector('ul');
      if(!entries.length){ ul.innerHTML = '<li class="pw-empty">Sem posts recentes.</li>'; return; }
      var html = '';
      entries.slice(0,6).forEach(function(e, idx){
        var link = '#';
        (e.link||[]).forEach(function(l){ if(l.rel==='alternate') link=l.href; });
        var title = (e.title && e.title.$t) || '';
        var thumb = (e.media$thumbnail && e.media$thumbnail.url) || '';
        if(!thumb && e.content){
          var m = (e.content.$t||'').match(/<img[^>]+src=["']([^"']+)/i);
          if(m) thumb = m[1];
        }
        if(!thumb) thumb = 'https://placehold.co/600x300/0c131e/ffffff?text=%20';
        thumb = thumb.replace(/\/s\d+(-c)?\//,'/s600/').replace('/default.jpg','/mqdefault.jpg');
        var cat = (e.category && e.category[0] && e.category[0].term) || '';
        var esc = title.replace(/&/g,'&amp;').replace(/"/g,'&quot;').replace(/</g,'&lt;');
        html += '<li>' +
          '<span class="pw-index">'+(idx+1)+'</span>' +
          '<a class="pw-card" href="'+link+'" title="'+esc+'" style="background-image:url('+thumb+')">' +
            (cat?'<span class="pw-cat">'+cat+'</span>':'') +
            '<span class="pw-title">'+esc+'</span>' +
          '</a>' +
        '</li>';
      });
      ul.innerHTML = html;
      ul.classList.remove('is-loading');
    }
  });
})();
