(function(){
  function sync(){
    var p=document.querySelector('#drk1.gsrecent1'); if(!p) return;
    var bgs=p.querySelectorAll('.bg_list li');
    bgs.forEach(function(li){
      var i=li.getAttribute('data-i');
      var card=p.querySelector('.interactive_item[data-i="'+i+'"] .interactive__item');
      if(card) card.style.setProperty('--cn-thumb', li.style.backgroundImage);
    });
  }
  var iv=setInterval(sync,400);
  setTimeout(function(){clearInterval(iv);setInterval(sync,1500);},20000);
  if(document.readyState==='loading') document.addEventListener('DOMContentLoaded',sync); else sync();
})();
