      function apply(){
        pos = Math.min(Math.max(0,pos), maxPos());
        track.style.transform = 'translate3d(-'+pos+'px,0,0)';
        prev.disabled = pos <= 1;
        next.disabled = pos >= maxPos() - 1;
      }
      prev.addEventListener('click', function(){ pos -= passo(); apply(); });
      next.addEventListener('click', function(){ pos += passo(); apply(); });
      window.addEventListener('resize', function(){ pos = 0; apply(); });
      setTimeout(apply, 60);
    };

    var s = document.createElement('script');
    s.src = feed;
    document.body.appendChild(s);
  }

  if(document.readyState === 'loading'){
    document.addEventListener('DOMContentLoaded', init);
  } else {
    init();
  }
})();
//

//
(function(){
  function areaPost(){
    return document.querySelector('.post-body.post-hentry') || document.querySelector('.post-body');
  }
  function init(){
    var pb = areaPost();
    if(!pb || document.getElementById('cn-rail')) return;

    var rail = document.createElement('div');
    rail.id = 'cn-rail';
    rail.innerHTML = '<div class="cn-rail-share"></div>'+
                     '<div class="cn-rail-font">'+
                       '<span class="cn-rail-cap">Aa</span>'+
                       '<input class="cn-rail-range" type="range" min="14" max="30" step="1" value="18" aria-label="Tamanho do texto"/>'+
                       '<span class="cn-rail-val">18</span>'+
                     '</div>';
    document.body.appendChild(rail);

    var share = document.querySelector('.social-share-container') || document.querySelector('.social-share-widget');
    if(share){ rail.querySelector('.cn-rail-share').appendChild(share); }

    var antigo = document.querySelector('.font-size-slider-container');
    if(antigo){ antigo.style.display = 'none'; }

    var r = rail.querySelector('.cn-rail-range');
    var v = rail.querySelector('.cn-rail-val');
    function aplicar(){
      var val = parseInt(r.value,10);
      pb.style.fontSize = val + 'px';
      v.textContent = val;
      var p = ((val - r.min) / (r.max - r.min)) * 100;
      r.style.setProperty('--cn-fill', p + '%');
      var o = document.getElementById('fontSizeSlider'); if(o){ o.value = val; }
      var c = document.getElementById('currentFontSize'); if(c){ c.textContent = val + 'px'; }
      try{ localStorage.setItem('cnFontSize', val); }catch(e){}
    }
    try{ var sv = localStorage.getItem('cnFontSize'); if(sv){ r.value = sv; } }catch(e){}
    r.addEventListener('input', aplicar);
    aplicar();

    var TOPO = 100; /* distancia do topo da janela enquanto acompanha a rolagem */
    function posicionar(){
      var rect = pb.getBoundingClientRect();
      var visivel = rect.bottom > 120 && rect.top < (window.innerHeight - 40);

      if(window.innerWidth <= 1100){
        /* mobile / tablet: barra flutuante centralizada no rodape */
        rail.classList.add('cn-rail-mobile');
        rail.classList.remove('cn-rail-dock');
        rail.style.left = '';
        rail.style.top = '';
        if(visivel){ rail.classList.add('cn-rail-on'); }
        else { rail.classList.remove('cn-rail-on'); }
        return;
      }

      rail.classList.remove('cn-rail-mobile');
      rail.classList.add('cn-rail-dock');

      var y = window.pageYOffset || document.documentElement.scrollTop || 0;
      var x = window.pageXOffset || document.documentElement.scrollLeft || 0;
      var larg = rail.offsetWidth || 56;
      var alt  = rail.offsetHeight || 260;

      /* limites do post-body em coordenadas do documento */
      var topoPost = rect.top + y;
      var fimPost  = topoPost + pb.offsetHeight;

      /* posicao desejada acompanhando a rolagem, travada dentro do post-body */
      var alvo = y + TOPO;
      var min  = topoPost;
      var max  = fimPost - alt;
      if(max < min) max = min;             /* post menor que o rail */
      if(alvo < min) alvo = min;           /* estaciona no inicio */
      if(alvo > max) alvo = max;           /* estaciona no fim e volta ao subir */
      rail.style.top = Math.round(alvo) + 'px';

      var esq = rect.left + x - larg - 22; /* fora da area do texto */
      if(esq < x + 10) esq = x + 10;
      rail.style.left = Math.round(esq) + 'px';

      if(visivel){ rail.classList.add('cn-rail-on'); }
      else { rail.classList.remove('cn-rail-on'); }
    }
    window.addEventListener('scroll', posicionar, {passive:true});
    window.addEventListener('resize', posicionar);
    posicionar();
    setTimeout(posicionar, 500);
    setTimeout(posicionar, 1500);
  }

  if(document.readyState === 'loading'){
    document.addEventListener('DOMContentLoaded', function(){ setTimeout(init, 400); });
  } else {
    setTimeout(init, 400);
  }
})();
