body.script:
//
(function(){
  var ICONS = {
    title:'fa-solid fa-clapperboard',
    date:'fa-regular fa-calendar-days',
    time:'fa-regular fa-clock',
    genre:'fa-solid fa-film',
    cast:'fa-solid fa-users',
    dir:'fa-solid fa-chair',
    dist:'fa-solid fa-building',
    rating:'fa-solid fa-shield-halved'
  };

  var SOCIAL = [
    {re:/facebook/i, ic:'fa-brands fa-facebook-f'},
    {re:/instagram/i, ic:'fa-brands fa-instagram'},
    {re:/(twitter|x\.com)/i, ic:'fa-brands fa-x-twitter'},
    {re:/threads/i, ic:'fa-brands fa-threads'},
    {re:/youtube/i, ic:'fa-brands fa-youtube'},
    {re:/tiktok/i, ic:'fa-brands fa-tiktok'},
    {re:/blogger/i, ic:'fa-brands fa-blogger-b'}
  ];

  function txt(el){ return el ? (el.textContent||'').replace(/\s+/g,' ').trim() : ''; }
  function esc(s){ return (s||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;'); }
  function pick(sel, root){ return (root||document).querySelector(sel); }
  function norm(s){ return (s||'').toUpperCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^A-Z ]/g,'').replace(/\s+/g,' ').trim(); }

  function getNota(body){
    var st = body.querySelectorAll('strike');
    for(var i=0;i<st.length;i++){
      var n = parseFloat(txt(st[i]).replace(',','.'));
      if(!isNaN(n) && n>0 && n<=5) return n;
    }
    return null;
  }
  function starsHTML(n){
    var v = Math.round((parseFloat(n)||0)*2)/2;   /* arredonda para 0,5 */
    var h='';
    for(var i=0;i<5;i++){
      if(v >= i+1)            h += '<span class="cn-full">\u2605</span>';
      else if(v === i+0.5)    h += '<span class="cn-half">\u2605</span>';
      else                    h += '<span class="cn-off">\u2605</span>';
    }
    return h;
  }
  /* frase que traduz a nota */
  function veredito(n){
    var v = Math.round((parseFloat(n)||0)*2)/2;
    switch(true){
      case (v === 0.5): return '!';
      case (v === 1):   return 'Deuzulive';
      case (v === 1.5): return 'Muito Paia';
      case (v === 2):   return 'Paia';
      case (v === 2.5): return 'Fraco';
      case (v === 3):   return 'Legalzin';
      case (v === 3.5): return 'Legal';
      case (v === 4):   return 'Massa';
      case (v === 4.5): return 'Muito Massa';
      case (v === 5):   return 'Phoda Bagarai!';
      default:          return 'Nota Inv\u00E1lida';
    }
  }

  /* ---------- anima o circulo da porcentagem + contador ---------- */
  function animarAnel(wrap, nota){
    var ring = wrap.querySelector('.cn-rh-ring');
    var val  = wrap.querySelector('.cn-rh-value');
    var pct  = wrap.querySelector('.cn-rh-pct');
    if(!ring) return;
    var alvo = Math.max(0, Math.min(100, (nota/5)*100));
    var dur  = 1400, ini = null, rodou = false;
    function passo(t){
      if(ini === null) ini = t;
      var p = Math.min(1, (t - ini) / dur);
      var e = 1 - Math.pow(1 - p, 3);                 /* easeOutCubic */
      var atual = alvo * e;
      ring.style.setProperty('--cn-p', atual.toFixed(2));
      if(val) val.textContent = ((Math.round((nota*e)*10)/10).toFixed(1)).replace('.', ',');
      if(pct) pct.textContent = Math.round(atual) + '%';
      if(p < 1) requestAnimationFrame(passo);
      else {
        ring.style.setProperty('--cn-p', alvo);
        if(val) val.textContent = (Math.round(nota*10)/10).toFixed(1).replace('.', ',');
        if(pct) pct.textContent = Math.round(alvo) + '%';
        ring.classList.add('cn-ring-done');
      }
    }
    function start(){
      if(rodou) return; rodou = true;
      ring.classList.add('cn-ring-live');
      requestAnimationFrame(passo);
    }
    if('IntersectionObserver' in window){
      var io = new IntersectionObserver(function(en){
        en.forEach(function(x){ if(x.isIntersecting){ start(); io.disconnect(); } });
      }, {threshold:.35});
      io.observe(ring);
    } else { start(); }
  }

  /* ---------- notas comparativas (IMDb / Metacritic / Rotten Tomatoes) ---------- */
  /* OMDb (https://www.omdbapi.com) - chave gratuita em omdbapi.com/apikey.aspx
     Cole a chave abaixo OU defina window.OMDB_KEY antes deste script. */
  var OMDB_KEY = (window.OMDB_KEY || '1661c898').trim();
  var TMDB_KEY_RH = '0344712bb861098caefcc9a8d67beb09';

  function notasNoTexto(body){
    var t = (body.textContent || '').replace(/\s+/g,' ');
    function achar(re){ var m = t.match(re); return m ? m[1].replace(',', '.') : null; }
    return {
      imdb: achar(/IMD\s*B?[:\s\-]*([0-9]{1,2}(?:[.,][0-9])?)\s*(?:\/\s*10)?/i),
      meta: achar(/Metacritic[:\s\-]*([0-9]{1,3})/i),
      rt:   achar(/(?:Rotten\s*Tomatoes|Tomatometer)[:\s\-]*([0-9]{1,3})\s*%?/i)
    };
  }
  var MINI_ICO = {
    'is-imdb':'<i class="fa-brands fa-imdb"></i>',
    'is-rt'  :'<span class="cn-mini-emo" aria-hidden="true">\uD83C\uDF45</span>',
    'is-meta':'<span class="cn-mini-mc" aria-hidden="true">M</span>'
  };
  function miniCard(nome, valor, sufixo, cls, url){
    var v = (valor === null || valor === undefined || valor === '') ? '\u2013' : valor + (sufixo||'');
    var inner = '<span class="cn-mini-ico" aria-hidden="true">'+(MINI_ICO[cls]||'')+'</span>'+
                '<span class="cn-mini-src">'+nome+'</span>'+
                '<span class="cn-mini-val">'+v+'</span>';
    return url ? '<a class="cn-mini '+cls+'" href="'+url+'" target="_blank" rel="noopener" title="'+nome+'" aria-label="'+nome+' '+v+'">'+inner+'</a>'
               : '<div class="cn-mini '+cls+'" title="'+nome+'" aria-label="'+nome+' '+v+'">'+inner+'</div>';
  }
  function blocoComparativo(n){
    return '<div class="cn-rh-mini" aria-label="Notas comparativas">'+
      '<span class="cn-rh-mini-cap">Comparativo</span>'+
      '<div class="cn-rh-mini-grid">'+
        miniCard('IMDb', n.imdb, '', 'is-imdb', n.imdbUrl)+
        miniCard('Rotten Tomatoes', n.rt, '%', 'is-rt', null)+
        miniCard('Metacritic', n.meta, '', 'is-meta', null)+
      '</div></div>';
  }

  function preencherComparativo(wrap, titulo, ano, base){
    var alvo = wrap.querySelector('.cn-rh-mini');
    if(!alvo) return;
    function pintar(n){
      alvo.outerHTML = blocoComparativo(n);
    }
    if(!titulo){ pintar(base); return; }
    var u = 'https://api.themoviedb.org/3/search/multi?api_key='+TMDB_KEY_RH+
            '&language=pt-BR&include_adult=false&query='+encodeURIComponent(titulo);
    fetch(u).then(function(r){ return r.json(); }).then(function(d){
      var it = (d.results||[]).filter(function(x){ return x.media_type!=='person'; })[0];
      if(!it){ pintar(base); return; }
      var tipo = it.media_type === 'tv' ? 'tv' : 'movie';
      return fetch('https://api.themoviedb.org/3/'+tipo+'/'+it.id+'/external_ids?api_key='+TMDB_KEY_RH)
        .then(function(r){ return r.json(); })
        .then(function(ex){
          var imdbId = ex && ex.imdb_id;
          base.imdbUrl = imdbId ? 'https://www.imdb.com/title/'+imdbId+'/' : null;
          if(!OMDB_KEY || !imdbId){
            if(base.imdb == null && it.vote_average) base.imdb = (Math.round(it.vote_average*10)/10).toFixed(1);
            pintar(base); return;
          }
          return fetch('https://www.omdbapi.com/?apikey='+OMDB_KEY+'&i='+imdbId)
            .then(function(r){ return r.json(); })
            .then(function(o){
              (o.Ratings||[]).forEach(function(r){
                if(/Internet Movie Database/i.test(r.Source)) base.imdb = r.Value.split('/')[0];
                if(/Metacritic/i.test(r.Source))              base.meta = r.Value.split('/')[0];
                if(/Rotten Tomatoes/i.test(r.Source))         base.rt   = r.Value.replace('%','');
              });
              if(base.meta == null && o.Metascore && o.Metascore !== 'N/A') base.meta = o.Metascore;
              if(base.imdb == null && o.imdbRating && o.imdbRating !== 'N/A') base.imdb = o.imdbRating;
              pintar(base);
            });
        });
    }).catch(function(){ pintar(base); });
  }

  /* ---- autor SEMPRE o marcado no final do post ---- */
  function markedNames(body){
    var names=[];
    body.querySelectorAll('u,b strong,strong u').forEach(function(u){
      var t=txt(u);
      if(t && t.split(/\s+/).length<=5 && /[A-Za-z]/.test(t)) names.push(t);
    });
    return names;
  }
  function findAuthorSource(body){
    var names = markedNames(body);
    var blocks = document.querySelectorAll('div[id$="Profile"]');
    for(var j=0;j<blocks.length;j++){
      var nm = norm(txt(pick('.authorDetails h4', blocks[j])));
      if(!nm) continue;
      for(var k=0;k<names.length;k++){
        if(norm(names[k]) === nm || norm(names[k]).indexOf(nm)>-1 || nm.indexOf(norm(names[k]))>-1) return blocks[j];
      }
    }
    for(var i=0;i<blocks.length;i++){ if(blocks[i].style.display==='block') return blocks[i]; }
    return null;
  }
  function readAuthor(block, body){
    var names = markedNames(body);
    var fallbackName = names.length ? names[names.length-1] : '';
    if(!block) return fallbackName ? {name:fallbackName,url:'',avatar:'',bio:'',socials:[]} : null;
    var img = pick('.authorAvatar img', block);
    var link = pick('.authorDetails h4 a', block);
    var socials = [];
    block.querySelectorAll('.authorSocial a').forEach(function(a){
      var href = a.getAttribute('href')||'';
      var ic = 'fa-solid fa-link';
      for(var i=0;i<SOCIAL.length;i++){ if(SOCIAL[i].re.test(href) || SOCIAL[i].re.test(a.getAttribute('title')||'')){ ic=SOCIAL[i].ic; break; } }
      socials.push({href:href, ic:ic, title:a.getAttribute('title')||'Perfil'});
    });
    return {
      name: txt(pick('.authorDetails h4', block)) || fallbackName,
      url: link ? link.getAttribute('href') : '',
      avatar: img ? img.getAttribute('src') : '',
      bio: txt(pick('.authorDetails [itemprop="description"]', block)),
      socials: socials
    };
  }

  function fichaData(){
    return {
      title: txt(pick('#movie-title')),
      release: txt(pick('#movie-release-date')),
      genres: txt(pick('#movie-genres')),
      cast: txt(pick('#movie-cast')),
      director: txt(pick('#movie-director')),
      distributor: txt(pick('#movie-distributor, #movie-studio, #movie-production')),
      certification: txt(pick('#movie-rating, #movie-certification, #movie-age-rating')),
      poster: (pick('#movie-poster')||{}).src || ''
    };
  }

  function postTitle(){ return txt(pick('.post-artikel h1.post-title, h1.post-title, .post-title')); }
  function duration(body){
    var m = (body.textContent||'').match(/(\d{1,2})\s*h\s*(\d{1,2})\s*m(?:in)?/i);
    if(m) return m[1]+'h '+m[2]+'m';
    var m2 = (body.textContent||'').match(/(\d{2,3})\s*min/i);
    return m2 ? m2[1]+' min' : '';
  }
  function tagline(body){
    var cand = body.querySelectorAll('em,i');
    for(var i=0;i<cand.length;i++){ var t=txt(cand[i]); if(t.length>12 && t.length<110) return t; }
    return '';
  }
  function quote(body){
    var t = txt(pick('blockquote', body));
    if(!t){
      var ps = body.querySelectorAll('p');
      for(var i=0;i<ps.length;i++){ var p=txt(ps[i]); if(p.length>80){ t=p; break; } }
    }
    if(t.length>210) t = t.slice(0,207).replace(/\s\S*$/,'')+'\u2026';
    return t;
  }
  function artwork(body, f){
    var im = body.querySelector('img');
    return (im && im.src) || f.poster || '';
  }
  function item(icon,k,v,campo){
    if(!v && !campo) return '';
    return '<div class="cn-rh-item"'+(campo?' data-campo="'+campo+'"':'')+'><span class="cn-rh-ico"><i class="'+icon+'"></i></span>'+
           '<span class="cn-rh-txt"><span class="cn-rh-k">'+esc(k)+'</span><span class="cn-rh-v">'+esc(v||'\u2013')+'</span></span></div>';
  }

  /* completa distribuicao e classificacao indicativa pelo TMDB */
  function completarFicha(wrap, titulo){
    var alvos = wrap.querySelectorAll('.cn-rh-item[data-campo]');
    if(!alvos.length || !titulo) return;
    function set(campo, valor){
      wrap.querySelectorAll('.cn-rh-item[data-campo="'+campo+'"]').forEach(function(el){
        var v = el.querySelector('.cn-rh-v');
        if(valor){ if(v) v.textContent = valor; }
        else if(el.parentNode){ el.parentNode.removeChild(el); }
      });
    }
    var u = 'https://api.themoviedb.org/3/search/multi?api_key='+TMDB_KEY_RH+
            '&language=pt-BR&include_adult=false&query='+encodeURIComponent(titulo);
    fetch(u).then(function(r){ return r.json(); }).then(function(d){
      var it = (d.results||[]).filter(function(x){ return x.media_type!=='person'; })[0];
      if(!it) throw 0;
      var tipo = it.media_type === 'tv' ? 'tv' : 'movie';
      wrap.setAttribute('data-cn-obra-tipo', tipo);
      wrap.setAttribute('data-cn-obra-id', it.id);
      var extra = tipo === 'tv' ? 'content_ratings' : 'release_dates';
      return fetch('https://api.themoviedb.org/3/'+tipo+'/'+it.id+'?api_key='+TMDB_KEY_RH+'&language=pt-BR&append_to_response='+extra)
        .then(function(r){ return r.json(); })
        .then(function(o){
          var dist = (o.production_companies||[]).map(function(c){ return c.name; }).slice(0,3).join(', ');
          var cert = '';
          if(tipo === 'tv'){
            ((o.content_ratings&&o.content_ratings.results)||[]).forEach(function(c){
              if(c.iso_3166_1 === 'BR' && c.rating) cert = c.rating;
            });
          } else {
            ((o.release_dates&&o.release_dates.results)||[]).forEach(function(c){
              if(c.iso_3166_1 !== 'BR') return;
              (c.release_dates||[]).forEach(function(r){ if(!cert && r.certification) cert = r.certification; });
            });
          }
          if(cert){ cert = /^(L|Livre)$/i.test(cert) ? 'Livre' : (/^\d+$/.test(cert) ? cert+' anos' : cert); }
          set('dist', dist);
          set('rating', cert);
        });
    }).catch(function(){ set('dist',''); set('rating',''); });
  }

  function build(body, nota){
    if(document.querySelector('.cn-rh')) return;
    var f = fichaData();
    var a = readAuthor(findAuthorSource(body), body);
    var title = f.title || postTitle();
    var art = artwork(body, f);
    var q = quote(body);
    var dur = duration(body);

    var wrap = document.createElement('section');
    wrap.className = 'cn-rh';
    wrap.setAttribute('aria-label','Nota do critico, ficha tecnica e autor');
    wrap.style.setProperty('--cn-p', 0);

    /* ficha: titulo, lancamento, genero, elenco, diretor, distribuicao, classificacao */
    var linhas = [
      item(ICONS.title,'Titulo', title),
      item(ICONS.date,'Lancamento', f.release),
      item(ICONS.genre,'Genero', f.genres),
      item(ICONS.cast,'Elenco', f.cast),
      item(ICONS.dir,'Diretor', f.director),
      item(ICONS.dist,'Distribuicao', f.distributor, 'dist'),
      item(ICONS.rating,'Classificacao', f.certification, 'rating')
    ].filter(Boolean).join('');
    var fichaItens = [
      item(ICONS.title,'Titulo', title),
      item(ICONS.date,'Lancamento', f.release),
      item(ICONS.genre,'Genero', f.genres),
      item(ICONS.rating,'Classificacao', f.certification, 'rating'),
      item(ICONS.dir,'Diretor', f.director),
      item(ICONS.dist,'Distribuicao', f.distributor, 'dist'),
      item(ICONS.cast,'Elenco', f.cast)
    ].filter(Boolean);
    var meio = Math.ceil(fichaItens.length/2);
    var colA = fichaItens.slice(0, meio).join('');
    var colB = fichaItens.slice(meio).join('');
    var rows = fichaItens.length
      ? '<div class="cn-rh-col"><div class="cn-rh-row is-full">'+colA+'</div></div>'+
        (colB ? '<div class="cn-rh-col"><div class="cn-rh-row is-full">'+colB+'</div></div>' : '')
      : '';

    var html = (art ? '<div class="cn-rh-art" style="background-image:url('+esc(art)+')"></div>' : '')+
    '<div class="cn-rh-inner">'+
      '<div class="cn-rh-score">'+

        '<div class="cn-rh-ring"><div class="cn-rh-ring-in">'+
          '<span class="cn-rh-value">0,0</span>'+
          '<span class="cn-rh-of">de 5</span>'+
          '<span class="cn-rh-pct">0%</span>'+
        '</div></div>'+
        '<div class="cn-rh-stars" data-nota="'+(parseFloat(nota)||0)+'">'+starsHTML(nota)+'</div>'+
        '<p class="cn-rh-verdict">'+esc(veredito(nota))+'</p>'+
        blocoComparativo(notasNoTexto(body))+
        (q ? '<div class="cn-rh-quote"><span>'+esc(q)+'</span></div>' : '')+
      '</div>'+
      '<div class="cn-rh-main">'+
        '<div class="cn-rh-head">'+
          '<h2 class="cn-rh-title">'+esc(title)+'</h2>'+
          '<div class="cn-rh-rule"></div>'+
          (tagline(body) ? '<p class="cn-rh-tagline">'+esc(tagline(body))+'</p>' : '')+
        '</div>'+
        (rows ? '<div class="cn-rh-sheet">'+rows+'</div>' : '')+
        '<a class="cn-rh-cta" href="#ficha">Mais informacoes <i class="fa-solid fa-chevron-right"></i></a>'+
      '</div>'+
    '</div>';

    if(a && a.name){
      html += '<div class="cn-rh-author">'+
        '<div class="cn-rh-au-id">'+
          (a.avatar ? '<span class="cn-rh-au-pic"><img alt="'+esc(a.name)+'" src="'+esc(a.avatar)+'" loading="lazy"/></span>' : '')+
          '<div class="cn-rh-au-name">'+
            (a.url ? '<a href="'+esc(a.url)+'"><strong>'+esc(a.name)+'</strong></a>' : '<strong>'+esc(a.name)+'</strong>')+
            (a.bio ? '<p class="cn-rh-au-bio">'+esc(a.bio)+'</p>' : '')+
          '</div>'+
        '</div>'+
        (a.socials.length ? '<div class="cn-rh-au-social"><b>Siga o critico</b><div>'+a.socials.map(function(s){
            return '<a href="'+esc(s.href)+'" target="_blank" rel="noopener" title="'+esc(s.title)+'" aria-label="'+esc(s.title)+'"><i class="'+s.ic+'"></i></a>';
          }).join('')+'</div></div>' : '')+
      '</div>';
    }

    wrap.innerHTML = html;
    wrap.style.setProperty('--cn-p', 0);
    body.parentNode.insertBefore(wrap, body.nextSibling);
    document.documentElement.classList.add('cn-rh-on');
    purgeLegacy();
    animarAnel(wrap, nota);
    preencherComparativo(wrap, title, '', notasNoTexto(body));
    completarFicha(wrap, title);


    wrap.querySelector('.cn-rh-cta').addEventListener('click', function(ev){
      ev.preventDefault();
      var id = wrap.getAttribute('data-cn-obra-id');
      var tipo = wrap.getAttribute('data-cn-obra-tipo') || 'movie';
      if(id && window.CN && typeof window.CN.obra === 'function'){
        window.CN.obra(tipo, id);
        return;
      }
      if(window.CN && typeof window.CN.obra === 'function' && title){
        fetch('https://api.themoviedb.org/3/search/multi?api_key='+TMDB_KEY_RH+'&language=pt-BR&include_adult=false&query='+encodeURIComponent(title))
          .then(function(r){ return r.json(); })
          .then(function(d){
            var it = (d.results||[]).filter(function(x){ return x.media_type!=='person'; })[0];
            if(!it) throw 0;
            wrap.setAttribute('data-cn-obra-tipo', it.media_type==='tv'?'tv':'movie');
            wrap.setAttribute('data-cn-obra-id', it.id);
            window.CN.obra(it.media_type==='tv'?'tv':'movie', it.id);
          })
          .catch(function(){
            var sh = wrap.querySelector('.cn-rh-sheet');
            if(sh) sh.scrollIntoView({behavior:'smooth',block:'center'});
          });
        return;
      }
      var sh = wrap.querySelector('.cn-rh-sheet');
      if(sh) sh.scrollIntoView({behavior:'smooth',block:'center'});
    });
  }

  /* ---- apaga de vez os blocos antigos duplicados ---- */
  function purgeLegacy(){
    var sels = ['#nota','#movie-details-section','.nota-exibida-container','.cn-author-card',
                '.trend-news-author-box','.author-box','.post-author-box','div[id$="Profile"]'];
    sels.forEach(function(s){
      document.querySelectorAll(s).forEach(function(el){
        if(el.closest && el.closest('.cn-rh')) return;
        if(el.parentNode) el.parentNode.removeChild(el);
      });
    });
  }

  function overrideByline(body){
    var a = readAuthor(findAuthorSource(body), body);
    if(!a || !a.name) return;
    document.querySelectorAll('.post-author, .post-author a, span.post-author .fn, .byline.post-author .fn, .postmeta .post-author').forEach(function(el){
      if(el.querySelector && el.querySelector('a')) return;
      var t = txt(el);
      if(!t) return;
      el.textContent = /^(por|by)\b/i.test(t) ? t.replace(/(por|by)\s+.*/i,'$1 '+a.name) : a.name;
    });
    document.querySelectorAll('a[rel="author"]').forEach(function(el){
      el.textContent = a.name;
      if(a.url) el.setAttribute('href', a.url);
    });
    var meta = document.querySelector('meta[name="author"]');
    if(meta) meta.setAttribute('content', a.name);
  }

  function init(){
    var body = document.querySelector('.post-body');
    if(!body) return;
    var nota = getNota(body);
    overrideByline(body);
    if(nota === null) return;
    var tries = 0;
    (function attempt(){
      tries++;
      var f = fichaData();
      if(f.title || f.release || f.cast || tries > 12){ build(body, nota); overrideByline(body); setTimeout(purgeLegacy, 1200); }
      else setTimeout(attempt, 700);
    })();
  }

  if(document.readyState === 'loading'){
    document.addEventListener('DOMContentLoaded', function(){ setTimeout(init, 500); });
  } else { setTimeout(init, 500); }
})();
