/* ============================================================
   OMDb API  -  baseado em https://github.com/aharen/OMDbAPI
   Documentacao: https://www.omdbapi.com/
   IMPORTANTE: troque SUA_CHAVE_OMDB pela sua chave gratuita
   obtida em https://www.omdbapi.com/apikey.aspx
   ============================================================ */
(function(){
  var OMDB_KEY  = '1661c898';
  var OMDB_BASE = 'https://www.omdbapi.com/';
  var CACHE_MS  = 6 * 60 * 60 * 1000; // 6h

  function esc(s){return (s||'').replace(/[&<>"']/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c];});}

  function cacheGet(k){
    try{var raw=localStorage.getItem('cn_omdb_'+k); if(!raw) return null;
      var o=JSON.parse(raw); if(Date.now()-o.t>CACHE_MS) return null; return o.d;}catch(e){return null;}
  }
  function cacheSet(k,d){ try{localStorage.setItem('cn_omdb_'+k,JSON.stringify({t:Date.now(),d:d}));}catch(e){} }

  // Consulta por titulo (t=) ou por IMDb id (i=)
  function omdb(params){
    var key='';
    for(var p in params){ key+=p+'='+params[p]+'&'; }
    var cached=cacheGet(key);
    if(cached) return Promise.resolve(cached);
    var url=OMDB_BASE+'?apikey='+encodeURIComponent(OMDB_KEY)+'&plot=short&r=json';
    for(var q in params){ url+='&'+q+'='+encodeURIComponent(params[q]); }
    return fetch(url).then(function(r){return r.json();}).then(function(j){
      if(!j || j.Response==='False') return null;
      cacheSet(key,j); return j;
    }).catch(function(){return null;});
  }

  function rating(data,name){
    if(!data.Ratings) return null;
    for(var i=0;i<data.Ratings.length;i++){ if(data.Ratings[i].Source===name) return data.Ratings[i].Value; }
    return null;
  }

  function card(d){
    var poster=(d.Poster && d.Poster!=='N/A')?d.Poster:'https://placehold.co/300x444/060d17/ffffff?text=Sem+Poster';
    var rt=rating(d,'Rotten Tomatoes'), mc=rating(d,'Metacritic');
    var scores='';
    if(d.imdbRating && d.imdbRating!=='N/A') scores+='<span class="cn-omdb-score"><b>IMDb</b> '+esc(d.imdbRating)+'/10</span>';
    if(rt) scores+='<span class="cn-omdb-score rt"><b>Tomatometer</b> '+esc(rt)+'</span>';
    if(mc) scores+='<span class="cn-omdb-score mc"><b>Metacritic</b> '+esc(mc)+'</span>';
    var meta='';
    if(d.Genre && d.Genre!=='N/A')    meta+='<div><b>G&ecirc;nero:</b> '+esc(d.Genre)+'</div>';
    if(d.Director && d.Director!=='N/A') meta+='<div><b>Dire&ccedil;&atilde;o:</b> '+esc(d.Director)+'</div>';
    if(d.Actors && d.Actors!=='N/A')  meta+='<div><b>Elenco:</b> '+esc(d.Actors)+'</div>';
    if(d.Released && d.Released!=='N/A') meta+='<div><b>Lan&ccedil;amento:</b> '+esc(d.Released)+'</div>';
    if(d.Runtime && d.Runtime!=='N/A')  meta+='<div><b>Dura&ccedil;&atilde;o:</b> '+esc(d.Runtime)+'</div>';
    return '<div class="cn-omdb">'+
      '<div class="cn-omdb-in">'+
        '<img class="cn-omdb-poster" alt="'+esc(d.Title)+'" src="'+esc(poster)+'" loading="lazy"/>'+
        '<div>'+
          '<h3 class="cn-omdb-title">'+esc(d.Title)+' <span class="cn-omdb-sub">('+esc(d.Year)+')</span></h3>'+
          '<div class="cn-omdb-sub">'+esc([d.Rated,d.Type,d.Country].filter(function(x){return x&&x!=='N/A';}).join(' &bull; '))+'</div>'+
          '<div class="cn-omdb-scores">'+scores+'</div>'+
          (d.Plot&&d.Plot!=='N/A'?'<p class="cn-omdb-plot">'+esc(d.Plot)+'</p>':'')+
          '<div class="cn-omdb-meta">'+meta+'</div>'+
        '</div>'+
      '</div>'+
      '<div class="cn-omdb-foot"><span>Ficha t&eacute;cnica</span>'+
        '<a href="https://www.imdb.com/title/'+esc(d.imdbID)+'/" target="_blank" rel="nofollow noopener">Ver no IMDb &#8250;</a>'+
      '</div>'+
    '</div>';
  }

  // 1) Blocos manuais:  <div class="cn-omdb-box" data-title="Duna" data-year="2021"></div>
  //    ou por id:       <div class="cn-omdb-box" data-imdb="tt1160419"></div>
  function renderBoxes(){
    var boxes=document.querySelectorAll('.cn-omdb-box:not([data-cn-done])');
    Array.prototype.forEach.call(boxes,function(box){
      box.setAttribute('data-cn-done','1');
      var p={};
      if(box.getAttribute('data-imdb')) p.i=box.getAttribute('data-imdb');
      else { p.t=box.getAttribute('data-title')||''; if(box.getAttribute('data-year')) p.y=box.getAttribute('data-year'); }
      if(!p.i && !p.t) return;
      omdb(p).then(function(d){ if(d) box.innerHTML=card(d); else box.style.display='none'; });
    });
  }

  // 2) Selo automatico de nota IMDb no titulo do post (opcional)
  //    Ative colocando <span class="cn-omdb-auto" data-title="Nome do Filme"></span> no post.
  function renderBadges(){
    var els=document.querySelectorAll('.cn-omdb-auto:not([data-cn-done])');
    Array.prototype.forEach.call(els,function(el){
      el.setAttribute('data-cn-done','1');
      var t=el.getAttribute('data-title'); if(!t) return;
      omdb({t:t}).then(function(d){
        if(d && d.imdbRating && d.imdbRating!=='N/A'){
          el.innerHTML='<span class="cn-omdb-badge">&#9733; IMDb '+esc(d.imdbRating)+'</span>';
        }
      });
    });
  }

  function boot(){ renderBoxes(); renderBadges(); }
  if(document.readyState!=='loading') boot();
  else document.addEventListener('DOMContentLoaded',boot);
  // conteudo carregado por AJAX (slides, modais, related)
  new MutationObserver(function(){ boot(); }).observe(document.documentElement,{childList:true,subtree:true});
})();
