(function(){
  'use strict';

  var FEED_MAX = 150;
  var mapaAutores = null;      /* url do post -> autor */
  var feedPromise = null;

  function txt(el){ return el ? (el.textContent || '').replace(/\s+/g,' ').trim() : ''; }
  function norm(s){ return (s||'').toLowerCase().replace(/\s+/g,' ').trim(); }

  /* ---------- perfis cadastrados no template (div[id$="Profile"]) ---------- */
  function perfis(){
    var out = [];
    document.querySelectorAll('div[id$="Profile"]').forEach(function(b){
      var h4 = b.querySelector('.authorDetails h4');
      var nome = txt(h4);
      if(!nome) return;
      var link = b.querySelector('.authorDetails h4 a');
      var img  = b.querySelector('.authorAvatar img');
      out.push({
        name: nome,
        url: link ? link.getAttribute('href') : '',
        avatar: img ? img.getAttribute('src') : '',
        bio: txt(b.querySelector('.authorDetails [itemprop="description"]'))
      });
    });
    return out;
  }

  /* ---------- nomes marcados no corpo do post (negrito / sublinhado) ---------- */
  function nomesMarcados(root){
    var nomes = [];
    root.querySelectorAll('u, b strong, strong u, b u, strong, b').forEach(function(el){
      var t = txt(el);
      if(t && t.split(/\s+/).length <= 5 && /[A-Za-zÀ-ÿ]/.test(t)) nomes.push(t);
    });
    return nomes;
  }

  /* ---------- resolve o autor a partir de um conteudo (DOM ou HTML) ---------- */
  function autorDoConteudo(root){
    if(!root) return null;

    /* 1) bloco cn-rh-author ja renderizado */
    var card = root.querySelector ? root.querySelector('.cn-rh-author') : null;
    if(!card) card = document.querySelector('.cn-rh .cn-rh-author');
    if(card){
      var nm = txt(card.querySelector('.cn-rh-au-name strong')) || txt(card.querySelector('.cn-rh-au-name'));
      if(nm){
        var lk = card.querySelector('.cn-rh-au-name a');
        var im = card.querySelector('.cn-rh-au-pic img');
        return {
          name: nm,
          url: lk ? lk.getAttribute('href') : '',
          avatar: im ? im.getAttribute('src') : '',
          bio: txt(card.querySelector('.cn-rh-au-bio'))
        };
      }
    }

    /* 2) marcacao explicita no post */
    var flag = root.querySelector ? root.querySelector('[data-cn-author]') : null;
    if(flag){
      var fn = flag.getAttribute('data-cn-author') || txt(flag);
      if(fn) return casarPerfil(fn) || {name:fn, url:'', avatar:'', bio:''};
    }

    /* 3) nome citado no texto casado com um perfil do template */
    var lista = perfis();
    var nomes = nomesMarcados(root);
    for(var i=0;i<nomes.length;i++){
      var p = casarPerfil(nomes[i], lista);
      if(p) return p;
    }
    return null;
  }

  function casarPerfil(nome, lista){
    lista = lista || perfis();
    var n = norm(nome);
    if(!n) return null;
    for(var i=0;i<lista.length;i++){
      var pn = norm(lista[i].name);
      if(pn && (pn === n || pn.indexOf(n) > -1 || n.indexOf(pn) > -1)) return lista[i];
    }
    return null;
  }

  /* ---------- aplica o autor no post aberto ---------- */
  function aplicarNoPost(a){
    if(!a || !a.name) return;

    document.querySelectorAll(
      '.post-author, span.post-author .fn, .postmeta .post-author, .post-artikel .postmeta .post-author, #post-title-container .post-author'
    ).forEach(function(el){
      var link = el.querySelector && el.querySelector('a');
      var alvo = link || el;
      var t = txt(alvo);
      alvo.textContent = /^(por|by)\b/i.test(t) ? t.replace(/^(por|by)\s+.*/i, '$1 ' + a.name) : a.name;
      if(link && a.url) link.setAttribute('href', a.url);
    });

    document.querySelectorAll('a[rel="author"], .g-profile').forEach(function(el){
      if(el.closest && el.closest('.cn-rh-author')) return;
      el.textContent = a.name;
      if(a.url) el.setAttribute('href', a.url);
    });

    document.querySelectorAll('[itemprop="author"] [itemprop="name"], [itemprop="author"][itemprop~="name"]').forEach(function(el){
      if(el.closest && el.closest('.cn-rh-author')) return;
      el.textContent = a.name;
    });

    document.querySelectorAll('[itemprop="author"] meta[itemprop="url"]').forEach(function(el){
      if(a.url) el.setAttribute('content', a.url);
    });

    if(a.avatar){
      document.querySelectorAll('.post-author-avatar img, .author-avatar img, .authorAvatar img').forEach(function(img){
        if(img.closest && img.closest('.cn-rh-author')) return;
        img.setAttribute('src', a.avatar);
        img.setAttribute('alt', a.name);
      });
    }

    var meta = document.querySelector('meta[name="author"]');
    if(meta) meta.setAttribute('content', a.name);

    /* JSON-LD do post */
    document.querySelectorAll('script[type="application/ld+json"]').forEach(function(s){
      try{
        var d = JSON.parse(s.textContent);
        if(d && d.author){
          if(Array.isArray(d.author)) d.author = d.author.map(function(x){ x.name = a.name; if(a.url) x.url = a.url; return x; });
          else { d.author.name = a.name; if(a.url) d.author.url = a.url; }
          s.textContent = JSON.stringify(d);
        }
      }catch(e){}
    });

    document.documentElement.setAttribute('data-cn-post-author', a.name);
  }

  /* ---------- feed: autor de cada post pelo conteudo (listagens) ---------- */
  function carregarFeed(){
    if(feedPromise) return feedPromise;
    feedPromise = fetch('/feeds/posts/default?alt=json&max-results=' + FEED_MAX)
      .then(function(r){ return r.json(); })
      .then(function(j){
        mapaAutores = {};
        var entradas = (j && j.feed && j.feed.entry) || [];
        entradas.forEach(function(e){
          var url = '';
          (e.link || []).forEach(function(l){ if(l.rel === 'alternate') url = l.href; });
          if(!url) return;
          var html = (e.content && e.content.$t) || (e.summary && e.summary.$t) || '';
          var box = document.createElement('div');
          box.innerHTML = html;
          var a = autorDoConteudo(box);
          if(a && a.name) mapaAutores[chave(url)] = a;
        });
        return mapaAutores;
      })
      .catch(function(){ mapaAutores = {}; return mapaAutores; });
    return feedPromise;
  }

  function chave(url){
    try{ var u = new URL(url, location.origin); return u.pathname.replace(/\/+$/,''); }
    catch(e){ return (url||'').replace(/^https?:\/\/[^/]+/,'').replace(/\/+$/,''); }
  }

  var SEL_AUTOR = '.recentbtm-author, .recent-author, .rlist-author, .rlist2-author, .featured-author, .post-author, .carousel-meta .recent-author, .postmeta .post-author';

  function aplicarNasListas(){
    if(!mapaAutores) return;
    document.querySelectorAll(SEL_AUTOR).forEach(function(el){
      if(el.getAttribute('data-cn-au') === '1') return;
      if(el.closest && el.closest('.cn-rh-author')) return;
      var box = el.closest('li, .gs-item, .carousel-item, .post-panel, article, .post, .featured-inner, .index-post');
      if(!box) return;
      var link = box.querySelector('a[href*="/20"], h2 a, h3 a, .rcp-title a, .recent-title a, .post-title a');
      if(!link) return;
      var a = mapaAutores[chave(link.getAttribute('href') || '')];
      if(!a || !a.name) return;
      el.textContent = a.name;
      el.setAttribute('data-cn-au', '1');
    });
  }

  /* ---------- inicializacao ---------- */
  function initPost(){
    var body = document.querySelector('.post-body');
    if(!body) return false;
    var a = autorDoConteudo(body);
    if(a && a.name){ aplicarNoPost(a); return true; }
    return false;
  }

  function start(){
    var single = !!document.querySelector('.post-body');
    if(single){
      var tentativas = 0;
      (function tenta(){
        tentativas++;
        if(!initPost() && tentativas < 15) setTimeout(tenta, 600);
        else setTimeout(initPost, 1500);
      })();
    }

    carregarFeed().then(function(){
      aplicarNasListas();
      var obs = new MutationObserver(function(){ aplicarNasListas(); });
      obs.observe(document.body, {childList:true, subtree:true});
      setTimeout(aplicarNasListas, 1500);
      setTimeout(aplicarNasListas, 4000);
    });
  }

  if(document.readyState === 'loading'){
    document.addEventListener('DOMContentLoaded', function(){ setTimeout(start, 400); });
  } else { setTimeout(start, 400); }
})();
