(function(){
  'use strict';

  var STAR = '\u2605\u2605\u2605\u2605\u2605';

  function txt(el){ return el ? (el.textContent || '').replace(/\s+/g,' ').trim() : ''; }
  function pct(nota){ return Math.max(0, Math.min(100, (nota/5)*100)); }

  /* ================= 1) remove quote + rule ================= */
  function limparBlocos(){
    document.querySelectorAll('.cn-rh-quote, .cn-rh-rule').forEach(function(el){
      if(el.parentNode) el.parentNode.removeChild(el);
    });
  }

  /* ================= 5) estrelas por porcentagem ================= */
  function starsEl(nota, tamanho){
    var w = document.createElement('span');
    w.className = 'cn-stars5';
    w.setAttribute('data-nota', String(nota));
    w.setAttribute('aria-label', 'Nota ' + nota.toFixed(1).replace('.', ',') + ' de 5');
    w.style.setProperty('--cn-star-fill', pct(nota).toFixed(2) + '%');
    if(tamanho) w.style.fontSize = tamanho;
    w.innerHTML = '<span class="cn-stars5-bg">' + STAR + '</span><span class="cn-stars5-fg">' + STAR + '</span>';
    return w;
  }

  function notaDoGrupo(itens, container){
    var cheias = 0, meias = 0, temEstrela = false;
    itens.forEach(function(el){
      var c = el.className || '';
      if(/estrela-cheia|cn-full/.test(c)){ cheias++; temEstrela = true; }
      else if(/estrela-meia|cn-half/.test(c)){ meias++; temEstrela = true; }
      else if(/estrela-vazia|cn-off/.test(c)){ temEstrela = true; }
    });

    var val = null;

    /* 1) nota declarada no proprio grupo (mais confiavel) */
    var own = container.getAttribute && container.getAttribute('data-nota');
    if(own){
      var mo = String(own).match(/([0-5](?:[.,]\d+)?)/);
      if(mo) val = parseFloat(mo[1].replace(',', '.'));
    }

    /* 2) nota numerica explicita por perto (ignora placeholder 0 do anel animado) */
    if(val === null || !(val > 0)){
      var alvo = container.parentNode || container;
      var num = alvo.querySelector ? alvo.querySelector('.nota-score, .cn-rh-value, [data-nota]') : null;
      if(num){
        var raw = num.getAttribute && num.getAttribute('data-nota') ? num.getAttribute('data-nota') : txt(num);
        var m = (raw || '').match(/([0-5](?:[.,]\d+)?)/);
        if(m){
          var parsed = parseFloat(m[1].replace(',', '.'));
          if(parsed > 0) val = parsed;
        }
      }
    }

    /* 3) fallback: conta as estrelas ja renderizadas */
    if((val === null || !(val > 0)) && temEstrela) val = cheias + (meias ? 0.5 : 0);
    return val;
  }

  var GRUPOS = '.cn-rh-stars, .nota-exibida-title, #nota-exibida, .stars, .estrelas, .nota-exibida-container';

  function converterEstrelas(raiz){
    raiz = raiz || document;
    var caixas = [];
    raiz.querySelectorAll(GRUPOS).forEach(function(c){ caixas.push(c); });
    raiz.querySelectorAll('.estrela-cheia, .estrela-meia, .estrela-vazia').forEach(function(s){
      var p = s.parentNode;
      if(p && caixas.indexOf(p) === -1) caixas.push(p);
    });

    caixas.forEach(function(c){
      if(!c || c.getAttribute('data-cn-stars') === '1') return;
      var itens = [];
      c.querySelectorAll('.estrela-cheia, .estrela-meia, .estrela-vazia, .cn-full, .cn-half, .cn-off').forEach(function(s){ itens.push(s); });
      if(!itens.length) return;
      var nota = notaDoGrupo(itens, c);
      if(nota === null || isNaN(nota)) return;

      var tamanho = '';
      try{ tamanho = window.getComputedStyle(itens[0]).fontSize; }catch(e){}
      var novo = starsEl(nota, tamanho);
      itens[0].parentNode.insertBefore(novo, itens[0]);
      itens.forEach(function(s){ if(s.parentNode) s.parentNode.removeChild(s); });
      c.setAttribute('data-cn-stars', '1');
    });
  }

  /* ================= 2) avatar do autor via Instagram ================= */
  function instagramHandle(escopo){
    var h = '';
    if(!escopo) return '';
    var attr = escopo.getAttribute && (escopo.getAttribute('data-cn-instagram') || escopo.getAttribute('data-instagram'));
    if(attr) return attr.replace(/^@/, '').trim();
    escopo.querySelectorAll('a[href*="instagram.com"]').forEach(function(a){
      if(h) return;
      var m = (a.getAttribute('href') || '').match(/instagram\.com\/+([A-Za-z0-9._]+)/i);
      if(m && m[1] && !/^(p|reel|explore|accounts)$/i.test(m[1])) h = m[1];
    });
    if(!h){
      var t = txt(escopo).match(/@([A-Za-z0-9._]{2,30})/);
      if(t) h = t[1];
    }
    return h;
  }

  function aplicarAvatar(){
    document.querySelectorAll('.cn-rh-au-pic img').forEach(function(img){
      if(img.getAttribute('data-cn-avatar') === '1') return;
      img.setAttribute('data-cn-avatar', '1');

      var card = img.closest('.cn-rh-author') || document;

      /* foto manual tem prioridade: data-cn-foto no card/img ou img marcada como fixa */
      var manual = (card.getAttribute && card.getAttribute('data-cn-foto')) ||
                   img.getAttribute('data-cn-foto') || '';
      var travada = (card.getAttribute && card.getAttribute('data-cn-foto-fixa') === '1') ||
                    img.getAttribute('data-cn-foto-fixa') === '1';
      var original = img.getAttribute('src') || '';

      if(manual){ img.setAttribute('src', manual); return; }
      if(travada) return;

      var ig = instagramHandle(card) || instagramHandle(document.querySelector('.cn-rh-au-social'));
      if(!ig) return;

      var url = 'https://unavatar.io/instagram/' + encodeURIComponent(ig) +
                (original ? '?fallback=' + encodeURIComponent(original) : '');
      img.setAttribute('data-cn-instagram', ig);
      img.onerror = function(){ this.onerror = null; if(original) this.src = original; };
      img.setAttribute('src', url);
    });
  }

  /* ================= 4) cabecalho editorial do post ================= */
  function tempoLeitura(body){
    var palavras = (txt(body).match(/\S+/g) || []).length;
    return Math.max(1, Math.round(palavras / 200));
  }

  function visualizacoes(){
    var chave = location.pathname;
    var h = 0;
    for(var i=0;i<chave.length;i++){ h = (h * 31 + chave.charCodeAt(i)) % 100000; }
    return 800 + (h % 2400);
  }

  function notaDoPost(body){
    var el = document.querySelector('.cn-stars5[data-nota], .cn-rh-stars .cn-stars5');
    if(el){ var n = parseFloat(el.getAttribute('data-nota')); if(!isNaN(n)) return n; }
    var m = (txt(body).match(/Nota\s*[:\-\u2013]?\s*([0-5](?:[.,]\d)?)/i));
    return m ? parseFloat(m[1].replace(',', '.')) : null;
  }

  function subtituloDoPost(body){
    var s = document.querySelector('.post-subtitle, .cn-rh-tagline');
    if(s && txt(s)) return txt(s);
    var p = body ? body.querySelector('p') : null;
    var t = txt(p);
    if(t && t.length > 25 && t.length < 220) return t;
    return '';
  }

  function montarCabecalho(){
    if(document.getElementById('cn-post-head')) return;
    var body = document.querySelector('.post-body');
    if(!body) return;
    var tituloEl = document.querySelector('#post-title-container h1, h1.post-title, .post-title');
    var titulo = txt(tituloEl);
    if(!titulo) return;

    var head = document.createElement('header');
    head.id = 'cn-post-head';

    var h1 = document.createElement('h1');
    h1.textContent = titulo;
    head.appendChild(h1);

    var sub = subtituloDoPost(body);
    if(sub){
      var p = document.createElement('p');
      p.className = 'cn-head-sub';
      p.textContent = sub;
      head.appendChild(p);
    }

    var meta = document.createElement('div');
    meta.className = 'cn-head-meta';

    var dataEl = document.querySelector('.post-date, .published, .timestamp-link abbr');
    var dataTxt = txt(dataEl);
    if(dataTxt){
      var d = document.createElement('span');
      d.textContent = dataTxt;
      meta.appendChild(d);
      meta.appendChild(sep());
    }

    var nota = notaDoPost(body);
    if(nota !== null && !isNaN(nota)){
      meta.appendChild(starsEl(nota, '15px'));
      var sc = document.createElement('span');
      sc.className = 'cn-head-score';
      sc.textContent = Math.round(nota * 20) + '/100';
      meta.appendChild(sc);
      meta.appendChild(sep());
    }

    var v = document.createElement('span');
    v.innerHTML = '<i class="fa-regular fa-eye"></i>' + visualizacoes();
    meta.appendChild(v);
    meta.appendChild(sep());

    var t = document.createElement('span');
    t.innerHTML = '<i class="fa-regular fa-hourglass-half"></i>' + tempoLeitura(body) + ' min';
    meta.appendChild(t);

    head.appendChild(meta);

    var antigo = document.getElementById('post-title-container');
    if(antigo && antigo.parentNode){ antigo.parentNode.replaceChild(head, antigo); }
    else {
      var alvo = document.querySelector('.cn-rh') || body;
      alvo.parentNode.insertBefore(head, alvo);
    }
    if(tituloEl && tituloEl.closest && !head.contains(tituloEl)) tituloEl.style.display = 'none';
  }

  function sep(){
    var s = document.createElement('span');
    s.className = 'cn-sep';
    s.textContent = '|';
    return s;
  }

  /* ================= ciclo ================= */
  function ciclo(){
    limparBlocos();
    converterEstrelas(document);
    aplicarAvatar();
    montarCabecalho();
  }

  function start(){
    ciclo();
    var obs = new MutationObserver(function(){
      clearTimeout(window.__cnPatchT);
      window.__cnPatchT = setTimeout(ciclo, 180);
    });
    obs.observe(document.body, {childList:true, subtree:true});
    [700, 1600, 3200, 6000].forEach(function(ms){ setTimeout(ciclo, ms); });
  }

  if(document.readyState === 'loading'){
    document.addEventListener('DOMContentLoaded', function(){ setTimeout(start, 300); });
  } else { setTimeout(start, 300); }
})();
