(function(){
  'use strict';
  var TMDB_KEY_V7 = '0344712bb861098caefcc9a8d67beb09';
  var STAR5 = '\u2605\u2605\u2605\u2605\u2605';

  function txt(el){ return el ? (el.textContent||'').replace(/\s+/g,' ').trim() : ''; }
  function esc(s){ return String(s==null?'':s).replace(/[&<>"']/g, function(c){
    return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c];
  }); }
  function num(v){ var m = String(v==null?'':v).match(/([0-5](?:[.,]\d+)?)/); return m ? parseFloat(m[1].replace(',','.')) : null; }

  /* ============ 2) estrelas exatas pela nota ============ */
  function notaDoCard(card){
    var n = num(card.getAttribute('data-cn-nota'));
    if(n) return n;
    var s = card.querySelector('.cn-rh-stars');
    if(s){ n = num(s.getAttribute('data-nota')); if(n) return n; }
    var p = card.querySelector('.cn-rh-pct');
    if(p){ var mp = txt(p).match(/(\d{1,3})\s*%/); if(mp){ var val = parseFloat(mp[1])/20; if(val > 0) return val; } }
    var v = card.querySelector('.cn-rh-value');
    if(v){ n = num(txt(v)); if(n) return n; }
    return null;
  }

  function pintarEstrelas(w, n){
    var p = Math.max(0, Math.min(100, (n/5)*100));
    w.setAttribute('data-nota', String(n));
    w.style.setProperty('--cn-star-fill', p.toFixed(2) + '%');
    w.setAttribute('aria-label', 'Nota ' + n.toFixed(1).replace('.', ',') + ' de 5');
    if(!w.querySelector('.cn-stars5-bg')){
      w.innerHTML = '<span class="cn-stars5-bg">'+STAR5+'</span><span class="cn-stars5-fg">'+STAR5+'</span>';
    }
  }

  function sincronizarEstrelas(){
    document.querySelectorAll('.cn-rh').forEach(function(card){
      var n = notaDoCard(card);
      if(n === null || isNaN(n) || !(n > 0)) return;
      card.setAttribute('data-cn-nota', String(n));
      var box = card.querySelector('.cn-rh-stars');
      if(box){
        box.setAttribute('data-nota', String(n));
        var w = box.querySelector('.cn-stars5');
        if(!w){
          box.innerHTML = '';
          w = document.createElement('span');
          w.className = 'cn-stars5';
          box.appendChild(w);
        }
        pintarEstrelas(w, n);
      }
    });
    document.querySelectorAll('.cn-stars5').forEach(function(w){
      var n = num(w.getAttribute('data-nota'));
      if(n === null){
        var dono = w.closest('[data-nota]');
        if(dono) n = num(dono.getAttribute('data-nota'));
      }
      if(n === null || isNaN(n)) return;
      pintarEstrelas(w, n);
    });
  }

  /* ============ 3) PRODUCAO na segunda coluna ============ */
  function itemProducao(valor){
    return '<div class="cn-rh-item" data-campo="prod">'+
      '<span class="cn-rh-ico"><i class="fa-solid fa-money-check-dollar"></i></span>'+
      '<span class="cn-rh-txt"><span class="cn-rh-k">Producao</span>'+
      '<span class="cn-rh-v">'+esc(valor)+'</span></span></div>';
  }

  function segundaColuna(card){
    var sheet = card.querySelector('.cn-rh-sheet');
    if(!sheet) return null;
    var cols = sheet.querySelectorAll('.cn-rh-col');
    if(cols.length > 1) return cols[cols.length-1].querySelector('.cn-rh-row') || cols[cols.length-1];
    if(cols.length === 1){
      var nova = document.createElement('div');
      nova.className = 'cn-rh-col';
      nova.innerHTML = '<div class="cn-rh-row is-full"></div>';
      sheet.appendChild(nova);
      return nova.querySelector('.cn-rh-row');
    }
    return sheet.querySelector('.cn-rh-row');
  }

  function inserirProducao(card, nomes){
    if(!nomes || !nomes.length) return;
    if(card.querySelector('.cn-rh-item[data-campo="prod"]')) return;
    var alvo = segundaColuna(card);
    if(!alvo) return;
    alvo.insertAdjacentHTML('beforeend', itemProducao(nomes.join(', ')));
  }

  function buscarProdutores(card){
    if(card.getAttribute('data-cn-prod') === '1') return;
    if(!card.querySelector('.cn-rh-sheet')) return;
    card.setAttribute('data-cn-prod', '1');
    var titulo = txt(card.querySelector('.cn-rh-title'));
    var id = card.getAttribute('data-cn-obra-id');
    var tipo = card.getAttribute('data-cn-obra-tipo') || 'movie';

    function credits(tp, ident){
      return fetch('https://api.themoviedb.org/3/'+tp+'/'+ident+'/credits?api_key='+TMDB_KEY_V7+'&language=pt-BR')
        .then(function(r){ return r.json(); })
        .then(function(c){
          var crew = c.crew || [];
          var nomes = [];
          ['Producer','Executive Producer','Co-Producer','Associate Producer'].forEach(function(job){
            crew.forEach(function(p){ if(p.job === job && nomes.indexOf(p.name) === -1) nomes.push(p.name); });
          });
          if(!nomes.length){
            crew.forEach(function(p){ if(/produc/i.test(p.job||'') && nomes.indexOf(p.name) === -1) nomes.push(p.name); });
          }
          inserirProducao(card, nomes.slice(0,4));
        });
    }

    if(id){ credits(tipo, id).catch(function(){}); return; }
    if(!titulo) return;
    fetch('https://api.themoviedb.org/3/search/multi?api_key='+TMDB_KEY_V7+'&language=pt-BR&include_adult=false&query='+encodeURIComponent(titulo))
      .then(function(r){ return r.json(); })
      .then(function(d){
        var it = (d.results||[]).filter(function(x){ return x.media_type !== 'person'; })[0];
        if(!it) return;
        return credits(it.media_type === 'tv' ? 'tv' : 'movie', it.id);
      }).catch(function(){});
  }

  /* ============ 4) traducao fiel do tn-content ============ */
  function pareceIngles(s){
    if(!s || s.length < 40) return false;
    var t = ' ' + s.toLowerCase() + ' ';
    var en = (t.match(/ (the|and|of|with|that|will|from|about|which|been|they|their|this|has|have|was|were|for|according) /g) || []).length;
    var pt = (t.match(/ (que|com|para|uma|dos|das|nao|mais|como|sobre|foi|sera|pelo|pela|ele|ela|isso|entao) /g) || []).length;
    return en >= 3 && en > pt;
  }

  function traduzirLote(trechos){
    var joined = trechos.join('\n@@@\n');
    var url = 'https://translate.googleapis.com/translate_a/single?client=gtx&sl=auto&tl=pt-BR&dt=t&q=' + encodeURIComponent(joined);
    return fetch(url).then(function(r){ return r.json(); }).then(function(d){
      var full = (d[0]||[]).map(function(x){ return x[0]; }).join('');
      var partes = full.split(/\s*@@@\s*/);
      if(partes.length !== trechos.length) throw new Error('desalinhado');
      return partes;
    });
  }

  function traduzirConteudo(box){
    if(!box || box.getAttribute('data-cn-tr') === '1') return;
    var nos = [], walker = document.createTreeWalker(box, NodeFilter.SHOW_TEXT, null, false), n;
    while((n = walker.nextNode())){
      var v = (n.nodeValue||'').trim();
      if(v.length > 2 && !/^[\d\W]+$/.test(v)) nos.push(n);
    }
    if(!nos.length) return;
    var amostra = nos.map(function(x){ return x.nodeValue; }).join(' ').slice(0, 1200);
    box.setAttribute('data-cn-tr', '1');
    if(!pareceIngles(amostra)) return;

    var lote = nos.slice(0, 120);
    traduzirLote(lote.map(function(x){ return x.nodeValue.trim(); })).then(function(res){
      res.forEach(function(t, i){ if(t) lote[i].nodeValue = t; });
    }).catch(function(){ box.removeAttribute('data-cn-tr'); });
  }

  function limparSelos(){
    document.querySelectorAll('.tn-traduzido').forEach(function(el){
      if(el.parentNode) el.parentNode.removeChild(el);
    });
  }

  function varrerTrendNews(){
    limparSelos();
    document.querySelectorAll('.tn-content, #tnContent').forEach(traduzirConteudo);
  }

  /* ============ ciclo ============ */
  function ciclo(){
    sincronizarEstrelas();
    document.querySelectorAll('.cn-rh').forEach(buscarProdutores);
    varrerTrendNews();
  }

  function start(){
    ciclo();
    var obs = new MutationObserver(function(){
      clearTimeout(window.__cnV7T);
      window.__cnV7T = setTimeout(ciclo, 220);
    });
    obs.observe(document.documentElement, {childList:true, subtree:true});
    [600, 1500, 3000, 6000].forEach(function(ms){ setTimeout(ciclo, ms); });
  }

  if(document.readyState === 'loading'){
    document.addEventListener('DOMContentLoaded', function(){ setTimeout(start, 450); });
  } else { setTimeout(start, 450); }
})();
